import json, re, sys

# Import the lypning modules
sys.path.insert(0, "src")
from lypning import conformance as cf
from lypning.corpus import Entry


def find_files(directory, recursive):
    """Find all files under directory recursively."""
    import os.path

    results = []

    def _walk(d):
        try:
            entries = list(os.listdir(d))
        except OSError:
            return
        for entry in entries:
            path = d + "/" + entry
            if os.path.isdir(path):
                if recursive:
                    _walk(path)
            else:
                results.append(path)

    _walk(directory)
    return sorted(results)


