import json, os, re, sys

def _walk_dir(root):
    """Replace glob.glob('**', recursive=True) with a deterministic walk.
       Uses sorted() so the result is reproducible."""
    files = []
    for dirpath, dirnames, filenames in os.walk(root):
        # sort both lists so traversal order is deterministic
        dirnames.sort()
        for fn in sorted(filenames):
            if fn.endswith('.jsonl'):
                files.append(os.path.join(dirpath, fn))
    return sorted(files)

