# We need to parse JSONL more carefully. Let's use a simpler approach:
# Since we can't import json, we'll manually extract the "program" field.

def _extract_program_from_jsonl(line):
    # Find "program": and then extract the string value
    idx = line.find('"program"')
    if idx == -1:
        return ''
    idx2 = line.find(':', idx + 9)
    if idx2 == -1:
        return ''
    idx3 = idx2 + 1
    # Skip whitespace
    while idx3 < len(line) and line[idx3] in ' \t\r\n':
        idx3 += 1
    if idx3 >= len(line) or line[idx3] != '"':
        return ''
    idx4 = idx3 + 1
    result = []
    i = idx4
    while i < len(line):
        ch = line[i]
        if ch == '\\':
            if i + 1 < len(line):
                nxt = line[i+1]
                if nxt == 'n':
                    result.append('\n')
                elif nxt == 't':
                    result.append('\t')
                elif nxt == 'r':
                    result.append('\r')
                elif nxt == '\\':
                    result.append('\\')
                elif nxt == '"':
                    result.append('"')
                elif nxt == '/':
                    result.append('/')
                elif nxt == 'b':
                    result.append('\b')
                elif nxt == 'f':
                    result.append('\f')
                elif nxt == 'u' and i + 5 < len(line):
                    hexcode = line[i+2:i+6]
                    try:
                        cp = int(hexcode, 16)
                        result.append(chr(cp))
                    except:
                        result.append(ch)
                    i += 4
                else:
                    result.append(ch)
                i += 1
            else:
                result.append(ch)
                i += 1
        elif ch == '"':
            break
        else:
            result.append(ch)
            i += 1
    return ''.join(result)


# Now let's implement the conformance check functions from lypning
# We need to replicate cf._IMPORTS_RANDOM.search and cf.is_seeded_stream

_IMPORTS_RANDOM_PATTERN = r'from\s+random\s+import|import\s+random'


def _imports_random_search(program):
    return bool(re.search(_IMPORTS_RANDOM_PATTERN, program))


def _is_seeded_stream(entry):
    p = entry.program
    # Check if random module is used AND seeded
    if not re.search(_IMPORTS_RANDOM_PATTERN, p):
        return False
    # Check for seed usage patterns
    # Seeded means random.seed( is called OR random.getstate() etc. indicate seeding
    if re.search(r'random\.seed\s*\(', p):
        return True
    if re.search(r'\.seed\s*\(', p):
        return True
    # Other indicators of seeded stream
    if re.search(r'seeded', p, re.IGNORECASE):
        return True
    return False


