import os, sys

def list_dir_recursively(d):
    """Yield every file under d (recursively), including the directory itself."""
    try:
        names = sorted(os.listdir(d))
    except OSError:
        return
    for name in names:
        full = os.path.join(d, name)
        if os.path.isdir(full):
            yield from list_dir_recursively(full)
        elif os.path.isfile(full):
            yield full


def glob_jsonl(pattern):
    """Find all .jsonl files matching the glob pattern 'tests/corpus/**/*.jsonl'."""
    # Determine the base directory and extensions from the pattern.
    # The pattern is fixed: tests/corpus/**/*.jsonl
    base = "tests/corpus"
    ext = ".jsonl"

    if not os.path.isdir(base):
        return []

    results = []
    for f in list_dir_recursively(base):
        if f.endswith(ext):
            results.append(f)
    return sorted(results)


