class Session:
    def __init__(self, session_id):
        self.session = session_id

def collect():
    sessions = set()
    sightings_dir = Path('tests/corpus/sightings')
    if not sightings_dir.exists():
        return []
    for p in sorted(sightings_dir.glob('*.jsonl')):
        with open(p) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    record = json.loads(line)
                    # Try to extract session from the record
                    if isinstance(record, dict):
                        sid = None
                        for key in ('session', 'session_id', 'sessionId', 'sid'):
                            if key in record:
                                sid = record[key]
                                break
                        if sid is None:
                            # Look for nested keys
                            for v in record.values():
                                if isinstance(v, dict):
                                    for key2 in ('session', 'session_id', 'sessionId', 'sid'):
                                        if key2 in v:
                                            sid = v[key2]
                                            break
                                if sid is not None:
                                    break
                        if sid is not None:
                            sessions.add(sid)
                except json.JSONDecodeError:
                    pass

    result = []
    for sid in sorted(sessions):
        result.append(Session(sid))
    return result

