def check_seed_static(program):
    """Statically determine if the program seeds the random stream."""
    try:
        tree = ast.parse(program)
    except SyntaxError:
        return False, False

    # Track imports
    imports = {}  # name -> actual module
    from_imports = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                imports[alias.asname or alias.name.split('.')[0]] = alias.name
        elif isinstance(node, ast.ImportFrom):
            if node.module == 'random':
                for alias in node.names:
                    if alias.name == '*':
                        from_imports.add('*')
                    else:
                        imports[alias.asname or alias.name] = 'random.' + alias.name

    seeded = False

    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            func = node.func

            # Direct call: random.seed(...)
            if isinstance(func, ast.Attribute) and func.attr == 'seed':
                target = func.value
                if isinstance(target, ast.Name) and target.id in imports and imports[target.id].split('.')[0] == 'random':
                    seeded = True
                    break

            # Call: seed(...) with from random import *
            if isinstance(func, ast.Name) and func.id == 'seed' and '*' in from_imports:
                seeded = True
                break

            # getattr(random, 'seed')(1) pattern
            if isinstance(func, ast.Call):
                inner_func = func.func
                if isinstance(inner_func, ast.Name) and inner_func.id == 'getattr':
                    if len(func.args) >= 2:
                        first_arg = func.args[0]
                        second_arg = func.args[1]
                        if isinstance(first_arg, ast.Name) and first_arg.id in imports and imports[first_arg.id].split('.')[0] == 'random':
                            if isinstance(second_arg, ast.Constant) and second_arg.value == 'seed':
                                seeded = True
                                break

    return seeded

