def find_word_before(s, word="seed", before_words=("import", "from"), after=None):
    i = 0
    n = len(s)
    while True:
        idx = s.find(word, i)
        if idx == -1:
            break
        # Check that the character right after `word` is one of ( [ space tab \n etc. (i.e., it's not part of a longer identifier)
        end_char_idx = idx + len(word)
        valid_after = True
        if end_char_idx < n:
            c = s[end_char_idx]
            if c.isalnum() or c == "_":
                valid_after = False
        else:
            valid_after = True

        if valid_after:
            # Check that the char before word is not a letter, digit, underscore, or dot
            start_ok = True
            if idx > 0:
                prev_c = s[idx - 1]
                if prev_c.isalnum() or prev_c in ("_", "."):
                    start_ok = False
            if start_ok:
                return True
        i = idx + 1
    return False


