def has_bare_seed_call(s):
    """Check if s contains a call to 'seed(' where 'seed' is not preceded by '.' or a word character."""
    i = 0
    n = len(s)
    while True:
        idx = s.find("seed(", i)
        if idx == -1:
            # Also check for "seed" followed by whitespace then "("
            idx2 = s.find("seed ", i)
            if idx2 == -1:
                # Try other whitespace: tab, newline
                found_any = False
                for ws in ("\t", "\n"):
                    idx3 = s.find("seed" + ws, i)
                    if idx3 != -1:
                        # Now need to verify the next non-whitespace char is '('
                        j = idx3 + len("seed")
                        while j < n and s[j] in " \t\n\r":
                            j += 1
                        if j < n and s[j] == "(":
                            # Found a candidate at position idx3
                            # Check character before "seed"
                            ok = True
                            if idx3 > 0:
                                prev_c = s[idx3 - 1]
                                if prev_c.isalnum() or prev_c in ("_", "."):
                                    ok = False
                            if ok:
                                return True
                        i = max(idx3 + 1, i + 1)
                        found_any = True
                    else:
                        i = max(i + 1, idx3 + 1) if idx3 != -1 else i + 1
                if not found_any and idx2 == -1:
                    # No more occurrences
                    return False
                # Continue scanning from updated i
                if i <= idx2 and idx2 != -1:
                    i = idx2 + 1
                continue

        # Check the character before "seed"
        ok = True
        if idx > 0:
            prev_c = s[idx - 1]
            if prev_c.isalnum() or prev_c in ("_", "."):
                ok = False
        if ok:
            return True
        i = idx + 1


