# Define a simple JSON loader to avoid importing json (only os and sys allowed)
def json_loads_line(line):
    # Simple recursive descent parser for the expected JSONL format
    # We'll parse the basic structure expected: objects with string keys and values
    # which may be strings, numbers, booleans, null, arrays, or objects.

    def skip_whitespace(s, i):
        while i < len(s) and s[i] in ' \t\n\r':
            i += 1
        return i

    def parse_value(s, i):
        i = skip_whitespace(s, i)
        if i >= len(s):
            raise ValueError("Unexpected end of input")

        c = s[i]
        if c == '{':
            return parse_object(s, i)
        elif c == '[':
            return parse_array(s, i)
        elif c == '"':
            return parse_string(s, i)
        elif c == 't' or c == 'f' or c == 'n':
            return parse_literal(s, i)
        else:
            return parse_number(s, i)

    def parse_object(s, i):
        result = {}
        i += 1  # skip {
        i = skip_whitespace(s, i)
        if i < len(s) and s[i] == '}':
            return result, i + 1

        while True:
            i = skip_whitespace(s, i)
            if i >= len(s):
                raise ValueError("Unterminated object")
            if s[i] != '"':
                raise ValueError("Expected string key")

            key, i = parse_string(s, i)
            i = skip_whitespace(s, i)
            if i >= len(s) or s[i] != ':':
                raise ValueError("Expected colon")
            i += 1

            value, i = parse_value(s, i)
            result[key] = value

            i = skip_whitespace(s, i)
            if i >= len(s):
                break
            if s[i] == ',':
                i += 1
                continue
            elif s[i] == '}':
                return result, i + 1
            else:
                raise ValueError("Expected comma or }")

    def parse_array(s, i):
        result = []
        i += 1  # skip [
        i = skip_whitespace(s, i)
        if i < len(s) and s[i] == ']':
            return result, i + 1

        while True:
            value, i = parse_value(s, i)
            result.append(value)

            i = skip_whitespace(s, i)
            if i >= len(s):
                break
            if s[i] == ',':
                i += 1
                continue
            elif s[i] == ']':
                return result, i + 1
            else:
                raise ValueError("Expected comma or ]")

    def parse_string(s, i):
        if s[i] != '"':
            raise ValueError("Expected string")
        i += 1
        result = []
        while i < len(s):
            c = s[i]
            if c == '\\':
                i += 1
                if i >= len(s):
                    break
                esc = s[i]
                if esc == '"':
                    result.append('"')
                elif esc == '\\':
                    result.append('\\')
                elif esc == '/':
                    result.append('/')
                elif esc == 'b':
                    result.append('\b')
                elif esc == 'f':
                    result.append('\f')
                elif esc == 'n':
                    result.append('\n')
                elif esc == 'r':
                    result.append('\r')
                elif esc == 't':
                    result.append('\t')
                elif esc == 'u':
                    hex_str = s[i+1:i+5]
                    code_point = int(hex_str, 16)
                    result.append(chr(code_point))
                    i += 4
                else:
                    result.append(esc)
                i += 1
            elif c == '"':
                return ''.join(result), i + 1
            else:
                result.append(c)
                i += 1
        raise ValueError("Unterminated string")

    def parse_number(s, i):
        start = i
        if i < len(s) and s[i] == '-':
            i += 1
        while i < len(s) and s[i].isdigit():
            i += 1
        if i < len(s) and s[i] == '.':
            i += 1
            while i < len(s) and s[i].isdigit():
                i += 1
        if i < len(s) and s[i] in 'eE':
            i += 1
            if i < len(s) and s[i] in '+-':
                i += 1
            while i < len(s) and s[i].isdigit():
                i += 1

        num_str = s[start:i]
        try:
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                return float(num_str), i
            else:
                return int(num_str), i
        except ValueError:
            return None, i

    def parse_literal(s, i):
        if s.startswith('true', i):
            return True, i + 4
        elif s.startswith('false', i):
            return False, i + 5
        elif s.startswith('null', i):
            return None, i + 4
        else:
            raise ValueError("Unknown literal")

    result, _ = parse_value(line, 0)
    return result


