def has_bare_seed_call(s):
    # Check if there's a bare seed call: 'seed' not preceded by '.' or word character
    # Use regex without lookbehind: match (?:^|[^.\w])seed\s*\(
    return re.search(r'(?:^|[^.\w])seed\s*\(', s) is not None


