def json_parse_value(s, i):
    """Parse a JSON value starting at position i. Returns (value, new_i)."""
    s = s.strip()
    if i >= len(s):
        return None, i
    c = s[i]
    if c == '"':
        # String
        j = i + 1
        buf = []
        while j < len(s):
            ch = s[j]
            if ch == '\\':
                j += 1
                if j < len(s):
                    esc = s[j]
                    if esc == '"': buf.append('"')
                    elif esc == '\\': buf.append('\\')
                    elif esc == '/': buf.append('/')
                    elif esc == 'n': buf.append('\n')
                    elif esc == 't': buf.append('\t')
                    elif esc == 'r': buf.append('\r')
                    elif esc == 'b': buf.append('\b')
                    elif esc == 'f': buf.append('\f')
                    elif esc == 'u':
                        hexs = s[j+1:j+5]
                        code = int(hexs, 16)
                        buf.append(chr(code))
                        j += 4
                    else:
                        buf.append(esc)
                j += 1
            elif ch == '"':
                break
            else:
                buf.append(ch)
                j += 1
        return ''.join(buf), j + 1
    elif c in '0123456789-' or c == '-':
        # Number - find end
        j = i
        while j < len(s) and s[j] in '0123456789.eE+-':
            j += 1
        num_str = s[i:j]
        try:
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                return float(num_str), j
            else:
                return int(num_str), j
        except:
            return None, j
    elif s[i:i+4] == 'true':
        return True, i + 4
    elif s[i:i+5] == 'false':
        return False, i + 5
    elif s[i:i+4] == 'null':
        return None, i + 4
    elif c == '{':
        # Object
        obj = {}
        j = i + 1
        # Skip whitespace
        while j < len(s) and s[j] in ' \t\n\r':
            j += 1
        if j < len(s) and s[j] == '}':
            return {}, j + 1
        while j < len(s):
            # Parse key
            while j < len(s) and s[j] in ' \t\n\r':
                j += 1
            if j >= len(s) or s[j] != '"':
                break
            key, j = json_parse_value(s, j)
            # Expect colon
            while j < len(s) and s[j] in ' \t\n\r':
                j += 1
            if j >= len(s) or s[j] != ':':
                break
            j += 1
            while j < len(s) and s[j] in ' \t\n\r':
                j += 1
            val, j = json_parse_value(s, j)
            obj[key] = val
            # Expect comma or }
            while j < len(s) and s[j] in ' \t\n\r':
                j += 1
            if j >= len(s):
                break
            if s[j] == ',':
                j += 1
                continue
            elif s[j] == '}':
                j += 1
                break
            else:
                break
        return obj, j
    elif c == '[':
        # Array
        arr = []
        j = i + 1
        while j < len(s) and s[j] in ' \t\n\r':
            j += 1
        if j < len(s) and s[j] == ']':
            return [], j + 1
        while j < len(s):
            val, j = json_parse_value(s, j)
            arr.append(val)
            while j < len(s) and s[j] in ' \t\n\r':
                j += 1
            if j >= len(s):
                break
            if s[j] == ',':
                j += 1
                continue
            elif s[j] == ']':
                j += 1
                break
            else:
                break
        return arr, j
    return None, i


