def _parse_args(s):
    """Parse the arguments inside re.findall(...) handling nested parens and strings."""
    args = []
    depth = 0
    current = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == "'":
            # Find end of string
            j = i + 1
            while j < len(s) and s[j] != "'":
                if s[j] == '\\':
                    j += 1
                j += 1
            # s[j] should be the closing quote
            args_part = s[i:j+1]
            current.append(args_part)
            i = j + 1
            continue
        elif c == '(':
            depth += 1
            current.append(c)
            i += 1
        elif c == ')':
            depth -= 1
            if depth == 0:
                # End of argument
                arg_str = ''.join(current)
                args.append(arg_str.strip())
                current = []
                i += 1
            else:
                current.append(c)
                i += 1
        elif c == ',' and depth == 0:
            arg_str = ''.join(current).strip()
            if arg_str:
                args.append(arg_str)
            current = []
            i += 1
        else:
            current.append(c)
            i += 1

    if current:
        arg_str = ''.join(current).strip()
        if arg_str:
            args.append(arg_str)

