def make_safe_eval():
    """Create a safe eval that only allows certain operations."""

    # Names we allow
    allowed_names = {
        're': __import__('re'),
        'len': len,
        'print': print,
        'int': int,
        'str': str,
        'repr': repr,
        'True': True,
        'False': False,
        'None': None,
    }

    def evaluate(node):
        if isinstance(node, ast.Expression):
            return evaluate(node.body)
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            if node.id in allowed_names:
                return allowed_names[node.id]
            else:
                raise NameError(f"Name '{node.id}' not found")
        elif isinstance(node, ast.Attribute):
            value = evaluate(node.value)
            attr = getattr(value, node.attr)
            return attr
        elif isinstance(node, ast.Call):
            func = evaluate(node.func)
            args = [evaluate(a) for a in node.args]
            kwargs = {}
            for kw in node.keywords:
                if kw.arg is None:
                    raise ValueError("Keyword argument expansion not supported")
                kwargs[kw.arg] = evaluate(kw.value)
            return func(*args, **kwargs)
        elif isinstance(node, ast.BinOp):
            left = evaluate(node.left)
            right = evaluate(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Pow):
                return left ** right
            elif isinstance(node.op, ast.FloorDiv):
                return left // right
            elif isinstance(node.op, ast.Mod):
                return left % right
            else:
                raise TypeError(f"Unsupported operator: {type(node.op).__name__}")
        elif isinstance(node, ast.UnaryOp):
            operand = evaluate(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
            elif isinstance(node.op, ast.UAdd):
                return +operand
            elif isinstance(node.op, ast.Not):
                return not operand
            else:
                raise TypeError(f"Unsupported unary operator: {type(node.op).__name__}")
        elif isinstance(node, ast.Compare):
            left = evaluate(node.left)
            for comparator, ope in zip(node.comparators, node.ops):
                right = evaluate(comparator)
                if isinstance(ope, ast.Eq):
                    result = left == right
                elif isinstance(ope, ast.NotEq):
                    result = left != right
                elif isinstance(ope, ast.Lt):
                    result = left < right
                elif isinstance(ope, ast.LtE):
                    result = left <= right
                elif isinstance(ope, ast.Gt):
                    result = left > right
                elif isinstance(ope, ast.GtE):
                    result = left >= right
                elif isinstance(ope, ast.Is):
                    result = left is right
                elif isinstance(ope, ast.IsNot):
                    result = left is not right
                elif isinstance(ope, ast.In):
                    result = left in right
                elif isinstance(ope, ast.NotIn):
                    result = left not in right
                else:
                    raise TypeError(f"Unsupported comparison: {type(ope).__name__}")
                if not result:
                    return False
                left = right
            return True
        elif isinstance(node, ast.IfExp):
            test = evaluate(node.test)
            if test:
                return evaluate(node.body)
            else:
                return evaluate(node.orelse)
        elif isinstance(node, ast.List):
            return [evaluate(el) for el in node.elts]
        elif isinstance(node, ast.Tuple):
            return tuple(evaluate(el) for el in node.elts)
        elif isinstance(node, ast.Dict):
            d = {}
            for key, value in zip(node.keys, node.values):
                k = evaluate(key) if key is not None else None
                v = evaluate(value)
                d[k] = v
            return d
        elif isinstance(node, ast.Set):
            return set(evaluate(el) for el in node.elts)
        elif isinstance(node, ast.JoinedStr):
            # f-string - try to handle
            parts = []
            for value in node.values:
                if isinstance(value, ast.FormattedValue):
                    parts.append(str(evaluate(value.value)))
                elif isinstance(value, ast.Constant):
                    parts.append(value.value)
                else:
                    raise ValueError("Unsupported f-string element")
            return ''.join(parts)
        else:
            raise ValueError(f"Unsupported expression type: {type(node).__name__}")

    def safe_eval(expr_string):
        tree = ast.parse(expr_string, mode='eval')
        return evaluate(tree)

    return safe_eval

