                if nxt == 'v': result.append('\v'); i += 2; continue
                if nxt == 'b': result.append('\b'); i += 2; continue
                if nxt == 'a': result.append('\a'); i += 2; continue
                if nxt == '\\': result.append('\\'); i += 2; continue
                if nxt == "'": result.append("'"); i += 2; continue
                if nxt == '"': result.append('"'); i += 2; continue
                if nxt == '0': result.append('\0'); i += 2; continue
                if nxt == 'x' and i+3 < len(body):
