import sys

print("python", sys.version.split()[0])

B64A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"


def _strict_validate(s):
    L = len(s)
    for i in range(L):
        c = s[i:i + 1]
        if c == "=":
            if i < L - 4 or any(s[j:j + 1] != "=" for j in range(i + 1, L)):
                return False
        elif B64A.find(c) == -1:
            return False
    if L % 4 == 0:
        return True
    if L % 4 == 3:
        n = ord(s[3 * 3 + 1]) & 0xF
        if n > 0:
            return False
    if L % 4 == 1:
        return False
    if L % 4 == 2:
        c0 = B64A.find(s[0:1]); c1 = B64A.find(s[1:2])
        return ((c0 << 2 | (c1 >> 4)) < 256)


def my_b64decode(data, validate):
    data = data.replace(b"\r\n", b"").replace(b"\n", b"").replace(b"\t", b"").replace(b" ", b"")
    if validate:
        try:
            s = data.decode("ascii")
        except UnicodeDecodeError:
            raise ValueError("Non-base64 digit found")
        if not _strict_validate(s):
            raise ValueError("Invalid base64-encoded string: number of data characters ({}).".format(len(s)))
    out = []
    buf = 0
    cnt = 0
    for byte in data:
        c = chr(byte)
        if c == "=":
            continue
        i = B64A.find(c)
        if i < 0:
            continue
        buf = (buf << 6) | i
        cnt += 1
        if cnt == 4:
            out.append((buf >> 16) & 0xFF)
            out.append((buf >> 8) & 0xFF)
            out.append(buf & 0xFF)
            buf = 0
            cnt = 0
    if cnt == 2:
        out.append((buf >> 10) & 0xFF)
    elif cnt == 3:
        out.append((buf >> 16) & 0xFF)
        out.append((buf >> 8) & 0xFF)
    return bytes(out)


