        buf = (buf << 6) | i
        cnt += 1
        if cnt == 4:
            out.append((buf >> 16) & 0xFF)
            out.append((buf >> 8) & 0xFF)
            out.append(buf & 0xFF)
            buf = 0
            cnt = 0
    if cnt == 2:
        out.append((buf >> 10) & 0xFF)
    elif cnt == 3:
        out.append((buf >> 16) & 0xFF)
        out.append((buf >> 8) & 0xFF)
    return bytes(out)


