import binascii

def my_b64decode(data, validate):
    """Mimic base64.b64decode"""
    if isinstance(data, str):
        data = data.encode('latin-1')

    if validate:
        # Strict mode
        try:
            return binascii.a2b_base64(data, strict_mode=True)
        except Exception as e:
            raise type(e)(str(e))
    else:
        # Non-strict: discard non-alphabet characters
        alphabet = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=')
        filtered = bytes(c for c in data if c in alphabet)
        try:
            return binascii.a2b_base64(filtered, strict_mode=False)
        except Exception as e:
            raise type(e)(str(e))

