def _parse_json(s):
    """Minimal JSON parser returning parsed value."""
    pos = [0]

    def skip_ws():
        while pos[0] < len(s) and s[pos[0]] in ' \t\n\r':
            pos[0] += 1

    def parse_value():
        skip_ws()
        if pos[0] >= len(s):
            raise ValueError("unexpected end")
        c = s[pos[0]]
        if c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == '"':
            return parse_string()
        elif c == 't':
            if s[pos[0]:pos[0]+4] == 'true':
                pos[0] += 4
                return True
            raise ValueError("bad token")
        elif c == 'f':
            if s[pos[0]:pos[0]+5] == 'false':
                pos[0] += 5
                return False
            raise ValueError("bad token")
        elif c == 'n':
            if s[pos[0]:pos[0]+4] == 'null':
                pos[0] += 4
                return None
            raise ValueError("bad token")
        else:
            return parse_number()

    def parse_object():
        result = {}
        pos[0] += 1  # skip {
        skip_ws()
        if pos[0] < len(s) and s[pos[0]] == '}':
            pos[0] += 1
            return result
        while True:
            skip_ws()
            if pos[0] >= len(s) or s[pos[0]] != '"':
                raise ValueError("expected string key")
            key = parse_string()
            skip_ws()
            if pos[0] >= len(s) or s[pos[0]] != ':':
                raise ValueError("expected colon")
            pos[0] += 1
            val = parse_value()
            result[key] = val
            skip_ws()
            if pos[0] >= len(s):
                raise ValueError("unexpected end")
            if s[pos[0]] == ',':
                pos[0] += 1
            elif s[pos[0]] == '}':
                pos[0] += 1
                break
            else:
                raise ValueError("expected comma or }")
        return result

    def parse_array():
        result = []
        pos[0] += 1  # skip [
        skip_ws()
        if pos[0] < len(s) and s[pos[0]] == ']':
            pos[0] += 1
            return result
        while True:
            val = parse_value()
            result.append(val)
            skip_ws()
            if pos[0] >= len(s):
                raise ValueError("unexpected end")
            if s[pos[0]] == ',':
                pos[0] += 1
            elif s[pos[0]] == ']':
                pos[0] += 1
                break
            else:
                raise ValueError("expected comma or ]")
        return result

    def parse_string():
        assert s[pos[0]] == '"'
        pos[0] += 1
        chars = []
        while pos[0] < len(s):
            c = s[pos[0]]
            if c == '\\':
                pos[0] += 1
                if pos[0] >= len(s):
                    break
                nc = s[pos[0]]
                if nc == '"':
                    chars.append('"')
                elif nc == '\\':
                    chars.append('\\')
                elif nc == '/':
                    chars.append('/')
                elif nc == 'b':
                    chars.append('\b')
                elif nc == 'f':
                    chars.append('\f')
                elif nc == 'n':
                    chars.append('\n')
                elif nc == 'r':
                    chars.append('\r')
                elif nc == 't':
                    chars.append('\t')
                elif nc == 'u':
                    hexs = s[pos[0]+1:pos[0]+5]
                    try:
                        code = int(hexs, 16)
                        chars.append(chr(code))
                        pos[0] += 4
                    except:
                        raise ValueError("bad unicode escape")
                else:
                    raise ValueError("bad escape")
                pos[0] += 1
            elif c == '"':
                pos[0] += 1
                break
            else:
                chars.append(c)
                pos[0] += 1
        return ''.join(chars)

    def parse_number():
        start = pos[0]
        if pos[0] < len(s) and s[pos[0]] == '-':
            pos[0] += 1
        while pos[0] < len(s) and s[pos[0]].isdigit():
            pos[0] += 1
        if pos[0] < len(s) and s[pos[0]] == '.':
            pos[0] += 1
            while pos[0] < len(s) and s[pos[0]].isdigit():
                pos[0] += 1
        if pos[0] < len(s) and s[pos[0]] in 'eE':
            pos[0] += 1
            if pos[0] < len(s) and s[pos[0]] in '+-':
                pos[0] += 1
            while pos[0] < len(s) and s[pos[0]].isdigit():
                pos[0] += 1
        txt = s[start:pos[0]]
        try:
            if '.' in txt or 'e' in txt or 'E' in txt:
                return float(txt)
            else:
                return int(txt)
        except:
            raise ValueError("bad number: " + txt)

    result = parse_value()
    skip_ws()
    if pos[0] != len(s):
        raise ValueError("trailing data")
    return result


