def _parse_json(s):
    # Minimal JSON parser using only builtins
    return _json_decode(s)


def _json_decode(s):
    s = s.strip()
    val, pos = _json_value(s, 0)
    return val


def _json_value(s, i):
    while i < len(s) and s[i] == " ":
        i += 1
    if i >= len(s):
        raise ValueError("unexpected end")
    c = s[i]
    if c == "{":
        return _json_object(s, i)
    if c == "[":
        return _json_array(s, i)
    if c == '"':
        return _json_string(s, i)
    if c == "t":
        if s[i:i+4] == "true":
            return True, i+4
        raise ValueError("bad literal")
    if c == "f":
        if s[i:i+5] == "false":
            return False, i+5
        raise ValueError("bad literal")
    if c == "n":
        if s[i:i+4] == "null":
            return None, i+4
        raise ValueError("bad literal")
    # number
    j = i
    if j < len(s) and (s[j] == '-' or s[j] == '+'):
        j += 1
    while j < len(s) and (s[j].isdigit() or s[j] in '.eE'):
        j += 1
    numstr = s[i:j]
    if '.' in numstr or 'e' in numstr or 'E' in numstr:
        return float(numstr), j
    return int(numstr), j


def _json_object(s, i):
    obj = {}
    assert s[i] == '{'
    i += 1
    while i < len(s):
        while i < len(s) and s[i] == " ":
            i += 1
        if i >= len(s):
            raise ValueError("unexpected end in object")
        if s[i] == '}':
            i += 1
            break
        key, i = _json_string(s, i)
        while i < len(s) and s[i] == " ":
            i += 1
        if s[i] != ':':
            raise ValueError("expected colon")
        i += 1
        val, i = _json_value(s, i)
        obj[key] = val
        while i < len(s) and s[i] == " ":
            i += 1
        if i < len(s) and s[i] == ',':
            i += 1
    return obj, i


def _json_array(s, i):
    arr = []
    assert s[i] == '['
    i += 1
    while i < len(s):
        while i < len(s) and s[i] == " ":
            i += 1
        if i >= len(s):
            raise ValueError("unexpected end in array")
        if s[i] == ']':
            i += 1
            break
        val, i = _json_value(s, i)
        arr.append(val)
        while i < len(s) and s[i] == " ":
            i += 1
        if i < len(s) and s[i] == ',':
            i += 1
    return arr, i


def _json_string(s, i):
    assert s[i] == '"'
    i += 1
    result = []
    while i < len(s):
        c = s[i]
        if c == '\\':
            i += 1
            ec = s[i]
            if ec == '"':
                result.append('"')
            elif ec == '\\':
                result.append('\\')
            elif ec == '/':
                result.append('/')
            elif ec == 'b':
                result.append('\b')
            elif ec == 'f':
                result.append('\f')
            elif ec == 'n':
                result.append('\n')
            elif ec == 'r':
                result.append('\r')
            elif ec == 't':
                result.append('\t')
            elif ec == 'u':
                hexs = s[i+1:i+5]
                cp = int(hexs, 16)
                result.append(chr(cp))
                i += 4
            else:
                raise ValueError("bad escape")
            i += 1
        elif c == '"':
            i += 1
            break
        else:
            result.append(c)
            i += 1
    return "".join(result), i


