import os, sys

def _skip_ws(s, i):
    while i < len(s) and s[i] in ' \t\r\n':
        i += 1
    return i

def _parse_value(s, i):
    i = _skip_ws(s, i)
    if i >= len(s):
        raise ValueError("unexpected end")
    c = s[i]
    if c == '{':
        obj, i = _parse_object(s, i + 1)
        return obj, i
    if c == '[':
        arr, i = _parse_array(s, i + 1)
        return arr, i
    if c == '"':
        val, i = _parse_string(s, i + 1)
        return val, i
    if c == 't' and s[i:i+4] == 'true':
        return True, i + 4
    if c == 'f' and s[i:i+5] == 'false':
        return False, i + 5
    if c == 'n' and s[i:i+4] == 'null':
        return None, i + 4
    # number
    j = i
    while j < len(s) and s[j] not in ' \t\r\n,}]':
        j += 1
    token = s[i:j]
    try:
        if '.' in token or 'e' in token or 'E' in token:
            return float(token), j
        return int(token), j
    except ValueError:
        raise ValueError("bad number: " + token)

def _parse_string(s, i):
    sb = []
    while i < len(s):
        c = s[i]
        if c == '\\':
            i += 1
            if i >= len(s):
                break
            esc = s[i]
            if esc == 'n': sb.append('\n')
            elif esc == 't': sb.append('\t')
            elif esc == 'r': sb.append('\r')
            elif esc == 'b': sb.append('\b')
            elif esc == 'f': sb.append('\f')
            elif esc == '"': sb.append('"')
            elif esc == '/': sb.append('/')
            elif esc == '\\': sb.append('\\')
            elif esc == 'u':
                hexstr = s[i+1:i+5]
                try:
                    sb.append(chr(int(hexstr, 16)))
                except ValueError:
                    sb.append('?')
                i += 4
            else:
                sb.append(esc)
            i += 1
        elif c == '"':
            return ''.join(sb), i + 1
        else:
            sb.append(c)
            i += 1
    return ''.join(sb), i

def _parse_object(s, i):
    obj = {}
    i = _skip_ws(s, i)
    if i < len(s) and s[i] == '}':
        return obj, i + 1
    while i < len(s):
        key, i = _parse_string(s, i + 1) if s[i] == '"' else ('', i)
        i = _skip_ws(s, i)
        if i < len(s) and s[i] == ':':
            i += 1
        val, i = _parse_value(s, i)
        obj[key] = val
        i = _skip_ws(s, i)
        if i < len(s) and s[i] == ',':
            i += 1
        elif i < len(s) and s[i] == '}':
            return obj, i + 1
        else:
            break
    return obj, i

def _parse_array(s, i):
    arr = []
    i = _skip_ws(s, i)
    if i < len(s) and s[i] == ']':
        return arr, i + 1
    while i < len(s):
        val, i = _parse_value(s, i)
        arr.append(val)
        i = _skip_ws(s, i)
        if i < len(s) and s[i] == ',':
            i += 1
        elif i < len(s) and s[i] == ']':
            return arr, i + 1
        else:
            break
    return arr, i

def parse_json_line(line):
    try:
        val, _ = _parse_value(line, 0)
        return val
    except Exception:
        return None

