def _json_parse(s):
    # This is a simplified JSON parser that handles the structures in JSONL transcript files
    pos = 0
    def skip_ws():
        nonlocal pos
        while pos < len(s) and s[pos] in ' \t\n\r':
            pos += 1
    def parse_value():
        nonlocal pos
        skip_ws()
        if pos >= len(s):
            return None
        c = s[pos]
        if c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == '"':
            return parse_string()
        elif c in ('-', '+') or c.isdigit():
            return parse_number()
        elif s[pos:pos+4] == 'true':
            pos += 4
            return True
        elif s[pos:pos+5] == 'false':
            pos += 5
            return False
        elif s[pos:pos+4] == 'null':
            pos += 4
            return None
        else:
            return None
    def parse_object():
        nonlocal pos
        pos += 1  # skip {
        obj = {}
        skip_ws()
        if pos < len(s) and s[pos] == '}':
            pos += 1
            return obj
        while pos < len(s):
            skip_ws()
            if pos < len(s) and s[pos] == '}':
                pos += 1
                break
            key = parse_string()
            if key is None:
                return obj
            skip_ws()
            if pos < len(s) and s[pos] == ':':
                pos += 1
            val = parse_value()
            obj[key] = val
            skip_ws()
            if pos < len(s) and s[pos] == ',':
                pos += 1
            elif pos < len(s) and s[pos] == '}':
                pos += 1
                break
        return obj
    def parse_array():
        nonlocal pos
        pos += 1  # skip [
        arr = []
        skip_ws()
        if pos < len(s) and s[pos] == ']':
            pos += 1
            return arr
        while pos < len(s):
            val = parse_value()
            arr.append(val)
            skip_ws()
            if pos < len(s) and s[pos] == ',':
                pos += 1
            elif pos < len(s) and s[pos] == ']':
                pos += 1
                break
        return arr
    def parse_string():
        nonlocal pos
        pos += 1  # skip "
        result = []
        while pos < len(s):
            c = s[pos]
            if c == '\\':
                pos += 1
                if pos < len(s):
                    esc = s[pos]
                    if esc == '"': result.append('"')
                    elif esc == '\\': result.append('\\')
                    elif esc == '/': result.append('/')
                    elif esc == 'n': result.append('\n')
                    elif esc == 't': result.append('\t')
                    elif esc == 'r': result.append('\r')
                    elif esc == 'b': result.append('\b')
                    elif esc == 'f': result.append('\f')
                    elif esc == 'u':
                        hexs = s[pos+1:pos+5]
                        try:
                            code = int(hexs, 16)
                            result.append(chr(code))
                            pos += 4
                        except:
                            result.append('\\u' + hexs)
                            pos += 4
                    else: result.append(esc)
                    pos += 1
            elif c == '"':
                pos += 1
                break
            else:
                result.append(c)
                pos += 1
        return ''.join(result)
    def parse_number():
        nonlocal pos
        start = pos
        if pos < len(s) and s[pos] in '-+':
            pos += 1
        while pos < len(s) and (s[pos].isdigit() or s[pos] in '.eE+-'):
            pos += 1
        num_str = s[start:pos]
        try:
            if '.' in num_str or 'e' in num_str or 'E' in num_str:
                return float(num_str)
            return int(num_str)
        except:
            return None
    try:
        result = parse_value()
        return result
    except:
        return None

# Minimal Counter implementation
class MiniCounter(dict):
    def update(self, other):
        if isinstance(other, dict):
            for k, v in other.items():
                self[k] = self.get(k, 0) + v
        elif hasattr(other, 'items'):
            for k, v in other.items():
                self[k] = self.get(k, 0) + v
        else:
            for item in other:
                self[item] = self.get(item, 0) + 1
    def most_common(self, n=None):
        items = sorted(self.items(), key=lambda x: (-x[1], x[0]))
        if n is not None:
            return items[:n]
        return items

