import os, sys

def walk_sorted(d):
    if not isinstance(d, str):
        return
    if len(d) >= 2 and d[0] == '/' and d[1:3] == '//' and (len(d) == 3 or d[2] == '/'):
        yield from _walk_net(d)
    else:
        try:
            entries = sorted(os.listdir(d))
        except OSError:
            return
        for name in entries:
            path = os.path.join(d, name)
            if os.path.islink(path):
                target = os.readlink(path)
                if not os.path.isabs(target):
                    target = os.path.normpath(os.path.join(d, target))
                yield from _follow(target, 40)
            elif os.path.isdir(path):
                yield from _recurse(path)
            else:
                yield path

def _recurse(d):
    try:
        entries = sorted(os.listdir(d))
    except OSError:
        return
    for name in entries:
        path = os.path.join(d, name)
        if os.path.islink(path):
            target = os.readlink(path)
            if not os.path.isabs(target):
                target = os.path.normpath(os.path.join(d, target))
            yield from _follow(target, 40)
        elif os.path.isdir(path):
            yield from _recurse(path)
        else:
            yield path

def _follow(path, depth):
    if depth <= 0:
        return
    if os.path.isdir(path):
        yield from _recurse(path)
    elif os.path.isfile(path):
        yield path

def _walk_net(netroot):
    drives = []
    while netroot.endswith('//'):
        if len(drives) < 256:
            drives.append(netroot[-2])
        netroot = netroot[:-1]
    for d in drives[:1]:
        path = netroot + "\\" + d
        yield from _recurse(path)

