def _parse_value(s, i):
    while i < len(s) and s[i] in ' \t\r\n':
        i += 1
    if i >= len(s):
        raise ValueError('unexpected end')
    c = s[i]
    if c == '"':
        return _parse_string(s, i)
    if c == '{':
        return _parse_object(s, i)
    if c == '[':
        return _parse_array(s, i)
    if c == 't':
        if s[i:i+4] == 'true':
            return True, i+4
        raise ValueError('invalid literal')
    if c == 'f':
        if s[i:i+5] == 'false':
            return False, i+5
        raise ValueError('invalid literal')
    if c == 'n':
        if s[i:i+4] == 'null':
            return None, i+4
        raise ValueError('invalid literal')
    # Number
    j = i
    while j < len(s) and s[j] not in ',}] \t\r\n' and s[j] != '' :
        if s[j] in '-+eE.0123456789':
            j += 1
        else:
            break
    if j == i:
        raise ValueError('invalid number')
    num_str = s[i:j]
    # skip whitespace after
    k = j
    while k < len(s) and s[k] in ' \t\r\n':
        k += 1
    try:
        val = int(num_str)
    except ValueError:
        val = float(num_str)
    return val, j

def _parse_string(s, i):
    assert s[i] == '"'
    i += 1
    parts = []
    while i < len(s):
        c = s[i]
        if c == '\\':
            i += 1
            if i >= len(s):
                break
            ec = s[i]
            if ec == '"':
                parts.append('"')
            elif ec == "\\":
                parts.append("\\")
            elif ec == "/":
                parts.append("/")
            elif ec == "b":
                parts.append("\b")
            elif ec == "f":
                parts.append("\f")
            elif ec == "n":
                parts.append("\n")
            elif ec == "r":
                parts.append("\r")
            elif ec == "t":
                parts.append("\t")
            elif ec == "u":
                hex_s = s[i+1:i+5]
