# Manual json parsing: build a minimal recursive-descent parser
# for the subset of JSON we need (objects, arrays, strings, numbers, booleans, null)

def parse_json(s):
    pos = 0
    n = len(s)
    def skip_ws():
        nonlocal pos
        while pos < n and s[pos] in ' \t\r\n':
            pos += 1
    def parse_value():
        nonlocal pos
        skip_ws()
        if pos >= n:
            return None
        c = s[pos]
        if c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == '"':
            return parse_string()
        elif c == 't':
            # true
            if s[pos:pos+4] == 'true':
                pos += 4
                return True
            return None
        elif c == 'f':
            # false
            if s[pos:pos+5] == 'false':
                pos += 5
                return False
            return None
        elif c == 'n':
            # null
            if s[pos:pos+4] == 'null':
                pos += 4
                return None
            return None
        else:
            return parse_number()
    def parse_object():
        nonlocal pos
        result = {}
        pos += 1  # skip {
        skip_ws()
        if pos < n and s[pos] == '}':
            pos += 1
            return result
        while pos < n:
            skip_ws()
            if pos < n and s[pos] != '"':
                raise ValueError("Expected string key")
            key = parse_string()
            skip_ws()
            if pos >= n or s[pos] != ':':
                raise ValueError("Expected colon")
            pos += 1  # skip :
            val = parse_value()
            result[key] = val
            skip_ws()
            if pos >= n:
                break
            if s[pos] == ',':
                pos += 1
            elif s[pos] == '}':
                pos += 1
                break
            else:
                raise ValueError("Expected comma or }")
        return result
    def parse_array():
        nonlocal pos
        result = []
        pos += 1  # skip [
        skip_ws()
        if pos < n and s[pos] == ']':
            pos += 1
            return result
        while pos < n:
            val = parse_value()
            result.append(val)
            skip_ws()
            if pos >= n:
                break
            if s[pos] == ',':
                pos += 1
            elif s[pos] == ']':
                pos += 1
                break
            else:
                raise ValueError("Expected comma or ]")
        return result
    def parse_string():
        nonlocal pos
        if pos >= n or s[pos] != '"':
            raise ValueError("Expected quote")
        pos += 1  # skip opening "
        chars = []
        while pos < n:
            c = s[pos]
            if c == '\\':
                pos += 1
                if pos >= n:
                    break
                esc = s[pos]
                if esc == '"':
                    chars.append('"')
                elif esc == '\\':
                    chars.append('\\')
                elif esc == '/':
                    chars.append('/')
                elif esc == 'b':
                    chars.append('\b')
                elif esc == 'f':
                    chars.append('\f')
                elif esc == 'n':
                    chars.append('\n')
                elif esc == 'r':
                    chars.append('\r')
                elif esc == 't':
                    chars.append('\t')
                elif esc == 'u':
                    # unicode escape
                    hexs = s[pos+1:pos+5]
                    if len(hexs) == 4:
                        try:
                            codepoint = int(hexs, 16)
                            chars.append(chr(codepoint))
                            pos += 4
                        except ValueError:
                            pass
                    pos += 1
                else:
                    chars.append(esc)
                pos += 1
            elif c == '"':
                pos += 1  # skip closing "
                return ''.join(chars)
            else:
                chars.append(c)
                pos += 1
        return ''.join(chars)
    def parse_number():
        nonlocal pos
        start = pos
        if pos < n and s[pos] == '-':
            pos += 1
        while pos < n and s[pos].isdigit():
            pos += 1
        is_float = False
        if pos < n and s[pos] == '.':
            is_float = True
            pos += 1
            while pos < n and s[pos].isdigit():
                pos += 1
        if pos < n and s[pos] in ('e', 'E'):
            is_float = True
            pos += 1
            if pos < n and s[pos] in ('+', '-'):
                pos += 1
            while pos < n and s[pos].isdigit():
                pos += 1
        num_str = s[start:pos]
        if not num_str:
            raise ValueError("Empty number")
        if is_float:
            return float(num_str)
        try:
            return int(num_str)
        except ValueError:
            return float(num_str)

    result = parse_value()
    skip_ws()
    return result

