                    code = int(hex_code, 16)
                    result.append(chr(code))
                    i += 4
                i += 1
        else:
            result.append(c)
            i += 1
    return ''.join(result)


def _parse_value(s, i):
    n = len(s)
    if i >= n:
        raise ValueError("unexpected end")
    c = s[i]
