        j = i + 1
        depth = 1
        in_str = False
        while j < n and depth > 0:
            if in_str:
                if s[j] == '\\':
                    j += 2
                    continue
                elif s[j] == '"':
                    in_str = False
            else:
                if s[j] == '"':
                    in_str = True
                elif s[j] == '{':
                    depth += 1
                elif s[j] == '}':
                    depth -= 1
            j += 1
        substring = s[i:j-1]
        pairs = _parse_object_pairs(substring)
        return dict(pairs), j

    elif c == '[':
        j = i + 1
        depth = 1
        in_str = False
        while j < n and depth > 0:
            if in_str:
                if s[j] == '\\':
                    j += 2
                    continue
                elif s[j] == '"':
                    in_str = False
            else:
                if s[j] == '"':
                    in_str = True
                elif s[j] == '[':
                    depth += 1
                elif s[j] == ']':
                    depth -= 1
            j += 1
        substring = s[i+1:j-1]
        items = _parse_array_items(substring)
        return items, j

    elif c == '"':
        j = i + 1
        while j < n and s[j] != '"':
