                j += 2
            else:
                j += 1
        str_val = _decode_str(s[i+1:j])
        return str_val, j + 1

    else:
        # number, true, false, null
        j = i
        while j < n and s[j] not in ',}] \t\n\r':
            j += 1
        token = s[i:j].strip()
        if token == 'true':
            return True, j
        elif token == 'false':
            return False, j
        elif token == 'null':
            return None, j
        else:
            # number
            if '.' in token or 'e' in token or 'E' in token:
                return float(token), j
            else:
                return int(token), j


