def _json_loads_plain(s, object_pairs_hook=None, object_hook=None, parse_int=None, parse_float=None):
    import re
    s = s.strip()

    # Tokenize the JSON string
    def tokenize(text):
        tokens = []
        i = 0
        n = len(text)
        while i < n:
            c = text[i]
            if c in ' \t\n\r':
                i += 1
            elif c == '{':
                tokens.append(('object_start', None))
                i += 1
            elif c == '}':
                tokens.append(('object_end', None))
                i += 1
            elif c == '[':
                tokens.append(('array_start', None))
                i += 1
            elif c == ']':
                tokens.append(('array_end', None))
                i += 1
            elif c == ',':
                tokens.append(('comma', None))
                i += 1
            elif c == ':':
                tokens.append(('colon', None))
                i += 1
            elif c == '"':
                # String token
                j = i + 1
                buf = []
                while j < n:
                    ch = text[j]
                    if ch == '\\':
                        j += 1
                        esc = text[j]
                        if esc == '"':
                            buf.append('"')
                        elif esc == '\\':
                            buf.append('\\')
                        elif esc == '/':
                            buf.append('/')
                        elif esc == 'b':
                            buf.append('\b')
                        elif esc == 'f':
                            buf.append('\f')
                        elif esc == 'n':
                            buf.append('\n')
                        elif esc == 'r':
                            buf.append('\r')
                        elif esc == 't':
                            buf.append('\t')
                        elif esc == 'u':
                            code = text[j+1:j+5]
                            buf.append(chr(int(code, 16)))
                            j += 4
                        else:
                            buf.append(esc)
                        j += 1
                    elif ch == '"':
                        break
                    else:
                        buf.append(ch)
                        j += 1
                tokens.append(('string', ''.join(buf)))
                i = j + 1
            elif c == '-' or c.isdigit():
                # Number
                j = i
                is_float = False
                while j < n:
                    ch = text[j]
                    if ch == '.' or ch == 'e' or ch == 'E':
                        is_float = True
                    if ch not in '-+.eE0123456789':
                        break
                    j += 1
                num_str = text[i:j]
                tokens.append(('number', num_str))
                i = j
            elif c == 't':
                # true
                tokens.append(('literal', True))
                i += 4
            elif c == 'f':
                # false
                tokens.append(('literal', False))
                i += 5
            elif c == 'n':
                # null
                tokens.append(('literal', None))
                i += 4
            else:
                raise ValueError("Unexpected character at position %d" % i)
        return tokens

    tokens = tokenize(s)
    pos = [0]

    def parse_value():
        kind, val = tokens[pos[0]]
        pos[0] += 1
        if kind == 'object_start':
            return parse_object()
        elif kind == 'array_start':
            return parse_array()
        elif kind == 'string':
            return val
        elif kind == 'number':
            if parse_int and '.' not in val and 'e' not in val and 'E' not in val and (not val.startswith('-') or val[1] != '.'):
                try:
                    return parse_int(int(val))
                except:
                    pass
            if parse_float and ('.' in val or 'e' in val or 'E' in val):
                return parse_float(float(val))
            if '.' in val or 'e' in val or 'E' in val:
                return float(val)
            return int(val)
        elif kind == 'literal':
            return val
        else:
            raise ValueError("Unexpected token")

    def parse_object():
        pairs = []
        # Expect comma-separated "key": value pairs
        while True:
            kind, val = tokens[pos[0]]
            if kind == 'object_end':
                pos[0] += 1
                break
            # key
            k_kind, k_val = tokens[pos[0]]
            pos[0] += 1
            if k_kind != 'string':
                raise ValueError("Expected string key")
            # colon
            c_kind, c_val = tokens[pos[0]]
            pos[0] += 1
            if c_kind != 'colon':
                raise ValueError("Expected colon")
            # value
            v = parse_value()
            pairs.append((k_val, v))
            # check for comma
            nk, nv = tokens[pos[0]]
            if nk == 'comma':
                pos[0] += 1
                continue
            else:
                break
        if object_pairs_hook:
            return object_pairs_hook(pairs)
        d = dict(pairs)
        if object_hook:
            return object_hook(d)
        return d

    def parse_array():
        items = []
        while True:
            kind, val = tokens[pos[0]]
            if kind == 'array_end':
                pos[0] += 1
                break
            items.append(parse_value())
            nk, nv = tokens[pos[0]]
            if nk == 'comma':
                pos[0] += 1
                continue
            else:
                break
        return items

    result = parse_value()
    return result

