def _parse_json(text, object_pairs_hook=None, object_hook=None, parse_int=None, parse_float=None):
    # Simple JSON parser that mimics json.loads behavior for the specific cases needed
    text = text.strip()
    return _parse_value(text, 0)[0]


def _skip_ws(s, i):
    while i < len(s) and s[i] in ' \t\n\r':
        i += 1
    return i


def _parse_value(s, i):
    i = _skip_ws(s, i)
    if i >= len(s):
        raise ValueError("Unexpected end of input")
    c = s[i]
    if c == '{':
        return _parse_object(s, i)
    elif c == '[':
        return _parse_array(s, i)
    elif c == '"':
        return _parse_string(s, i)
    elif c == '-':
        return _parse_number(s, i)
    elif c.isdigit():
        return _parse_number(s, i)
    elif s[i:i+4] == 'true':
        i += 4
        return True, i
    elif s[i:i+5] == 'false':
        i += 5
        return False, i
    elif s[i:i+4] == 'null':
        i += 4
        return None, i
    else:
        raise ValueError(f"Unexpected character {c} at position {i}")


def _parse_object(s, i):
    assert s[i] == '{'
    i += 1
    pairs = []
    i = _skip_ws(s, i)
    if i < len(s) and s[i] == '}':
        i += 1
        result = dict(pairs) if object_hook is not None else {}
        if object_hook is not None:
            result = object_hook(result)
        return result, i

    while True:
        i = _skip_ws(s, i)
        key_str, i = _parse_string(s, i)
        i = _skip_ws(s, i)
        assert s[i] == ':'
        i += 1
        val, i = _parse_value(s, i)
        pairs.append((key_str, val))
        i = _skip_ws(s, i)
        if i >= len(s):
            raise ValueError("Unexpected end of object")
        if s[i] == ',':
            i += 1
            continue
        elif s[i] == '}':
            i += 1
            break
        else:
            raise ValueError(f"Expected , or }} but got {s[i]}")

    if object_pairs_hook is not None:
        result = object_pairs_hook(pairs)
    else:
        result = dict(pairs)
    if object_hook is not None:
        result = object_hook(result)
    return result, i


def _parse_array(s, i):
    assert s[i] == '['
    i += 1
    arr = []
    i = _skip_ws(s, i)
    if i < len(s) and s[i] == ']':
        i += 1
        return arr, i

    while True:
        val, i = _parse_value(s, i)
        arr.append(val)
        i = _skip_ws(s, i)
        if i >= len(s):
            raise ValueError("Unexpected end of array")
        if s[i] == ',':
            i += 1
            continue
        elif s[i] == ']':
            i += 1
            break
        else:
            raise ValueError(f"Expected , or ] but got {s[i]}")
    return arr, i


def _parse_string(s, i):
    assert s[i] == '"'
    i += 1
    chars = []
    while i < len(s):
        c = s[i]
        if c == '"':
            i += 1
            return ''.join(chars), i
        elif c == '\\':
            i += 1
            esc = s[i]
            if esc == 'n':
                chars.append('\n')
            elif esc == 't':
                chars.append('\t')
            elif esc == 'r':
                chars.append('\r')
            elif esc == '"':
                chars.append('"')
            elif esc == '\\':
                chars.append('\\')
            elif esc == '/':
                chars.append('/')
            elif esc == 'b':
                chars.append('\b')
            elif esc == 'f':
                chars.append('\f')
            elif esc == 'u':
                hex_code = s[i+1:i+5]
                char_val = int(hex_code, 16)
                chars.append(chr(char_val))
                i += 4
            else:
                chars.append(esc)
            i += 1
        else:
            chars.append(c)
            i += 1
    raise ValueError("Unterminated string")


def _parse_number(s, i):
    start = i
    if s[i] == '-':
        i += 1
    while i < len(s) and (s[i].isdigit()):
        i += 1
    is_float = False
    if i < len(s) and s[i] == '.':
        is_float = True
        i += 1
        while i < len(s) and s[i].isdigit():
            i += 1
    if i < len(s) and s[i] in 'eE':
        is_float = True
        i += 1
        if i < len(s) and s[i] in '+-':
            i += 1
        while i < len(s) and s[i].isdigit():
            i += 1

    num_str = s[start:i]
    if is_float:
        val = float(num_str)
        if parse_float is not None:
            val = parse_float(num_str)
    else:
        val = int(num_str)
        if parse_int is not None:
            val = parse_int(num_str)
    return val, i


