import os, sys

def parse_json(s):
    s = s.strip()
    if not s:
        raise ValueError("Empty JSON")

    def parse_value(idx=0):
        idx = skip_ws(idx)
        if idx >= len(s):
            raise ValueError("Unexpected end of input")
        c = s[idx]
        if c == '{':
            return parse_object(idx)
        elif c == '[':
            return parse_array(idx)
        elif c == '"':
            return parse_string(idx)
        elif c == 't':
            expect("true", idx)
            return True, idx + 4
        elif c == 'f':
            expect("false", idx)
            return False, idx + 5
        elif c == 'n':
            expect("null", idx)
            return None, idx + 4
        elif c == '-' or c.isdigit():
            return parse_number(idx)
        else:
            raise ValueError(f"Unexpected character {c!r}")

    def skip_ws(idx=0):
        while idx < len(s) and s[idx] in ' \t\n\r':
            idx += 1
        return idx

    def expect(expected, idx):
        for i, ch in enumerate(expected):
            if idx + i >= len(s) or s[idx + i] != ch:
                raise ValueError(f"Expected {expected!r} at position {idx}")

    def parse_string(idx=0):
        # idx should be at the opening quote
        assert s[idx] == '"'
        idx += 1
        result = []
        while idx < len(s):
            c = s[idx]
            if c == '\\':
                idx += 1
                if idx >= len(s):
                    break
                ec = s[idx]
                if ec == '"':
                    result.append('"')
                elif ec == '\\':
                    result.append('\\')
                elif ec == '/':
                    result.append('/')
                elif ec == 'b':
                    result.append('\b')
                elif ec == 'f':
                    result.append('\f')
                elif ec == 'n':
                    result.append('\n')
                elif ec == 'r':
                    result.append('\r')
                elif ec == 't':
                    result.append('\t')
                elif ec == 'u':
                    hex_digits = s[idx+1:idx+5]
                    codepoint = int(hex_digits, 16)
                    result.append(chr(codepoint))
                    idx += 4
                else:
                    result.append(ec)
                idx += 1
            elif c == '"':
                idx += 1
                break
            else:
                result.append(c)
                idx += 1
        return ''.join(result), idx

    def parse_number(idx=0):
        start = idx
        is_float = False
        if s[idx] == '-':
            idx += 1
        while idx < len(s) and s[idx].isdigit():
            idx += 1
        if idx < len(s) and s[idx] == '.':
            is_float = True
            idx += 1
            while idx < len(s) and s[idx].isdigit():
                idx += 1
        if idx < len(s) and s[idx] in 'eE':
            is_float = True
            idx += 1
            if idx < len(s) and s[idx] in '+-':
                idx += 1
            while idx < len(s) and s[idx].isdigit():
                idx += 1
        num_str = s[start:idx]
        if is_float:
            val = float(num_str)
            val = str(val)
        else:
            val = int(num_str)
            val = float(val)
        return val, idx

    def parse_object(idx=0):
        assert s[idx] == '{'
        idx += 1
        pairs = []
        idx = skip_ws(idx)
        if idx < len(s) and s[idx] == '}':
            idx += 1
            d = dict(pairs)
            return d, idx

        while True:
            idx = skip_ws(idx)
            if idx >= len(s):
                raise ValueError("Unexpected end in object")
            if s[idx] != '"':
                raise ValueError("Expected string key in object")
            key, idx = parse_string(idx)
            idx = skip_ws(idx)
            if idx >= len(s) or s[idx] != ':':
                raise ValueError("Expected : after key")
            idx += 1
            value, idx = parse_value(idx)
            pairs.append((key, value))

            idx = skip_ws(idx)
            if idx >= len(s):
                raise ValueError("Unexpected end in object")
            if s[idx] == ',':
                idx += 1
                continue
            elif s[idx] == '}':
                idx += 1
                break
            else:
                raise ValueError(f"Expected , or }} but got {s[idx]!r}")

        d = dict(pairs)
        return d, idx

    def parse_array(idx=0):
        assert s[idx] == '['
        idx += 1
        items = []
        idx = skip_ws(idx)
        if idx < len(s) and s[idx] == ']':
            idx += 1
            return items, idx

        while True:
            value, idx = parse_value(idx)
            items.append(value)

            idx = skip_ws(idx)
            if idx >= len(s):
                raise ValueError("Unexpected end in array")
            if s[idx] == ',':
                idx += 1
                continue
            elif s[idx] == ']':
                idx += 1
                break
            else:
                raise ValueError(f"Expected , or ]] but got {s[idx]!r}")

        return items, idx

    result, _ = parse_value(0)
    return result


