def to_repr(s):
    # Produce the repr of the string without using repr() on non-ASCII characters
    # This mimics Python's repr behavior for strings
    # We need to handle: normal printable ASCII, and non-ASCII/non-printable as escapes

    result = []
    i = 0
    n = len(s)

    # Determine if we use single or double quotes
    # Python uses single quotes unless the string contains single quotes but no double quotes
    has_single = "'" in s
    has_double = '"' in s

    if has_single and not has_double:
        quote_char = '"'
    else:
        quote_char = "'"

    for ch in s:
        c = ord(ch)

        if c == 0x0A:
            result.append('\\n')
        elif c == 0x0D:
            result.append('\\r')
        elif c == 0x09:
            result.append('\\t')
        elif c == 0x0B:
            result.append('\\x0b')
        elif c == 0x0C:
            result.append('\\x0c')
        elif c == 0x08:
            result.append('\\b')
        elif c == 0x07:
            result.append('\\a')
        elif c == 0x0C:
            result.append('\\f')
        elif c == 0x00:
            result.append('\\0')
        elif c == 0x7F:
            result.append('\\x7f')
        elif c == ord(quote_char):
            result.append('\\' + quote_char)
        elif 0x20 <= c <= 0x7E:
            # Printable ASCII
            result.append(ch)
        elif c < 0x20 or c >= 0x7F:
            # Use \x for control chars that don't have named escapes, 
            # and \uXXXX for non-ASCII
            if c < 0x80:
                result.append('\\x%02x' % c)
            elif c < 0x10000:
                result.append('\\u%04x' % c)
            else:
                # Surrogate pairs or larger
                c -= 0x10000
                high = 0xD800 + (c >> 10)
                low = 0xDC00 + (c & 0x3FF)
                result.append('\\u%04x\\u%04x' % (high, low))
        else:
            result.append(ch)

    return quote_char + ''.join(result) + quote_char

