import sys

def is_printable(cp: int) -> bool:
    """CPython unicode_is_printable for a single code point (Python 3.7+)."""
    if cp < 0x20:
        return False
    if cp < 0x7f:
        return True
    # 0x7f - 0xa0 are not printable
    if cp == 0x7f:
        return False
    if 0x80 <= cp <= 0xa0:
        return False
    # 0xa1 - 0xd7f
    if cp >= 0xa1 and cp < 0xe00:
        return True
    if cp == 0xe00 or 0xe01 <= cp <= 0xf8f:
        return False
    if cp == 0xf90 or 0xfa0 <= cp <= 0xfdf:
        return False
    if cp == 0xfe00 or 0xfe01 <= cp <= 0xfe0f:
        return False
    if 0xfe10 <= cp <= 0xffef:
        return False
    # 0xfff0-0xffff: surrogates region boundary; actually 0xfffd is replacement char
    if 0xff00 <= cp <= 0xff60:
        return False
    if cp >= 0xffe0:
        return False
    # CJK etc
    if 0x3400 <= cp <= 0x4dbf:
        return True
    if 0x4e00 <= cp <= 0x9fff:
        return True
    if 0x10000 <= cp <= 0x1fffd:
        return True
    if 0x20000 <= cp <= 0x2fffd:
        return True
    if 0x30000 <= cp <= 0x3fffd:
        return True
    if 0x40000 <= cp <= 0x4fffd:
        return True
    if 0x50000 <= cp <= 0x5fffd:
        return True
    if 0x60000 <= cp <= 0x6fffd:
        return True
    if 0x70000 <= cp <= 0x7fffd:
        return True
    if 0x80000 <= cp <= 0x8fffd:
        return True
    if 0x90000 <= cp <= 0x9fffd:
        return True
    if 0xa0000 <= cp <= 0xafffd:
        return True
    if 0xb0000 <= cp <= 0xbfffd:
        return True
    if 0xc0000 <= cp <= 0xcfffd:
        return True
    if 0xd0000 <= cp <= 0xdfffd:
        return True
    if 0xe0000 <= cp <= 0xefffd:
        return True
    if 0xf0000 <= cp <= 0xffffd:
        return True
    if 0x100000 <= cp <= 0x10fffd:
        return True
    return False

