            has_double = True
        elif c == 39:
            has_single = True
        if c < 32 or c == 127 or c == 92:
            has_backslash_or_ctrl = True
        if c >= 128 and not (32 <= c <= 126):
            # non-ASCII printable; repr would show the character itself
            needs_escape_nonascii = True
        if c == 0xA0:
            # U+00A0 is non-breaking space; repr shows it as the actual character
            needs_escape_nonascii = True

    if has_single and not has_double:
        use_single = True
    elif has_double and not has_single:
        use_single = False
    else:
        use_single = True

    q = "'" if use_single else '"'

    parts = []
    parts.append(q)
    for ch in s:
        c = ord(ch)
        if c == 10:
            parts.append("\\n")
        elif c == 9:
            parts.append("\\t")
        elif c == 13:
            parts.append("\\r")
        elif c == 92:
            parts.append("\\\\")
        elif c == 39 and use_single:
            parts.append("\\'")
        elif c == 34 and not use_single:
            parts.append('\\"')
        elif c < 32 or c == 127:
            parts.append("\\x%02x" % c)
        elif c == 0xA0:
            # Represent U+00A0 as \xa0 to avoid printing the character? 
            # Actually repr() of '\xa0' in Python 3 returns "'\xa0'" — it uses the escape!
            # Let's verify: in Python 3, repr('\xa0') == "'\\xa0'"
            parts.append("\\xa0")
