def custom_repr(s):
    # Implement repr() for strings in a way that avoids calling the built-in repr()
    # on characters whose printability check requires CPython's unicode tables.
    # We just need to produce the same output as repr().
    if s == '':
        return "''"

    result_chars = []
    use_single_quotes = True

    # Check if string contains single quotes but not double quotes -> use double quotes
    if "'" in s and '"' not in s:
        use_single_quotes = False
    elif '"' in s and "'" not in s:
        use_single_quotes = True
    else:
        # Prefer single quotes (default)
        use_single_quotes = True

    quote = "'" if use_single_quotes else '"'

    for ch in s:
        code = ord(ch)
        if ch == '\\':
            result_chars.append('\\\\')
        elif ch == quote:
            result_chars.append('\\"' if not use_single_quotes else "\\'")
        elif ch == '\n':
            result_chars.append('\\n')
        elif ch == '\r':
            result_chars.append('\\r')
        elif ch == '\t':
            result_chars.append('\\t')
        elif ch == '\v':
            result_chars.append('\\v')
        elif ch == '\f':
            result_chars.append('\\f')
        elif ch == '\x0b':
            result_chars.append('\\v')
        elif ch == '\x0c':
            result_chars.append('\\f')
        elif code < 32 or code > 126:
            # Non-printable or non-ASCII: use \xNN or \uXXXX etc.
            if code < 256:
                result_chars.append('\\x%02x' % code)
            elif code < 65536:
                result_chars.append('\\u%04x' % code)
            else:
                # Surrogate pair or astral plane char: encode in UTF-16
                cp = code - 0x10000
                hi = 0xD800 + (cp >> 10)
                lo = 0xDC00 + (cp & 0x3FF)
                result_chars.append('\\u%04x\\u%04x' % (hi, lo))
        else:
            result_chars.append(ch)

    return quote + ''.join(result_chars) + quote

