def safe_eval(expr):
    # Remove float('nan') occurrences to avoid builtin call
    # We'll replace them with a token and parse
    import ast

    # First, let's transform the expression to remove function calls to float
    # Replace float('nan') with NaN
    expr_modified = expr.replace("float('nan')", "NaN")

    try:
        tree = ast.parse(expr_modified, mode='eval')
    except SyntaxError:
        # If it still has issues, raise an appropriate error
        raise

    def evaluate(node):
        if isinstance(node, ast.Expression):
            return evaluate(node.body)
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.Str):
            return node.s
        elif isinstance(node, ast.Name):
            if node.id == 'NaN':
                return float('nan')
            elif node.id == 'True':
                return True
            elif node.id == 'False':
                return False
            elif node.id == 'None':
                return None
            else:
                raise NameError(f"name '{node.id}' is not defined")
        elif isinstance(node, ast.List):
            return [evaluate(el) for el in node.elts]
        elif isinstance(node, ast.Tuple):
            return tuple(evaluate(el) for el in node.elts)
        elif isinstance(node, ast.Set):
            return set(evaluate(el) for el in node.elts)
        elif isinstance(node, ast.Dict):
            return {evaluate(k): evaluate(v) for k, v in zip(node.keys, node.values)}
        elif isinstance(node, ast.UnaryOp):
            operand = evaluate(node.operand)
            if isinstance(node.op, ast.Not):
                return not operand
            elif isinstance(node.op, ast.USub):
                return -operand
            elif isinstance(node.op, ast.UAdd):
                return +operand
            else:
                raise TypeError(f"unsupported unary operator: {type(node.op).__name__}")
        elif isinstance(node, ast.BinOp):
            left = evaluate(node.left)
            right = evaluate(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                return left / right
            elif isinstance(node.op, ast.FloorDiv):
                return left // right
            elif isinstance(node.op, ast.Mod):
                return left % right
            elif isinstance(node.op, ast.Pow):
                return left ** right
            else:
                raise TypeError(f"unsupported binary operator: {type(node.op).__name__}")
        elif isinstance(node, ast.Compare):
            left = evaluate(node.left)
            operators = []
            comparators = [evaluate(c) for c in node.comparators]

            op_funcs = {
                ast.Eq: operator.eq,
                ast.NotEq: operator.ne,
                ast.Lt: operator.lt,
                ast.LtE: operator.le,
                ast.Gt: operator.gt,
                ast.GtE: operator.ge,
                ast.Is: lambda a, b: a is b,
                ast.IsNot: lambda a, b: a is not b,
                ast.In: lambda a, b: a in b,
                ast.NotIn: lambda a, b: a not in b,
            }

            for i, op in enumerate(node.ops):
                comp = comparators[i]
                func = op_funcs.get(type(op))
                if func is None:
                    raise TypeError(f"unsupported comparison operator: {type(op).__name__}")
                result = func(left, comp)
                if not result:
                    return False
                left = comp

            return True
        elif isinstance(node, ast.Call):
            func_name = None
            if isinstance(node.func, ast.Name):
                func_name = node.func.id
            else:
                raise NotImplementedError("only simple name calls supported")

            args = [evaluate(a) for a in node.args]
            keywords = {}
            for kw in node.keywords:
                keywords[kw.arg] = evaluate(kw.value)

            if func_name == 'sorted':
                if len(args) != 1:
                    raise TypeError(f'sorted expected at least 1 argument, got {len(args)}')
                iterable = args[0]
                key = kwargs.get('key')
                reverse = kwargs.get('reverse', False)
