        left = _eval_node(node.left)
        ops = node.ops
        comparators = node.comparators
        for i, op in enumerate(ops):
            right = _eval_node(comparators[i])
            if isinstance(op, ast.Lt):
                result = left < right
            elif isinstance(op, ast.Gt):
                result = left > right
            elif isinstance(op, ast.LtE):
                result = left <= right
            elif isinstance(op, ast.GtE):
                result = left >= right
            elif isinstance(op, ast.Eq):
                result = left == right
            elif isinstance(op, ast.NotEq):
                result = left != right
            elif isinstance(op, ast.Is):
                result = left is right
            elif isinstance(op, ast.IsNot):
                result = left is not right
            elif isinstance(op, ast.In):
                result = left in right
            elif isinstance(op, ast.NotIn):
                result = left not in right
            else:
                raise ValueError("Unknown comparison operator")
            if not result:
                return False
            left = right
        return True
    elif isinstance(node, ast.UnaryOp):
        operand = _eval_node(node.operand)
        if isinstance(node.op, ast.USub):
            return -operand
        elif isinstance(node.op, ast.UAdd):
            return +operand
        elif isinstance(node.op, ast.Not):
            return not operand
        elif isinstance(node.op, ast.Invert):
            return ~operand
        else:
            raise ValueError("Unknown unary operator")
    elif isinstance(node, ast.BinOp):
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        elif isinstance(node.op, ast.Sub):
            return left - right
        elif isinstance(node.op, ast.Mult):
            return left * right
        elif isinstance(node.op, ast.Div):
            return left / right
        elif isinstance(node.op, ast.Mod):
            return left % right
        elif isinstance(node.op, ast.Pow):
            return left ** right
        elif isinstance(node.op, ast.FloorDiv):
            return left // right
        elif isinstance(node.op, ast.BitAnd):
            return left & right
        elif isinstance(node.op, ast.BitOr):
            return left | right
        elif isinstance(node.op, ast.BitXor):
            return left ^ right
        elif isinstance(node.op, ast.LShift):
            return left << right
        elif isinstance(node.op, ast.RShift):
            return left >> right
        else:
            raise ValueError("Unknown binary operator")
    elif isinstance(node, ast.Name):
        if node.id == 'True':
            return True
        elif node.id == 'False':
            return False
        elif node.id == 'None':
            return None
        else:
            raise NameError("name '%s' is not defined" % node.id)
    elif isinstance(node, ast.Attribute):
        value = _eval_node(node.value)
        return getattr(value, node.attr)
    elif isinstance(node, ast.Subscript):
        value = _eval_node(node.value)
        slice_node = _eval_node(node.slice)
        return value[slice_node]
