import ast, builtins

# Build a safe evaluation function using ast.literal_eval is not enough for expressions
# We need to evaluate general Python expressions without using eval/compile/exec.
# The approach: use the ast module to parse and then manually evaluate.

def _eval_node(node):
    """Recursively evaluate an AST node."""
    if isinstance(node, ast.Expression):
        return _eval_node(node.body)
    elif isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Num):  # deprecated but might appear
        return node.n
    elif isinstance(node, ast.Str):  # deprecated
        return node.s
    elif isinstance(node, ast.NameConstant):  # deprecated
        return node.value
    elif isinstance(node, ast.Name):
        name = node.id
        if name in globals() or name in __builtins__.__dict__:
            # Look up in globals, then builtins
            g = {k: v for k, v in globals().items()}
            b = vars(builtins)
            if name in g:
                return g[name]
            elif name in b:
                return b[name]
            else:
                raise NameError(f"name '{name}' is not defined")
        else:
            raise NameError(f"name '{name}' is not defined")
    elif isinstance(node, ast.UnaryOp):
        operand = _eval_node(node.operand)
        op = node.op
        if isinstance(op, ast.UAdd):
            return +operand
        elif isinstance(op, ast.USub):
            return -operand
        elif isinstance(op, ast.Not):
            return not operand
        elif isinstance(op, ast.Invert):
            return ~operand
    elif isinstance(node, ast.BinOp):
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        op = node.op
        if isinstance(op, ast.Add):
            return left + right
        elif isinstance(op, ast.Sub):
            return left - right
        elif isinstance(op, ast.Mult):
            return left * right
        elif isinstance(op, ast.Div):
            return left / right
        elif isinstance(op, ast.FloorDiv):
            return left // right
        elif isinstance(op, ast.Mod):
            return left % right
        elif isinstance(op, ast.Pow):
            return left ** right
        elif isinstance(op, ast.MatMult):
            return left @ right
    elif isinstance(node, ast.BoolOp):
        values = []
        for value in node.values:
            values.append(_eval_node(value))
        if isinstance(node.op, ast.And):
            result = True
            for v in values:
                result = v
                if not result:
                    break
            return result
        elif isinstance(node.op, ast.Or):
            result = False
            for v in values:
                result = v
                if result:
                    break
            return result
    elif isinstance(node, ast.Compare):
        left = _eval_node(node.left)
        for i, comparator in enumerate(node.comparators):
            comparator_val = _eval_node(comparator)
            op = node.ops[i]
            if isinstance(op, ast.Eq):
                if not (left == comparator_val):
                    return False
            elif isinstance(op, ast.NotEq):
                if not (left != comparator_val):
                    return False
            elif isinstance(op, ast.Lt):
                if not (left < comparator_val):
                    return False
            elif isinstance(op, ast.LtE):
                if not (left <= comparator_val):
                    return False
            elif isinstance(op, ast.Gt):
                if not (left > comparator_val):
                    return False
            elif isinstance(op, ast.GtE):
                if not (left >= comparator_val):
                    return False
            elif isinstance(op, ast.Is):
                if not (left is comparator_val):
                    return False
            elif isinstance(op, ast.IsNot):
                if not (left is not comparator_val):
                    return False
            elif isinstance(op, ast.In):
                if not (left in comparator_val):
                    return False
            elif isinstance(op, ast.NotIn):
                if not (left not in comparator_val):
                    return False
            left = comparator_val
        return True
    elif isinstance(node, ast.IfExp):
        test = _eval_node(node.test)
        if test:
            return _eval_node(node.body)
        else:
            return _eval_node(node.orelse)
    elif isinstance(node, ast.Call):
        func = _eval_node(node.func)
        args = [_eval_node(a) for a in node.args]
        keywords = {}
        for kw in node.keywords:
            key = kw.arg
            val = _eval_node(kw.value)
            if key is None:
                raise TypeError("cannot handle double-star keyword arguments")
            keywords[key] = val
        return func(*args, **keywords)
    elif isinstance(node, ast.List):
        return [_eval_node(el) for el in node.elts]
    elif isinstance(node, ast.Tuple):
        return tuple(_eval_node(el) for el in node.elts)
    elif isinstance(node, ast.Set):
        return {_eval_node(el) for el in node.elts}
    elif isinstance(node, ast.Dict):
        d = {}
        for key, val in zip(node.keys, node.values):
            if key is not None:
                d[_eval_node(key)] = _eval_node(val)
        return d
    elif isinstance(node, ast.Attribute):
        obj = _eval_node(node.value)
        return getattr(obj, node.attr)
    elif isinstance(node, ast.Subscript):
        obj = _eval_node(node.value)
        slice_node = node.slice
        return obj[slice_node]
    else:
        raise NotImplementedError(f"Cannot evaluate node type: {type(node).__name__}")


def safe_eval(expr_str):
    """Evaluate a Python expression string without using eval."""
    tree = ast.parse(expr_str, mode='eval')
    return _eval_node(tree)


