def _safe_eval(code):
    """Safely evaluate the specific expressions in CASES without using eval()."""
    # Strip whitespace
    code = code.strip()

    # Handle sorted(...)
    if code.startswith("sorted(") and code.endswith(")"):
        inner = code[len("sorted("):-1]
        # Parse the list inside sorted
        lst = _parse_list(inner)
        try:
            result = sorted(lst)
        except Exception as e:
            raise type(e)(str(e))
        return result

    # Handle set comparisons like {1} < {1,2}
    if code.startswith("{") and ("{" in code[1:]) and ("<" in code or ">" in code or "==" in code or ">=" in code or "<=" in code):
        # Find the operator
        pass  # We'll handle below more generically

    # Determine the operator
    # Check for two-character operators first
    op = None
    idx = -1
    for o in ["<=", ">=", "==", "!=", "<", ">", "="]:
        # For "<=", we need to check that it's not part of something else
        i = code.find(o)
        if i != -1:
            # Make sure it's a valid position (not inside a string or number)
            # Simple heuristic: count braces/brackets before this position
            depth = 0
            in_str = False
            str_char = None
            j = 0
            valid_pos = False
            while j < len(code):
                c = code[j]
                if in_str:
                    if c == str_char:
                        in_str = False
                else:
                    if c in "'\"":
                        in_str = True
                        str_char = c
                    elif c in "[{(":
                        depth += 1
                    elif c in "]})":
                        depth -= 1
                    if j == i and depth == 0 and not in_str:
                        valid_pos = True
                        break
                j += 1
            if valid_pos:
                # For one-char operators, make sure they aren't part of a two-char op already matched
                if len(o) == 1:
                    # Check previous char
                    if i > 0 and code[i-1] in "<>=":
                        continue
                    # Check next char for two-char ops
                    if i + 1 < len(code) and code[i+1] in "=<>":
                        # This could be part of <=, >=, ==, etc.
                        # But we're checking single-char, so skip if next forms a two-char
                        two_char = code[i:i+2]
                        if two_char in ["<=", ">=", "==", "!="]:
                            continue
                op = o
                idx = i
                break

    if op is None:
        raise ValueError(f"Cannot parse expression: {code}")

    left_str = code[:idx].strip()
    right_str = code[idx+len(op):].strip()

    left_val = _eval_value(left_str)
    right_val = _eval_value(right_str)

    try:
        if op == "<":
            return left_val < right_val
        elif op == ">":
            return left_val > right_val
        elif op == "<=":
            return left_val <= right_val
        elif op == ">=":
            return left_val >= right_val
        elif op == "==":
            return left_val == right_val
        else:
            raise ValueError(f"Unknown operator: {op}")
    except TypeError as e:
        raise TypeError(str(e))
    except Exception as e:
        raise


def _eval_value(s):
    """Evaluate a single value expression."""
    s = s.strip()

    # Empty string
    if s == "''" or s == '""':
        return ''

    # float('nan')
    if s == "float('nan')":
        return float('nan')

    # Numbers
    try:
        if '.' in s:
            return float(s)
        else:
            return int(s)
    except ValueError:
        pass

    # List
    if s.startswith("[") and s.endswith("]"):
        return _parse_list(s)

    # Tuple
    if s.startswith("(") and s.endswith(")"):
        return _parse_tuple(s)

    # Set
    if s.startswith("{") and s.endswith("}"):
        return _parse_set(s)

    # None
    if s == "None":
        return None

    # Parenthesized expression
    if s.startswith("(") and s.endswith(")") and s.count("(") == s.count(")") == 1:
        return _eval_value(s[1:-1])

    raise ValueError(f"Cannot parse value: {s}")


def _parse_list(s):
    """Parse a list literal like [1, 'a'] or [float('nan'), 1.0]."""
    inner = s[1:-1].strip()
    if not inner:
        return []

    items = _split_top_level(inner, ",")
    result = []
    for item in items:
