def _parse_tuple(s):
    """Parse a tuple literal like (1,) or ('a',)."""
    inner = s[1:-1].strip()
    if not inner:
        return ()

    # Remove trailing comma if present for single element
    items = _split_top_level(inner, ",")
    result = []
    for item in items:
        item = item.strip()
        if item:
            result.append(_eval_value(item))
    return tuple(result)


def _parse_set(s):
    """Parse a set literal like {1} or {1,2}."""
    inner = s[1:-1].strip()
    if not inner:
        return set()

    items = _split_top_level(inner, ",")
    result = set()
    for item in items:
        item = item.strip()
        if item:
            result.add(_eval_value(item))
    return result


def _split_top_level(s, sep):
    """Split string on separator at top level (not inside brackets/strings)."""
    parts = []
    current = []
    depth = 0
    in_str = False
    str_char = None

    i = 0
    while i < len(s):
        c = s[i]

        if in_str:
            current.append(c)
            if c == str_char and (i == 0 or s[i-1] != '\\'):
                in_str = False
        else:
            if c in "'\"":
                in_str = True
                str_char = c
                current.append(c)
            elif c in "[{(":
                depth += 1
                current.append(c)
            elif c in "]})":
                depth -= 1
                current.append(c)
            elif c == sep and depth == 0:
                parts.append("".join(current))
                current = []
            else:
                current.append(c)
        i += 1

    if current:
        parts.append("".join(current))

    return parts


