            return tok[1:-1]
        try:
            if '.' in tok:
                return float(tok)
            else:
                return int(tok)
        except ValueError:
            raise ValueError(f"Cannot parse value: {tok}")

    # Handle sorted([...])
    if s.startswith('sorted(') and s.endswith(')'):
        inner = s[7:-1].strip()
        # inner should be like [1,'a'] or [float('nan'), 1.0]
        if not (inner.startswith('[') and inner.endswith(']')):
            raise ValueError(f"Expected list in sorted(): {s}")
        items_str = inner[1:-1].strip()
        if items_str == '':
            result = []
        else:
