            items = []
            parts = items_str.split(',')
            items = [parse_value(p) for p in parts]
        result = sorted(items)
        return result

    # Handle comparison expressions
    # Split on comparison operator
    for op in ['<=', '>=', '<', '>']:
        if op in s:
            # Need to be careful about splitting
