                    inner = operand[1:-1].strip()
                    if inner == '':
                        return []
                    parts = inner.split(',')
                    return [parse_value(p) for p in parts]
                # Check if it's a tuple
                if operand.startswith('(') and operand.endswith(')'):
                    inner = operand[1:-1].strip()
                    if inner == '':
                        return ()
                    # Handle single-element tuples
                    if inner.endswith(','):
                        parts = [p.strip() for p in inner[:-1].split(',') if p.strip()]
                        return tuple(parse_value(p) for p in parts)
                    else:
