                    inner = operand[1:-1].strip()
                    if inner == '':
                        return set()
                    parts = inner.split(',')
                    return set(parse_value(p) for p in parts)
                # It's a scalar value
                return parse_value(operand)

            lval = eval_operand(left)
            rval = eval_operand(right)

            if op == '<=':
                return lval <= rval
            elif op == '>=':
                return lval >= rval
            elif op == '<':
                return lval < rval
            elif op == '>':
                return lval > rval

    # Fallback: just parse as a value
    return parse_value(s)


