    """Compare a and b like Python's built-in comparison operators.
    Returns: -1 if a<b, 0 if a==b, 1 if a>b, or None if not comparable (TypeError)."""
    # First check equality/inequality using == which works across types
    try:
        eq = (a == b)
    except Exception:
        return None

    try:
        lt = (a < b)
    except TypeError:
        # For objects that are equal but don't support ordering between them, 
        # we need to check if they're the same type or handle nan specially
        if eq:
            return 0
        return None
    except Exception:
        return None

    if lt:
        return -1
    elif eq:
        return 0
    else:
        return 1


