def _parse_expr(s):
    s = s.strip()

    # Check for known functions
    if s.startswith('sorted(') and s.endswith(')'):
        inner = s[7:-1]
        lst = _parse_value(inner)
        try:
            result = sorted(lst)
            return result
        except TypeError as e:
            raise e
    elif s.startswith('float(') and s.endswith(')'):
        inner = s[6:-1].strip()
        return float(inner)
    elif s.startswith('repr(') and s.endswith(')'):
        inner = s[5:-1]
        val = _parse_value(inner)
        return repr(val)

    # Check for comparison operators at top level
    # Split on comparison operators, being careful with strings
    comparisons = ['<=', '>=', '<', '>', '==']

    # Find a top-level comparison operator
    depth = 0
    in_string = False
    quote_char = None
    i = 0
    found_op = None
    found_pos = -1

    while i < len(s):
        ch = s[i]

        if in_string:
            if ch == '\\':
                i += 2
                continue
            elif ch == quote_char:
                in_string = False
        else:
            if ch in ('"', "'"):
                in_string = True
                quote_char = ch
            elif ch in ('(', '[', '{'):
                depth += 1
            elif ch in (')', ']', '}'):
                depth -= 1
            elif depth == 0:
                # Check for comparison operators
                for op in comparisons:
                    if s[i:i+len(op)] == op:
                        # Make sure it's not part of something like <= etc already handled
                        found_op = op
                        found_pos = i
                        break
                if found_op:
                    break

        i += 1

    if found_op is not None:
        left_s = s[:found_pos].strip()
        right_s = s[found_pos + len(found_op):].strip()
        left_val = _parse_value(left_s)
        right_val = _parse_value(right_s)

        if found_op == '<':
            try:
                return left_val < right_val
            except TypeError as e:
                raise e
        elif found_op == '>':
            try:
                return left_val > right_val
            except TypeError as e:
                raise e
        elif found_op == '<=':
            try:
                return left_val <= right_val
            except TypeError as e:
                raise e
        elif found_op == '>=':
            try:
                return left_val >= right_val
            except TypeError as e:
                raise e
        elif found_op == '==':
            return left_val == right_val
        else:
            raise ValueError(f"Unknown operator: {found_op}")
    else:
        return _parse_value(s)


def _parse_value(s):
    s = s.strip()

    if not s:
        raise SyntaxError("empty value")

    # Handle NaN
    if s == "float('nan')":
        return float('nan')
    elif s == "float(\"nan\")":
        return float('nan')

    # Handle None
    if s == "None":
        return None

    # Handle booleans (not needed but just in case)
    if s == "True":
        return True
    elif s == "False":
        return False

    # Handle integers
    try:
        return int(s)
    except ValueError:
        pass

    # Handle floats
    try:
        return float(s)
    except ValueError:
        pass

    # Handle strings (single or double quotes)
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        return s[1:-1]

    # Handle tuples
    if s.startswith('(') and s.endswith(')'):
        inner = s[1:-1].strip()
        if not inner:
            return ()
        items = _split_top_level(inner)
        return tuple(_parse_value(item) for item in items)

    # Handle lists
    if s.startswith('[') and s.endswith(']'):
        inner = s[1:-1].strip()
        if not inner:
            return []
        items = _split_top_level(inner)
        return [_parse_value(item) for item in items]

    # Handle sets
    if s.startswith('{') and s.endswith('}'):
        inner = s[1:-1].strip()
        if not inner:
            return set()
        items = _split_top_level(inner)
        return set(_parse_value(item) for item in items)

    # Handle function calls
    func_result = _parse_function_call(s)
    if func_result is not None:
        return func_result

    raise ValueError(f"Cannot parse value: {s}")


def _parse_function_call(s):
    s = s.strip()

    if s.startswith('float(') and s.endswith(')'):
        inner = s[6:-1].strip()
        try:
            return float(inner)
        except ValueError as e:
            raise e
    elif s.startswith('int(') and s.endswith(')'):
        inner = s[4:-1].strip()
        try:
            return int(inner)
        except ValueError as e:
            raise e
    elif s.startswith('str(') and s.endswith(')'):
        inner = s[4:-1].strip()
        val = _parse_value(inner)
        return str(val)
    elif s.startswith('repr(') and s.endswith(')'):
        inner = s[5:-1].strip()
        val = _parse_value(inner)
        return repr(val)
    elif s.startswith('len(') and s.endswith(')'):
        inner = s[4:-1].strip()
        val = _parse_value(inner)
        return len(val)

    return None


def _split_top_level(s):
    """Split a string on commas that are at the top level (not inside brackets/braces/parens/strings)."""
    if not s:
        return []

    results = []
    current = []
    depth = 0
    in_string = False
    quote_char = None
    i = 0

    while i < len(s):
        ch = s[i]

        if in_string:
            current.append(ch)
            if ch == '\\' and i + 1 < len(s):
                current.append(s[i+1])
                i += 1
            elif ch == quote_char:
                in_string = False
        else:
            if ch in ('"', "'"):
                in_string = True
                quote_char = ch
                current.append(ch)
            elif ch in ('(', '[', '{'):
                depth += 1
                current.append(ch)
            elif ch in (')', ']', '}'):
                depth -= 1
                current.append(ch)
            elif ch == ',' and depth == 0:
                results.append(''.join(current).strip())
                current = []
            else:
                current.append(ch)

        i += 1

    final = ''.join(current).strip()
    if final:
        results.append(final)

    return results


