    # Helper functions for creating test values
    def make_val(token):
        token = token.strip()
        if token == "''":
            return ""
        elif token == "'a'":
            return 'a'
        elif token == "1":
            return 1
        elif token == "1.0":
            return 1.0
        elif token == "None":
            return None
        elif token.startswith("[") and token.endswith("]"):
            inner = token[1:-1].strip()
            if inner == "":
                return []
            parts = inner.split(',')
            return [make_val(p) for p in parts]
        elif token.startswith("(") and token.endswith(")"):
            inner = token[1:-1].strip()
            if inner == "":
                return ()
            parts = inner.split(',')
            return tuple(make_val(p) for p in parts)
        elif token.startswith("{") and token.endswith("}"):
            inner = token[1:-1].strip()
            if inner == "":
                return set()
            parts = inner.split(',')
            return {make_val(p) for p in parts}
        elif "float('nan')" in token or token == "float('nan')":
            return float('nan')
        else:
            raise ValueError(f"Cannot parse: {token}")

    # Split by comparison operator
    # Operators in order of length (longest first) to avoid mis-parsing
    operators = ['<=', '>=', '==', '<', '>', '!=']

    # Find the operator at top level (not inside brackets/braces/parens)
    op_pos = -1
    op_found = ""
    depth = 0
    i = 0
    while i < len(s):
        ch = s[i]
        if ch in '([{':
            depth += 1
        elif ch in ')]}':
            depth -= 1
        elif depth == 0:
            # Check for two-char operators
            if i + 1 < len(s):
                two = s[i:i+2]
                if two in ('<=', '>=', '=='):
                    op_pos = i
                    op_found = two
                    break
            # Single char operators
            if ch in ('<', '>', '!'):
                op_pos = i
                op_found = ch
                break
        i += 1

    if op_pos == -1:
        # No comparison found - shouldn't happen for these cases
        raise ValueError(f"No operator found in: {s}")

    left_str = s[:op_pos].strip()
    right_str = s[op_pos + len(op_found):].strip()

    left_val = make_val(left_str)
    right_val = make_val(right_str)

    # Perform the comparison
    if op_found == '<':
        return left_val < right_val
    elif op_found == '>':
        return left_val > right_val
    elif op_found == '<=':
        return left_val <= right_val
    elif op_found == '>=':
        return left_val >= right_val
    elif op_found == '==':
        return left_val == right_val
    elif op_found == '!=':
        return left_val != right_val
    else:
        raise ValueError(f"Unknown operator: {op_found}")


