            elif name == 'None':
                return None
            elif name == 'float':
                return float
            elif name == 'int':
                return int
            elif name == 'str':
                return str
            elif name == 'list':
                return list
            elif name == 'tuple':
                return tuple
            elif name == 'dict':
                return dict
            elif name == 'set':
                return set
            elif name == 'sorted':
                return sorted
            else:
                raise NameError("Name not allowed: " + name)
        if isinstance(node, ast.Index):  # Python 2 style subscript
            return node_to_literal(node.value)
        if isinstance(node, ast.Subscript):
            base = node_to_literal(node.value)
            if isinstance(node.slice, ast.Slice):
                lower = node_to_literal(node.slice.lower) if node.slice.lower else None
                upper = node_to_literal(node.slice.upper) if node.slice.upper else None
                step = node_to_literal(node.slice.step) if node.slice.step else None
