                return base[idx]
        if isinstance(node, ast.IfExp):
            test_val = node_to_literal(node.test)
            if test_val:
                return node_to_literal(node.body)
            else:
                return node_to_literal(node.orelse)
        raise ValueError("Unsupported AST node type: " + type(node).__name__)

    return node_to_literal(tree)


