import ast

def _safe_eval(node):
    """Evaluate an AST node in a limited environment."""
    if isinstance(node, ast.Expression):
        return _safe_eval(node.body)
    elif isinstance(node, ast.Name):
        env = {'float': float, 'None': None, 'sorted': sorted}
        if node.id in env:
            return env[node.id]
        else:
            raise NameError("name '%s' is not defined" % node.id)
    elif isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Num):  # for older Python compatibility
        return node.n
    elif isinstance(node, ast.Str):
        return node.s
    elif isinstance(node, ast.List):
        return [_safe_eval(el) for el in node.elts]
    elif isinstance(node, ast.Tuple):
        return tuple(_safe_el for _safe_el in (_safe_eval(el) for el in node.elts))
    elif isinstance(node, ast.Set):
        return {_safe_eval(el) for el in node.elts}
    elif isinstance(node, ast.Call):
        func = _safe_eval(node.func)
        args = [_safe_eval(a) for a in node.args]
        kwargs = {kw.arg: _safe_eval(kw.value) for kw in node.keywords}
        return func(*args, **kwargs)
    elif isinstance(node, ast.Compare):
        left = _safe_eval(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = _safe_eval(comparator)
            if isinstance(op, ast.Lt):
                result = left < right
            elif isinstance(op, ast.LtE):
                result = left <= right
            elif isinstance(op, ast.Gt):
                result = left > right
            elif isinstance(op, ast.GtE):
                result = left >= right
            elif isinstance(op, ast.Eq):
                result = left == right
            elif isinstance(op, ast.NotEq):
                result = left != right
            elif isinstance(op, ast.In):
                result = left in right
            elif isinstance(op, ast.NotIn):
                result = left not in right
            elif isinstance(op, ast.Is):
                result = left is right
            elif isinstance(op, ast.IsNot):
                result = left is not right
            else:
                raise ValueError("Unknown operator")
            if not result:
                return False
            left = right
        return True
    elif isinstance(node, ast.UnaryOp):
        operand = _safe_eval(node.operand)
        if isinstance(node.op, ast.USub):
            return -operand
        elif isinstance(node.op, ast.UAdd):
            return +operand
        elif isinstance(node.op, ast.Not):
            return not operand
        else:
            raise ValueError("Unknown unary operator")
    elif isinstance(node, ast.BinOp):
        left = _safe_eval(node.left)
        right = _safe_eval(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        elif isinstance(node.op, ast.Sub):
            return left - right
        elif isinstance(node.op, ast.Mult):
            return left * right
        elif isinstance(node.op, ast.Div):
            return left / right
        elif isinstance(node.op, ast.FloorDiv):
            return left // right
        elif isinstance(node.op, ast.Mod):
            return left % right
        elif isinstance(node.op, ast.Pow):
            return left ** right
        elif isinstance(node.op, ast.BitAnd):
            return left & right
        elif isinstance(node.op, ast.BitOr):
            return left | right
        elif isinstance(node.op, ast.BitXor):
            return left ^ right
        elif isinstance(node.op, ast.LShift):
            return left << right
        elif isinstance(node.op, ast.RShift):
            return left >> right
        else:
            raise ValueError("Unknown binary operator")
    elif isinstance(node, ast.Attribute):
        value = _safe_eval(node.value)
        return getattr(value, node.attr)
    elif isinstance(node, ast.Index):  # for older Python versions
        return _safe_eval(node.value)
    else:
        raise ValueError("Cannot evaluate node of type %s" % type(node).__name__)

