def is_word_char_unicode(c, i, s):
    """Check if c at position i in string s is a word character per Unicode."""
    ch = s[i]
    cp = ord(ch)
    # ASCII word chars
    if (0x30 <= cp <= 0x39) or (0x41 <= cp <= 0x5A) or (0x61 <= cp <= 0x7A) or cp == 0x5F:
        return True
    # Underscore and other connector punctuation
    if cp == 0x5F:
        return True
    # Check Unicode categories using unicodedata
    import unicodedata
    cat = unicodedata.category(ch)
    # L*, Nl, No are letters/numbers; Mn, Mc are combining marks considered part of words
    if cat.startswith('L') or cat.startswith('N'):
        return True
    return False


def is_digit_unicode(c):
    ch = c
    cp = ord(ch)
    if 0x30 <= cp <= 0x39:
        return True
    import unicodedata
    cat = unicodedata.category(ch)
    if cat in ('Nd', 'Nl', 'No'):
        return True
    return False


def is_space_unicode(c):
    ch = c
    cp = ord(ch)
    if cp in (0x20, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F, 0x85, 0xA0):
        return True
    import unicodedata
    cat = unicodedata.category(ch)
    if cat.startswith('Z') or cat in ('Cc', 'Cf') and unicodedata.bidirectional(ch) in ('WS', 'BA', 'BOM'):
        return True
    # More careful check
    return unicodedata.category(ch).startswith('Z') or cp in (0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x1C, 0x1D, 0x1E, 0x1F, 0x20, 0x85, 0xA0)


