def parse_const(s):
    """Parse a simple literal expression."""
    # Handle None, True, False
    if s == "None":
        return None
    if s == "True":
        return True
    if s == "False":
        return False
    # Handle integers (including negative)
    if s.lstrip('-').isdigit():
        return int(s)
    # Handle strings (single or double quoted)
    if len(s) >= 2 and ((s[0] == "'" and s[-1] == "'") or (s[0] == '"' and s[-1] == '"')):
        # Unescape: for simplicity, use repr approach
        inner = s[1:-1]
        # Try to unescape common sequences
        result = []
        i = 0
        while i < len(inner):
            if inner[i] == '\\' and i + 1 < len(inner):
                nxt = inner[i+1]
                if nxt == 'n':
                    result.append('\n')
                elif nxt == 't':
                    result.append('\t')
                elif nxt == '\\':
                    result.append('\\')
                elif nxt == "'":
                    result.append("'")
                elif nxt == '"':
                    result.append('"')
                elif nxt == 'r':
                    result.append('\r')
                elif nxt == 'b':
                    result.append('\b')
                elif nxt == 'f':
                    result.append('\f')
                elif nxt == 'v':
                    result.append('\v')
                else:
                    result.append('\\')
                    result.append(nxt)
                i += 2
            else:
                result.append(inner[i])
                i += 1
        return ''.join(result)
    # Handle lists like [97]
    if s.startswith('[') and s.endswith(']'):
        inner = s[1:-1].strip()
        if not inner:
            return []
        items = []
        # Split by comma, respecting nesting
        depth = 0
        current = []
        for ch in inner:
            if ch in '([{':
                depth += 1
            elif ch in ')]}':
                depth -= 1
            if ch == ',' and depth == 0:
                items.append(''.join(current).strip())
                current = []
            else:
                current.append(ch)
        if current:
            items.append(''.join(current).strip())
        return [parse_const(item) for item in items]
    # Handle tuples like (97,)
    if s.startswith('(') and s.endswith(')'):
        inner = s[1:-1].strip()
        if not inner:
            return ()
        # Check if it's a single element with trailing comma
        if inner.endswith(','):
            inner = inner[:-1].strip()
        items = []
        depth = 0
        current = []
        for ch in inner:
            if ch in '([{':
                depth += 1
            elif ch in ')]}':
                depth -= 1
            if ch == ',' and depth == 0:
                items.append(''.join(current).strip())
                current = []
            else:
                current.append(ch)
        if current:
            items.append(''.join(current).strip())
        return tuple(parse_const(item) for item in items)
    raise ValueError("Cannot parse: %s" % s)

