            left = self.result
            for op, comp in zip(node.ops, node.comparators):
                self.visit(comp)
                right = self.result
                if isinstance(op, ast.Eq):
                    res = left == right
                elif isinstance(op, ast.NotEq):
                    res = left != right
                elif isinstance(op, ast.Lt):
                    res = left < right
                elif isinstance(op, ast.LtE):
                    res = left <= right
                elif isinstance(op, ast.Gt):
                    res = left > right
                elif isinstance(op, ast.GtE):
                    res = left >= right
                elif isinstance(op, ast.Is):
                    res = left is right
                elif isinstance(op, ast.IsNot):
                    res = left is not right
                elif isinstance(op, ast.In):
                    res = left in right
                elif isinstance(op, ast.NotIn):
                    res = left not in right
                if not res:
                    self.result = False
                    return self.result
                left = right
            self.result = True
            return self.result

        def visit_Call(self, node):
            # Get the function
            self.visit(node.func)
            func = self.result
            args = []
            for a in node.args:
                self.visit(a)
                args.append(self.result)
            kwargs = {}
            for kw in node.keywords:
                self.visit(kw.value)
                kwargs[kw.arg] = self.result
            self.result = func(*args, **kwargs)
            return self.result

        def visit_Attribute(self, node):
            self.visit(node.value)
            obj = self.result
            self.result = getattr(obj, node.attr)
            return self.result

        def visit_List(self, node):
            items = []
            for el in node.elts:
                self.visit(el)
                items.append(self.result)
            self.result = items
            return self.result

        def visit_Tuple(self, node):
            items = []
            for el in node.elts:
                self.visit(el)
                items.append(self.result)
            self.result = tuple(items)
            return self.result

        def visit_Dict(self, node):
            d = {}
            for k, v in zip(node.keys, node.values):
                self.visit(k)
                key = self.result
                self.visit(v)
                val = self.result
                d[key] = val
            self.result = d
            return self.result

        def visit_Set(self, node):
            items = set()
            for el in node.elts:
                self.visit(el)
                items.add(self.result)
            self.result = items
            return self.result

        def visit_Name(self, node):
            if node.id == 'True':
                self.result = True
            elif node.id == 'False':
                self.result = False
            elif node.id == 'None':
                self.result = None
            else:
                raise NameError(f"name '{node.id}' is not defined")
            return self.result

        def visit_Num(self, node):
            self.result = node.n
            return self.result

        def visit_Str(self, node):
            self.result = node.s
            return self.result

        def visit_Index(self, node):
            return self.visit(node.value)

    ev = Evaluator()
    ev.visit(tree)
    return ev.result

