            return node.value
        elif isinstance(node, ast.Call):
            func = _resolve_func(node.func)
            args = [_node_value(a) for a in node.args]
            kwargs = {kw.arg: _node_value(kw.value) for kw in node.keywords}
            return func(*args, **kwargs)
        elif isinstance(node, ast.BinOp):
            left = _node_value(node.left)
            right = _node_value(node.right)
            op = type(node.op).__name__
            if op == 'Add':
                return left + right
            elif op == 'Sub':
                return left - right
            elif op == 'Mult':
                return left * right
            elif op == 'Div':
                return left / right
            elif op == 'FloorDiv':
                return left // right
            elif op == 'Mod':
                return left % right
            elif op == 'Pow':
                return left ** right
            else:
                raise ValueError("Unsupported operator: " + op)
        elif isinstance(node, ast.Compare):
            ops = type(node.ops[0]).__name__
            left = _node_value(node.left)
            comps = [_node_value(c) for c in node.comparators]
            if len(comps) == 1 and left is not None:
                if ops == 'In':
                    return left in comps[0]
                elif ops == 'NotIn':
                    return left not in comps[0]
                elif ops == 'Eq':
                    return left == comps[0]
                elif ops == 'NotEq':
                    return left != comps[0]
                elif ops == 'Lt':
                    return left < comps[0]
                elif ops == 'LtE':
                    return left <= comps[0]
                elif ops == 'Gt':
                    return left > comps[0]
                elif ops == 'GtE':
                    return left >= comps[0]
            raise ValueError("Compare not supported")
        elif isinstance(node, ast.UnaryOp):
            operand = _node_value(node.operand)
            optype = type(node.op).__name__
            if optype == 'USub':
                return -operand
            elif optype == 'UAdd':
                return +operand
            elif optype == 'Not':
                return not operand
            elif optype == 'Invert':
                return ~operand
            raise ValueError("Unary op not supported: " + optype)
        elif isinstance(node, (ast.List, ast.Tuple)):
            elts = [_node_value(e) for e in node.elts]
            if isinstance(node, ast.List):
                return elts
            else:
                if len(elts) == 1:
                    return elts[0]
                return tuple(elts)
        elif isinstance(node, ast.Attribute):
            raise ValueError("Attribute access not allowed")
        elif isinstance(node, ast.Name):
            raise ValueError("Name reference not allowed: " + node.id)
        else:
            raise ValueError("Unsupported AST node: " + type(node).__name__)

    def _resolve_func(node):
        # Handle b'abc'.method or other calls
        if isinstance(node, ast.Attribute):
            obj = _node_value(node.value)
            method_name = node.attr
            return getattr(obj, method_name)
        elif isinstance(node, ast.Name):
            if node.id == 'bytes':
                return bytes
            raise ValueError("Builtin name not allowed: " + node.id)
        else:
            raise ValueError("Cannot resolve function: " + type(node).__name__)

    return _node_value(tree)


