def _eval_node(node, ns):
    if isinstance(node, ast.Expression):
        return _eval_node(node.body, ns)
    elif isinstance(node, ast.Call):
        func = node.func
        if isinstance(func, ast.Attribute):
            # b'abc'.method(...) or 'a' in b'abc' etc.
            val_obj = _eval_node(func.value, ns)
            method_name = func.attr
            args = [_eval_node(a, ns) for a in node.args]
            if hasattr(val_obj, method_name):
                return getattr(val_obj, method_name)(*args)
            else:
                raise AttributeError("'{}' object has no attribute '{}'".format(type(val_obj).__name__, method_name))
        elif isinstance(func, ast.Name):
            name = func.id
            args = [_eval_node(a, ns) for a in node.args]
            if name in ns:
                return ns[name](*args)
            else:
                raise NameError("name '{}' is not defined".format(name))
    elif isinstance(node, ast.BinOp):
        left = _eval_node(node.left, ns)
        right = _eval_node(node.right, ns)
        if isinstance(node.op, ast.Add):
            return left + right
        else:
            raise ValueError("Unsupported binary op")
    elif isinstance(node, ast.UnaryOp):
        operand = _eval_node(node.operand, ns)
        if isinstance(node.op, ast.Not):
            return not operand
        elif isinstance(node.op, ast.USub):
            return -operand
    elif isinstance(node, ast.Compare):
        left = _eval_node(node.left, ns)
        for op, comparator in zip(node.ops, node.comparators):
            right = _eval_node(comparator, ns)
            if isinstance(op, ast.In):
                if left not in right:
                    return False
            elif isinstance(op, ast.Eq):
                if left != right:
                    return False
            else:
                raise ValueError("Unsupported compare op")
        return True
    elif isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.List):
        return [_eval_node(el, ns) for el in node.elts]
    elif isinstance(node, ast.Tuple):
        return tuple(_eval_node(el, ns) for el in node.elts)
    elif isinstance(node, ast.Name):
        return ns[node.id]
    else:
        raise ValueError("Unsupported AST node: {}".format(type(node).__name__))

