            dot_idx = rest.index('.')
            attr_and_rest = rest[dot_idx:]

            # Check if it's a direct method call with args
            if '(' in attr_and_rest and ')' in attr_and_rest:
                open_paren = attr_and_rest.index('(')
                method_name = attr_and_rest[1:open_paren].strip()
