                    return v
                if isinstance(node.op, ast.Or) and v:
                    return v
                values.append(v)
            return values[-1] if values else None

        def visit_Compare(self, node):
            left = self.visit(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = self.visit(comparator)
                if isinstance(op, ast.Eq):
                    if not (left == right):
                        return False
                elif isinstance(op, ast.NotEq):
                    if not (left != right):
                        return False
                elif isinstance(op, ast.Lt):
                    if not (left < right):
                        return False
                elif isinstance(op, ast.LtE):
                    if not (left <= right):
                        return False
                elif isinstance(op, ast.Gt):
                    if not (left > right):
                        return False
                elif isinstance(op, ast.GtE):
                    if not (left >= right):
                        return False
                elif isinstance(op, ast.Is):
                    if not (left is right):
                        return False
                elif isinstance(op, ast.IsNot):
                    if not (left is not right):
                        return False
                elif isinstance(op, ast.In):
                    if not (left in right):
                        return False
                elif isinstance(op, ast.NotIn):
                    if not (left not in right):
                        return False
                left = right
            return True

        def visit_Call(self, node):
            func = self.visit(node.func)
            args = [self.visit(arg) for arg in node.args]
            keywords = {}
            for kw in node.keywords:
                if kw.arg is not None:
                    keywords[kw.arg] = self.visit(kw.value)
                else:
                    raise Exception("Unexpected keyword argument")
            try:
                return func(*args, **keywords)
            except TypeError as e:
                raise

        def visit_Attribute(self, node):
            value = self.visit(node.value)
            return getattr(value, node.attr)

        def visit_Subscript(self, node):
            value = self.visit(node.value)
            index = self.visit(node.slice)
            return value[index]

        def visit_List(self, node):
            return [self.visit(el) for el in node.elts]

        def visit_Tuple(self, node):
            return tuple(self.visit(el) for el in node.elts)

        def visit_Dict(self, node):
            result = {}
            for key, value in zip(node.keys, node.values):
                k = self.visit(key) if key else None
                v = self.visit(value)
                result[k] = v
            return result

        def visit_Set(self, node):
            return {self.visit(el) for el in node.elts}

        def visit_FormattedValue(self, node):
            value = self.visit(node.value)
            format_spec = self.visit(node.format_spec) if node.format_spec else ""
            return format(value, format_spec) if format_spec else str(value)

        def visit_JoinedStr(self, node):
            parts = []
            for value in node.values:
                if isinstance(value, ast.Constant):
                    parts.append(str(value.value))
                elif isinstance(value, ast.FormattedValue):
                    parts.append(self.visit(value))
                else:
                    raise Exception("Unsupported f-string component")
            return "".join(parts)

    # Provide needed builtins
    b = {'bytes': bytes, 'int': int, 'str': str, 'True': True, 'False': False, 'None': None}
    return NodeVisitor(b).visit(tree)

