def safe_eval(arg, func):
    """Compute the result of calling bytes method `func` with argument `arg` (string)."""
    data = b'abc'

    if arg == "1":
        a = 1
    elif arg == "'a'":
        a = 'a'
    elif arg == "[97]":
        a = [97]
    elif arg == "(97,)":
        a = (97,)
    elif arg == "None":
        a = None
    else:
        # Must be string literal like b'' or b'X' - handled in special cases
        return None  # Signal to handle specially

    f = getattr(data, func)
    try:
        r = f(a)
        return ("ok", repr(r))
    except Exception as e:
        return ("err", type(e).__name__, str(e))

