def parse_literal(s):
    # s is one of: '1', "'a'", '[97]', '(97,)', 'None', '97'
    if s == 'None':
        return None
    if s.startswith("'") and s.endswith("'"):
        return s[1:-1]  # for our inputs this gives the string content
    try:
        val = int(s)
        return val
    except ValueError:
        pass
    if s.startswith('[') and s.endswith(']'):
        inner = s[1:-1].strip()
        if not inner:
            return []
        return [int(x) for x in inner.split(',')]
    if s.startswith('(') and s.endswith(')'):
        inner = s[1:-1].strip()
        if not inner:
            return ()
        return tuple(int(x) for x in inner.split(','))
    raise ValueError("Cannot parse literal: %s" % s)

