import ast


class SafeEval(ast.AST):
    """A small AST evaluator that supports the subset of expressions used here."""

    def __init__(self, node):
        self.node = node

    @staticmethod
    def _eval(node, env):
        if isinstance(node, ast.Expression):
            return SafeEval._eval(node.body, env)
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            return env.get(node.id)
        elif isinstance(node, ast.List):
            return [SafeEval._eval(el, env) for el in node.elts]
        elif isinstance(node, ast.Tuple):
            return tuple(SafeEval._eval(el, env) for el in node.elts)
        elif isinstance(node, ast.BinOp):
            left = SafeEval._eval(node.left, env)
            right = SafeEval._eval(node.right, env)
            op_type = type(node.op).__name__
            if op_type == 'Add':
                return left + right
            elif op_type == 'Sub':
                return left - right
            elif op_type == 'Mult':
                return left * right
            elif op_type == 'Div':
                return left / right
            elif op_type == 'Mod':
                return left % right
            elif op_type == 'Pow':
                return left ** right
            elif op_type == 'FloorDiv':
                return left // right
            else:
                raise Exception("Unsupported binary operator: " + op_type)
        elif isinstance(node, ast.UnaryOp):
            operand = SafeEval._eval(node.operand, env)
            op_type = type(node.op).__name__
            if op_type == 'USub':
                return -operand
            elif op_type == 'UAdd':
                return +operand
            elif op_type == 'Not':
                return not operand
            elif op_type == 'Invert':
                return ~operand
            else:
                raise Exception("Unsupported unary operator: " + op_type)
        elif isinstance(node, ast.BoolOp):
            if type(node.op).__name__ == 'And':
                result = True
                for v in node.values:
                    result = SafeEval._eval(v, env)
                    if not result:
                        break
                return result
            elif type(node.op).__name__ == 'Or':
                result = False
                for v in node.values:
                    result = SafeEval._eval(v, env)
                    if result:
                        break
                return result
        elif isinstance(node, ast.Call):
            func_name = None
            if isinstance(node.func, ast.Name):
                func_name = node.func.id
            elif isinstance(node.func, ast.Attribute):
                # e.g., b'abc'.find(...) -> value.attr(...)
                obj = SafeEval._eval(node.func.value, env)
                attr = node.func.attr
                args = [SafeEval._eval(a, env) for a in node.args]
                kwargs = {kw.arg: SafeEval._eval(kw.value, env) for kw in node.keywords}
                return getattr(obj, attr)(*args, **kwargs)
            else:
                raise Exception("Unsupported call")
            args = [SafeEval._eval(a, env) for a in node.args]
            kwargs = {kw.arg: SafeEval._eval(kw.value, env) for kw in node.keywords}
            if func_name == 'len':
                return len(args[0])
            elif func_name == 'str':
                return str(args[0]) if args else ""
            elif func_name == 'repr':
                return repr(args[0]) if args else ""
            elif func_name == 'print':
                print(*args)
                return None
            elif func_name == 'bytes':
                return bytes(*args, **kwargs)
            elif func_name == 'int':
                return int(*args, **kwargs)
            elif func_name == 'chr':
                return chr(*args, **kwargs)
            elif func_name == 'ord':
                return ord(*args, **kwargs)
            elif func_name == 'type':
                if args:
                    return type(args[0])
                return type
            else:
                raise Exception("Unsupported function: " + func_name)
        elif isinstance(node, ast.Compare):
            left = SafeEval._eval(node.left, env)
            for op, comparator in zip(node.ops, node.comparators):
                right = SafeEval._eval(comparator, env)
                op_type = type(op).__name__
                if op_type == 'Eq':
                    if not (left == right):
                        return False
                elif op_type == 'NotEq':
                    if not (left != right):
                        return False
                elif op_type == 'Lt':
                    if not (left < right):
                        return False
                elif op_type == 'LtE':
                    if not (left <= right):
                        return False
                elif op_type == 'Gt':
                    if not (left > right):
                        return False
                elif op_type == 'GtE':
                    if not (left >= right):
                        return False
                elif op_type == 'Is':
                    if not (left is right):
                        return False
                elif op_type == 'IsNot':
                    if not (left is not right):
                        return False
                elif op_type == 'In':
                    if left not in right:
                        return False
                elif op_type == 'NotIn':
                    if left in right:
                        return False
                else:
                    raise Exception("Unsupported comparison: " + op_type)
                left = right
            return True
        elif isinstance(node, ast.Subscript):
            value = SafeEval._eval(node.value, env)
            slice_node = node.slice
            idx = SafeEval._eval(slice_node, env)
            return value[idx]
        elif isinstance(node, ast.Attribute):
            value = SafeEval._eval(node.value, env)
            return getattr(value, node.attr)
        else:
            raise Exception("Unsupported AST node: " + type(node).__name__)


def safe_eval(expr_str):
    tree = ast.parse(expr_str, mode='eval')
    return SafeEval._eval(tree, {})


