import ast


def safe_eval(expr):
    """Evaluate a simple expression using AST, no eval()."""
    tree = ast.parse(expr, mode='eval')
    return _eval_node(tree.body)


def _eval_node(node):
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.JoinedStr):
        parts = []
        for v in node.values:
            if isinstance(v, ast.FormattedValue):
                val = _eval_node(v.value)
                spec = v.conversion
                fmt = v.format_spec
                if spec == 101:  # 'r'
                    parts.append(repr(val))
                else:
                    if fmt and not isinstance(fmt, ast.Constant):
                        fmt = _eval_node(fmt)
                    else:
                        fmt = ''
                    parts.append(format(val, fmt))
            elif isinstance(v, ast.Constant):
                parts.append(str(v.value))
        return ''.join(parts)
    elif isinstance(node, ast.Call):
        func = _eval_node(node.func)
        args = [_eval_node(a) for a in node.args]
        keywords = {}
        for kw in node.keywords:
            if kw.arg is None:
                # **kwargs - not expected here
                pass
            else:
                keywords[kw.arg] = _eval_node(kw.value)
        try:
            return func(*args, **keywords)
        except Exception as e:
            raise e
    elif isinstance(node, ast.Attribute):
        value = _eval_node(node.value)
        return getattr(value, node.attr)
    elif isinstance(node, ast.Name):
        names = {
            'b': b,
            'None': None,
            'True': True,
            'False': False,
            'bytes': bytes,
            'int': int,
            'repr': repr,
            'len': len,
        }
        if node.id in names:
            return names[node.id]
        raise NameError("name '%s' is not defined" % node.id)
    elif isinstance(node, ast.BinOp):
        left = _eval_node(node.left)
        right = _eval_node(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        elif isinstance(node.op, ast.Sub):
            return left - right
        elif isinstance(node.op, ast.Mult):
            return left * right
        elif isinstance(node.op, ast.Div):
            return left / right
        elif isinstance(node.op, ast.FloorDiv):
            return left // right
        elif isinstance(node.op, ast.Mod):
            return left % right
        elif isinstance(node.op, ast.Pow):
            return left ** right
        else:
            raise NotImplementedError("operator %s" % type(node.op).__name__)
    elif isinstance(node, ast.UnaryOp):
        operand = _eval_node(node.operand)
        if isinstance(node.op, ast.UAdd):
            return +operand
        elif isinstance(node.op, ast.USub):
            return -operand
        elif isinstance(node.op, ast.Not):
            return not operand
        else:
            raise NotImplementedError("unary operator %s" % type(node.op).__name__)
    elif isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = True
            for v in node.values:
                result = _eval_node(v)
                if not result:
                    return result
            return result
        elif isinstance(node.op, ast.Or):
            result = False
            for v in node.values:
                result = _eval_node(v)
                if result:
                    return result
            return result
    elif isinstance(node, ast.Compare):
        left = _eval_node(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = _eval_node(comparator)
            if isinstance(op, ast.Eq):
                if not (left == right):
                    return False
            elif isinstance(op, ast.NotEq):
                if not (left != right):
                    return False
            elif isinstance(op, ast.Lt):
                if not (left < right):
                    return False
            elif isinstance(op, ast.LtE):
                if not (left <= right):
                    return False
            elif isinstance(op, ast.Gt):
                if not (left > right):
                    return False
            elif isinstance(op, ast.GtE):
                if not (left >= right):
                    return False
            elif isinstance(op, ast.In):
                if not (left in right):
                    return False
            elif isinstance(op, ast.NotIn):
                if not (left not in right):
                    return False
            elif isinstance(op, ast.Is):
                if not (left is right):
                    return False
            elif isinstance(op, ast.IsNot):
                if not (left is not right):
                    return False
            else:
                raise NotImplementedError("comparison operator %s" % type(op).__name__)
            left = right
        return True
    elif isinstance(node, ast.IfExp):
        test = _eval_node(node.test)
        if test:
            return _eval_node(node.body)
        else:
            return _eval_node(node.orelse)
    elif isinstance(node, ast.List):
        return [_eval_node(e) for e in node.elts]
    elif isinstance(node, ast.Tuple):
        return tuple(_eval_node(e) for e in node.elts)
    elif isinstance(node, ast.Dict):
        d = {}
        for k, v in zip(node.keys, node.values):
            if k is None:
                # **kwargs in dict literal
                continue
            key = _eval_node(k)
            val = _eval_node(v)
            d[key] = val
        return d
    elif isinstance(node, ast.Set):
        return set(_eval_node(e) for e in node.elts)
    elif isinstance(node, ast.Subscript):
        value = _eval_node(node.value)
        index = _eval_node(node.slice)
        return value[index]
    elif isinstance(node, ast.Index):  # Python 3.8 compat
        return _eval_node(node.value)
    elif isinstance(node, ast.Slice):
        lower = _eval_node(node.lower) if node.lower else None
        upper = _eval_node(node.upper) if node.upper else None
        step = _eval_node(node.step) if node.step else None
        return slice(lower, upper, step)
    elif isinstance(node, ast.Starred):
        return _eval_node(node.value)
    else:
        raise NotImplementedError("node type %s" % type(node).__name__)


