# Define a frozenset-like class using __slots__ to save memory and ensure hashability via set
class FrozenSet:
    """A minimal frozenset replacement."""
    __slots__ = ('_set',)

    def __init__(self, iterable=None):
        if iterable is None:
            self._set = set()
        else:
            self._set = set(iterable)

    def __iter__(self):
        return iter(self._set)

    def __contains__(self, item):
        return item in self._set

    def __len__(self):
        return len(self._set)

    def __hash__(self):
        # Hash consistent with frozenset semantics for sets of hashes.
        # For a standard frozen set of ints, this should match frozenset([1,2]).__hash__()
        h = 0
        for x in self._set:
            h ^= hash(x)
        # The actual algorithm is more complex, but for the tests here (small sets of ints/strings),
        # we need identity/equality to work correctly for dict/set operations.
        # If we use a simple XOR, [1,2] gives hash(1)^hash(2).
        # But does it matter? In Python, if obj1 == obj2, then hash(obj1)==hash(obj2).
        # The `in` check will first compare hashes, then equality.
        # So as long as equal objects have equal hashes, it works.
        return h

    def __eq__(self, other):
        if isinstance(other, FrozenSet):
            return self._set == other._set
        if isinstance(other, set):
            return self._set == other
        return NotImplemented

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __repr__(self):
        return "FrozenSet" + str(list(self._set))

# Helper to create FrozenSet from list/tuple
def fs(items):
    return FrozenSet(items)

