from collections.abc import Set as _AbcSet

class _FS(tuple):
    __slots__ = ()
    def __new__(cls, it=()):
        if isinstance(it, _FS):
            return it
        t = tuple(it)
        for x in t:
            hash(x)  # raises TypeError for unhashable, like frozenset
        return super().__new__(cls, t)

    def __repr__(self):
        s = self._tostr()
        if s.startswith('['):
            s = '{' + s[1:-1] + '}'
        return 'frozenset(' + s + ')'

    def _tostr(self):
        parts = []
        for x in self:
            r = repr(x)
            if isinstance(x, _FS):
                r = x._tostr()
            parts.append(r)
        if not parts:
            return '[]'
        return '[' + ', '.join(parts) + ']'

    @classmethod
    def __subclasshook__(cls, C):
