import sys

# Replace frozenset with a minimal hashable container that behaves like frozenset
class FZ:
    __slots__ = ('_data',)

    def __init__(self, iterable=()):
        self._data = tuple(sorted(iterable, key=lambda x: (str(type(x).__name__), str(x))) if not isinstance(iterable, (list, tuple)) else sorted(iterable, key=lambda x: (str(type(x).__name__), str(x))))
        # Better: just store as frozenset-like via set then convert to canonical form
        s = set(iterable)
        # Convert to a canonical representation that is hashable and comparable
        self._data = tuple(sorted(s, key=lambda x: (x.__hash__() if callable(getattr(x, '__hash__', None)) else -1, repr(x), type(x).__name__, str(x))))

    def __repr__(self):
        return f'FZ({self._data!r})'

    def __eq__(self, other):
        if isinstance(other, FZ):
            return self._data == other._data
        elif isinstance(other, (set, frozenset)):
            try:
                othertuple = tuple(sorted(other, key=lambda x: (x.__hash__() if callable(getattr(x, '__hash__', None)) else -1, repr(x), type(x).__name__, str(x))))
            except Exception:
                return False
            return self._data == othertuple
        elif isinstance(other, (list, tuple)):
            try:
                s = set(other)
                othertuple = tuple(sorted(s, key=lambda x: (x.__hash__() if callable(getattr(x, '__hash__', None)) else -1, repr(x), type(x).__name__, str(x))))
                return self._data == othertuple
            except Exception:
                return False
        else:
            return NotImplemented

    def __ne__(self, other):
        result = self.__eq__(other)
        if result is NotImplemented:
            return result
        return not result

    def __hash__(self):
        return hash(self._data)

    def __len__(self):
        return len(self._data)

    def __contains__(self, item):
        return item in set(self._data)


