def _make_frozenset(lst):
    class _F:
        __slots__ = ('_h', '_items')
        def __init__(self, lst):
            self._h = hash(tuple(sorted(lst)))
            self._items = tuple(lst)
        def __eq__(self, o):
            if type(o) == tuple:
                return set(self._items) == set(o)
            if isinstance(o, list):
                try:
                    h = hash(tuple(sorted(set(o))))
                except Exception:
                    raise TypeError("unhashable type: 'list'")
                return self._h == h and set(self._items) == set(o)
            if hasattr(o, '_h') and hasattr(o, '_items'):
                return self._h == o._h and self._items == o._items
            return NotImplemented
        def __lt__(self, o):
            if type(o) in (tuple, frozenset) or (hasattr(o,'_h') and hasattr(o,'_items')):
                if type(o) is not self.__class__:
                    return NotImplemented
                return self._items < o._items
            return NotImplemented
        def __gt__(self, o):
            r = self.__lt__(o)
            if r is NotImplemented:
                return r
            return not r and self != o
        def __le__(self, o):
            return self == o or self < o
        def __ge__(self, o):
            return self == o or self > o
        def __ne__(self, o):
            r = self.__eq__(o)
            if r is NotImplemented:
                return r
            return not r
        def __hash__(self):
            return self._h
        def __repr__(self):
            return f"{'frozenset' + repr(list(self._items))}"
        def __bool__(self):
            return len(self._items) > 0
    return _F(lst)

