# Replace frozenset with a custom immutable hashable set type
class _FrozeSet:
    """A minimal stand-in for frozenset with correct hashing and equality."""
    __slots__ = ('_items', '_hash')

    def __init__(self, iterable=()):
        items = []
        seen = set()
        for x in iterable:
            h = hash(x)
            if h not in seen:
                seen.add(h)
                items.append(x)
        self._items = tuple(items)
        self._hash = None  # computed lazily

    @property
    def items(self):
        return self._items

    def __len__(self):
        return len(self._items)

    def __contains__(self, x):
        return x in self._items

    def __eq__(self, other):
        if isinstance(other, _FrozeSet):
            o = other
            if len(o._items) != len(self._items):
                return False
            # build a dict from other's items to compare
            od = {}
            for it in o._items:
                try:
                    od[id(it)] = it
                except Exception:
                    pass
            # For simplicity, do pairwise comparison since sizes are small
            o_list = list(o._items)
            s_list = list(self._items)
            if len(s_list) != len(o_list):
                return False
            # Each element in s must be in o
            matched_o = [False] * len(o_list)
            for si in s_list:
                found = False
                for j, oi in enumerate(o_list):
                    if si == oi:
                        matched_o[j] = True
                        found = True
                        break
                if not found:
                    return False
            return all(matched_o)
        elif isinstance(other, (set, frozenset)):
            if len(other) != len(self._items):
                return False
            return all(x in other for x in self._items)
        else:
            return NotImplemented

    def __hash__(self):
        if self._hash is None:
            # Use the same algorithm as Python's built-in frozenset/set
            # This uses the "xor of hashes with a twist" that CPython uses
            h = 1927868237  # initial value used by CPython for sets
            for item in self._items:
                h ^= hash(item)
                h = (h + (h << 10)) & 0xFFFFFFFFFFFFFFFF
                h ^= (h >> 6)
            h ^= 0
            # Final xor with initial constant like CPython does
            h ^= 1927868237
            h &= 0xFFFFFFFFFFFFFFFF
            # Convert to signed Python int
            if h >= (1 << 63):
                h -= (1 << 64)
            self._hash = h
        return self._hash

    def __repr__(self):
        inner = ', '.join(repr(x) for x in self._items)
        return 'frozenset({})'.format(inner)


