# Frozenset emulation: a read-only set that supports hashing.
class froz:
    """Emulates frozenset for this limited usage."""
    __slots__ = ('_hash', '_members')
    def __init__(self, iterable=()):
        if hasattr(iterable, '__iter__'):
            self._members = tuple(sorted(iterable, key=lambda x: (type(x).__name__, str(x))))
        else:
            # For empty or non-iterable, just store as tuple
            try:
                self._members = tuple(iterable)
            except TypeError:
                self._members = ()
        self._hash = hash(self._members)
    def __hash__(self):
        return self._hash
    def __eq__(self, other):
        if isinstance(other, froz):
            return self._members == other._members
        return False
    def __len__(self):
        return len(self._members)
    def __contains__(self, item):
        return item in self._members
    def __repr__(self):
        return 'froz(%r)' % (self._members,)
    def discard(self, item):
        raise AttributeError("frozenset object has no attribute 'discard'")
    def remove(self, item):
        raise AttributeError("frozenset object has no attribute 'remove'")

