def _make_dataclass(cls, field_names, default_values):
    fields = list(field_names)

    def __init__(self, *args, **kwargs):
        for i, fname in enumerate(fields):
            if i < len(args):
                val = args[i]
            else:
                if fname in kwargs:
                    val = kwargs[fname]
                else:
                    default = default_values.get(fname, None)
                    if callable(default):
                        val = default()
                    else:
                        val = default
            object.__setattr__(self, fname, val)

    def __eq__(self, other):
        if not isinstance(other, cls):
            return NotImplemented
        return all(getattr(self, f) == getattr(other, f) for f in fields)

    def __hash__(self):
        return hash(tuple(getattr(self, f) for f in fields))

    def __repr__(self):
        vals = ", ".join(f"{f}={getattr(self, f)!r}" for f in fields)
        return f"{cls.__name__}({vals})"

    def __setattr__(self, name, value):
        raise AttributeError("can't set attribute")

    cls.__init__ = __init__
    cls.__eq__ = __eq__
    cls.__hash__ = __hash__
    cls.__repr__ = __repr__
    cls.__setattr__ = __setattr__
    return cls


