import sys

def _make_dataclass(frozen, defaults=()):
    def decorator(cls):
        fields = list(cls.__annotations__)
        # Build a new class with proper __init__, __repr__, __eq__
        def __init__(self, *args):
            if len(args) != len(fields):
                raise TypeError("Expected %d arguments, got %d" % (len(fields), len(args)))
            for fname, val in zip(fields, args):
                object.__setattr__(self, fname, val)

        def __repr__(self):
            vals = []
            for fname in fields:
                v = object.__getattribute__(self, fname)
                vals.append("%s=%r" % (fname, v))
            return "%s(%s)" % (cls.__name__, ", ".join(vals))

        def __eq__(self, other):
            if not isinstance(other, cls):
                return NotImplemented
            for fname in fields:
                if object.__getattribute__(self, fname) != object.__getattribute__(other, fname):
                    return False
            return True

        if frozen:
            def __hash__(self):
                h = 0
                for fname in fields:
                    h = h * 31 + hash(object.__getattribute__(self, fname))
                return h
            def __setattr__(self, name, value):
                raise AttributeError("frozen instance")
            def __delattr__(self, name):
                raise AttributeError("frozen instance")
        else:
            def __hash__(self):
                return None
            # default __setattr__ from object

        cls.__init__ = __init__
        cls.__repr__ = __repr__
        cls.__eq__ = __eq__
        if frozen:
            cls.__hash__ = __hash__
            cls.__setattr__ = __setattr__
            cls.__delattr__ = __delattr__
        else:
            cls.__hash__ = __hash__
        return cls
    return decorator

