def _dc(cls, fields_spec):
    # fields_spec: list of (name, default_factory_or_default, frozen)
    names = [f[0] for f in fields_spec]

    def __init__(self, *args):
        if len(args) != len(fields_spec):
            raise TypeError(f"__init__ missing {len(fields_spec) - len(args)} required positional arguments")
        for i, (name, default, _frozen) in enumerate(fields_spec):
            setattr(self, name, args[i])

    def __eq__(self, other):
        if not isinstance(other, cls.__class__):
            return NotImplemented
        if type(self) is not type(other):
            return NotImplemented
        for name, _default, _frozen in fields_spec:
            if getattr(self, name) != getattr(other, name):
                return False
        return True

    def __hash__(self):
        return hash(tuple(getattr(self, name) for name, _d, _f in fields_spec))

    def __repr__(self):
        parts = []
        for name, _d, _f in fields_spec:
            val = getattr(self, name)
            v = repr(val)
            # If the value is an instance of the same class or contains a newline, keep it as-is
            parts.append(f"{name}={v}")
        return f"{cls.__qualname__}({', '.join(parts)})"

    cls.__init__ = __init__
    cls.__eq__ = __eq__
    cls.__hash__ = __hash__
    cls.__repr__ = __repr__
    return cls


