def _dataclass(frozen=True, **kwargs):
    def decorator(cls):
        if not hasattr(cls, '__annotations__'):
            cls.__annotations__ = {}
        defaults = {}
        for k in cls.__annotations__:
            if hasattr(cls, k):
                defaults[k] = getattr(cls, k)

        orig_init = getattr(cls, '__init__', None)

        def new_init(self, *args, **kw):
            annotations = cls.__annotations__
            fields = list(annotations.keys())
            values = []
            for i, name in enumerate(fields):
                if i < len(args):
                    values.append(args[i])
                elif name in kw:
                    values.append(kw[name])
                elif name in defaults:
                    d = defaults[name]
                    if callable(d):
                        # handle field(default_factory=dict) pattern
                        if hasattr(d, 'default_factory') and d is not None:
                            pass
                        values.append(d() if isinstance(d, dict) or isinstance(d, type) else d)
                    else:
                        values.append(d)
                else:
                    raise TypeError(f"missing argument {name}")

            self.__dict__ = dict(zip(fields, values))
            if frozen:
                object.__setattr__(self, '_frozen', True)

        class Meta(type(cls)):
            pass

        cls.__init__ = new_init

        def __hash__(self):
            return hash(tuple((k, v) for k, v in self.__dict__.items()))

        def __eq__(self, other):
            if not isinstance(other, cls):
                return NotImplemented
            return self.__dict__ == other.__dict__

        def __repr__(self):
            items = ', '.join(f'{k}={v!r}' for k, v in self.__dict__.items())
            return f"{cls.__name__}({items})"

        cls.__hash__ = __hash__
        cls.__eq__ = __eq__
        cls.__repr__ = __repr__
        return cls
    return decorator


