import sys

def _make_dataclass(cls):
    """Create a dataclass-like class without using the @dataclass decorator."""
    cls.__slots__ = ()

    # Get field names and defaults from annotations/assignments
    fields = []
    for name, type_ in list(cls.__annotations__.items()):
        default = getattr(cls, name, '__no_default__')
        if hasattr(default, '_factory'):
            pass  # will handle later
        fields.append((name, type_, default))

    # Remove class-level attributes that were used as defaults
    for name, _, _ in fields:
        if name in cls.__dict__:
            delattr(cls, name)

    def __init__(self, *args, **kwargs):
        # Bind positional args to fields
        values = {}
        for i, (name, type_, default) in enumerate(fields):
            if i < len(args):
                values[name] = args[i]
            elif name in kwargs:
                values[name] = kwargs.pop(name)
            else:
                if default is not '__no_default__':
                    if hasattr(default, '_is_factory'):
                        values[name] = default()
                    else:
                        values[name] = default
                else:
                    raise TypeError(f"Missing required argument: {name}")
        if kwargs:
            raise TypeError(f"Unexpected keyword arguments: {list(kwargs.keys())}")
        self._fields_dict = values

    def __repr__(self):
        field_strs = [f"{name}={self._fields_dict[name]!r}" for name, _, _ in fields]
        return f"{cls.__name__}({', '.join(field_strs)})"

    def __eq__(self, other):
        if not isinstance(other, cls):
            return NotImplemented
        for name, _, _ in fields:
            if self._fields_dict[name] != other._fields_dict[name]:
                return False
        return True

    def __hash__(self):
        try:
            field_values = tuple(self._fields_dict[name] for name, _, _ in fields)
            return hash(field_values)
        except TypeError:
            raise TypeError(f"unhashable type: '{type(self._fields_dict.get(fields[0][0])).__name__}'")

    cls.__init__ = __init__
    cls.__repr__ = __repr__
    cls.__eq__ = __eq__
    cls.__hash__ = __hash__

    return cls


