def dataclass(cls=None, frozen=False, **kwargs):
    """A minimal decorator that mimics @dataclass with basic functionality."""
    def decorator(_cls):
        # Collect annotations and defaults
        annotations = getattr(_cls, '__annotations__', {})

        # Gather fields: name -> (is_field_marker, value)
        fields = []  # list of (name, is_field_marker, default_value_or_factory)

        for name in annotations:
            if hasattr(_cls, name):
                val = getattr(_cls, name)
                if isinstance(val, dict) and 'default_factory' in val and 'default' in val:
                    fields.append((name, True, val))
                else:
                    fields.append((name, False, val))
            else:
                fields.append((name, None, None))

        def __init__(self, *args, **kwargs_init):
            for i, (fname, _, _) in enumerate(fields):
                if i < len(args):
                    setattr(self, fname, args[i])
                elif fname in kwargs_init:
                    setattr(self, fname, kwargs_init[fname])
                else:
                    # Check for default from class
                    if hasattr(_cls, fname):
                        val = getattr(_cls, fname)
                        if isinstance(val, dict) and 'default_factory' in val:
                            setattr(self, fname, val['default_factory']())
                        else:
                            setattr(self, fname, val)
                    else:
                        raise TypeError(f"missing required argument: {fname!r}")

        def __repr__(self):
            parts = []
            for fname, _, _ in fields:
                parts.append(f"{fname}={getattr(self, fname)!r}")
            return f"{_cls.__name__}({', '.join(parts)})"

        if frozen:
            def __setattr__(self, name, value):
                raise AttributeError("can't set attribute")
            def __delattr__(self, name):
                raise AttributeError("can't delete attribute")

            # For frozen dataclasses with only hashable fields, allow hashing
            # We need to check if all field values are hashable
            def __hash__(self):
                items = []
                for fname, _, _ in fields:
                    val = getattr(self, fname)
                    items.append((fname, val))
                try:
                    return hash(tuple(items))
                except TypeError:
                    raise TypeError(f"unhashable type: cannot hash instance of '{_cls.__name__}' due to unhashable field(s)")
        else:
            def __eq__(self, other):
                if not isinstance(other, _cls):
                    return NotImplemented
                for fname, _, _ in fields:
                    if getattr(self, fname) != getattr(other, fname):
                        return False
                return True

            def __hash__(self):
                items = []
                for fname, _, _ in fields:
                    val = getattr(self, fname)
                    items.append((fname, val))
                try:
                    return hash(tuple(items))
                except TypeError:
                    raise TypeError(f"unhashable type: cannot hash instance of '{_cls.__name__}' due to unhashable field(s)")

        _cls.__init__ = __init__
        _cls.__repr__ = __repr__
        _cls.__setattr__ = __setattr__
        _cls.__delattr__ = __delattr__
        _cls.__eq__ = __eq__
        _cls.__hash__ = __hash__

        return _cls

    if cls is None:
        return decorator
    else:
        return decorator(cls)


