class Tokenizer:
    def __init__(self, source):
        self.source = source
        self.pos = 0
        self.tokens = []
        self._tokenize()

    def _tokenize(self):
        src = self.source
        i = 0
        n = len(src)
        while i < n:
            c = src[i]
            if c in ' \t\r\n':
                i += 1
            elif c == '#':
                # comment to end of line
                j = src.find('\n', i)
                if j == -1:
                    break
                i = j + 1
            elif c == '"' and src[i:i+3] == '"""':
                # triple-quoted string
                j = i + 3
                while j < n - 2 and src[j:j+3] != '"""':
                    j += 1
                if j >= n - 2:
                    # unterminated
                    self.tokens.append(('STRING', src[i:]))
                    i = n
                else:
                    self.tokens.append(('STRING', src[i:j+3]))
                    i = j + 3
            elif c == "'" and src[i:i+3] == "'''":
                # triple-quoted string
                j = i + 3
                while j < n - 2 and src[j:j+3] != "'''":
                    j += 1
                if j >= n - 2:
                    self.tokens.append(('STRING', src[i:]))
                    i = n
                else:
                    self.tokens.append(('STRING', src[i:j+3]))
                    i = j + 3
            elif c == '"':
                # regular double-quoted string
                j = i + 1
                while j < n and src[j] != '"' and src[j] != '\n':
                    if src[j] == '\\':
                        j += 1
                    j += 1
                if j < n and src[j] == '"':
                    self.tokens.append(('STRING', src[i:j+1]))
                    i = j + 1
                else:
                    self.tokens.append(('STRING', src[i:]))
