import unicodedata as u

def get_decomposition(cp):
    """Get decomposition mapping for a codepoint."""
    try:
        d = u.decomposition(chr(cp))
    except (ValueError, UnicodeEncodeError):
        return None
    return d

def compose(b, m):
    """Check if base b and mark m compose to some codepoint using NFC."""
    try:
        result = u.normalize('NFC', chr(b) + chr(m))
    except (ValueError, UnicodeEncodeError):
        return None
    if len(result) == 1:
        return ord(result[0])
    return None

