def b64decode_cp(s):
    """Reproduce base64.b64decode for the given test cases (strict, validate=True)."""
    if isinstance(s, str):
        s = s.encode('latin1')
    # remove whitespace
    cleaned = bytes(b for b in s if b not in (0x20, 0x09, 0x0a, 0x0d, 0x0b, 0x0c))
    length = len(cleaned)
    pad_count = 0
    i = length
    while i > 0 and cleaned[i-1] == 0x3d:  # '='
        pad_count += 1
        i -= 1
    if pad_count > 2:
        raise ValueError("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % (length - pad_count))
    if (length - pad_count) % 4 != 0:
        raise binascii.Error("Invalid base64-encoded string")
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    # build lookup
    trans = {}
    for idx, ch in enumerate(alphabet):
        trans[ord(ch)] = idx
    out = bytearray()
    acc = 0
    nbits = 0
    data_len = length - pad_count
    for byte in cleaned[:data_len]:
        if byte not in trans:
            raise binascii.Error("Invalid base64-encoded string")
        v = trans[byte]
        acc = (acc << 6) | v
        nbits += 6
        if nbits >= 8:
            nbits -= 8
            out.append((acc >> nbits) & 0xFF)
    # CPython's strict mode with validate=False actually raises on invalid chars? Let's check.
    # For the test cases given, we assume they're either valid or we need to match behavior.
    return bytes(out)

def urlsafe_b64decode_cp(s):
    if isinstance(s, str):
        s = s.encode('latin1')
    # translate -_ to +/
    translated = bytes(trans if trans not in (0x2d, 0x5f) else (0x2b if trans == 0x2d else 0x2f) for trans in s)
    return b64decode_cp(translated)

