def apply_spec(s, suffix, align, sign, alt, zero, width):
    # Remove existing sign characters from s if we're managing them
    content = s + suffix

    # Determine padding
    total_len = len(content)

    # Handle zero-padding only when no explicit space/padding is requested
    if zero and width and not alt:
        # Zero-padding
        needed = int(width) - total_len
        if needed > 0:
            # Add zeros after the sign
            if content.startswith(("-", "+", " ")):
                first_char = content[0]
                rest = content[1:]
                padded = first_char + "0" * needed + rest
            else:
                padded = "0" * needed + content
            return padded
    elif width:
        w = int(width)
        needed = w - total_len
        if needed > 0:
            if align == "<":
                return content + " " * needed
            elif align == ">":
                return " " * needed + content
            elif align == "^":
                left = needed // 2
                right = needed - left
                return " " * left + content + " " * right
            else:
                # Default: numbers are right-aligned
                return " " * needed + content
    else:
        return content


