        # Check if last char is a type indicator that's an int type
        for i, c in enumerate(spec):
            if c in 'dxXobc':
                # no 'n', so just use format
                return format(v, spec)
        # No type specified
        return format(v, spec)

    # We have 'n' at position t_pos
    # Replace 'n' with 'd' and apply thousands separator manually
    spec_no_n = spec[:t_pos] + 'd' + spec[t_pos+1:]
    r = format(v, spec_no_n)

    # Now apply thousands grouping (locale-dependent but we'll use comma as standard)
    # The 'n' type uses locale-aware formatting. Since we can't use locale module,
    # we need to replicate what Python does with the default locale.
    # In C locale (default), thousands separator is ',' and decimal point is '.'
    # For integers, there's no decimal part, so we just add commas.

    negative = r.startswith('-') or r.startswith('+')
    prefix = ''
    if negative:
