def emulate_n(value):
    """Emulate the 'n' format spec using locale.getlocale() and standard formatting."""
    try:
        import locale
        lang, enc = locale.getlocale(locale.LC_NUMERIC)
        if lang is None:
            raise ValueError("no locale")
        # Parse locale numeric settings
        # We need to get decimal point, thousands separator, and grouping
        # locale.localeconv() provides these
        conv = locale.localeconv()
        decimal_point = conv['decimal_point']
        thousands_sep = conv['thousands_sep']
        grouping = conv['grouping']  # list of ints or LC_NUMERIC_GROUPING

        # Format the number as a string first (without grouping)
        if isinstance(value, int):
            s = str(value)
        elif isinstance(value, float):
            # Use repr-style but we need decimal point replaced later
            # Actually for 'n', floats are formatted like general with up to 6 significant digits
            s = f"{value}"
            # But we need to handle it properly. Let's use format(v, '') which uses str
            s = str(value)

        # Now apply grouping and replace decimal point
        # Handle negative sign
        negative = s.startswith('-')
        if negative:
            s = s[1:]

        # Split into integer and fractional parts
        if '.' in s:
            int_part, frac_part = s.split('.', 1)
        else:
            int_part, frac_part = s, ''

        # Handle exponential notation
        if 'e' in int_part.lower():
            return s.replace('.', decimal_point)

        # Apply grouping to integer part
        # grouping is a list where each element is the number of digits in that group
        # last element repeated if needed
        def group_digits(s, groups):
            if not groups or groups == [0]:
                return s
            result = s
            pos = len(result)
            for i, g in enumerate(groups):
                if g == 0:  # repeat previous
                    break
                if g < 255:
                    chunk = g
                else:
                    chunk = None

                remaining = pos
                # Process from right to left
                new_s = ""
                while remaining > 0:
                    if chunk and chunk > 0 and chunk != 255:
                        take = min(chunk, remaining)
                    else:
                        take = remaining
                    new_s = result[pos - take:pos] + thousands_sep + new_s if new_s else result[pos - take:pos]
                    remaining -= take
                    pos = pos - take
                # Remove trailing sep
                if new_s.endswith(thousands_sep):
                    new_s = new_s[:-len(thousands_sep)]
                result = new_s
                if chunk == 255 or chunk is None:
                    break
            return result

        grouped_int = group_digits(int_part, grouping)

        # Rebuild
        out = ''
        if negative:
            out += '-'
        out += grouped_int
        if frac_part:
            out += decimal_point + frac_part

        return out

    except Exception:
        # Fallback to default behavior
        if isinstance(value, int):
            s = str(value)
        elif isinstance(value, bool):
            s = str(value)
        else:
            s = str(value)
        return s


