def get_git_files():
    """Get list of files similar to git ls-files (all files in the working tree)."""
    result = []
    for root, dirs, files in os.walk('.'):
        # Skip hidden directories and .git
        dirs[:] = [d for d in dirs if not d.startswith('.') and d != '.git']
        for f in files:
