def _open(path, mode='r', buffering=-1, encoding=None, errors=None, newline=None):
    """Attempt to open a file, raising FileNotFoundError if it doesn't exist."""
    # Use os.open to check existence
    import os as _os
    try:
        fd = _os.open(path, 0o0)  # O_RDONLY = 0 on most systems
        _os.close(fd)
    except OSError as e:
        raise FileNotFoundError(e.errno, e.strerror, path)

    # If we get here, the file exists and opened successfully
    return open(path, mode, buffering=buffering, encoding=encoding, errors=errors, newline=newline)

