                            elif s[pos] == '}':
                                pos += 1
                                break
                            else:
                                raise ValueError("expected , or }")
                        return obj

                    def parse_array():
                        nonlocal pos
                        pos += 1  # skip [
                        arr = []
                        skip_ws()
                        if pos < length and s[pos] == ']':
                            pos += 1
                            return arr
                        while True:
                            val = parse_value()
                            arr.append(val)
                            skip_ws()
                            if pos >= length:
                                break
                            if s[pos] == ',':
                                pos += 1
                            elif s[pos] == ']':
                                pos += 1
                                break
                            else:
                                raise ValueError("expected , or ]")
                        return arr

                    def parse_string():
                        nonlocal pos
                        assert s[pos] == '"'
                        pos += 1
                        res = []
                        while pos < length:
                            c = s[pos]
                            if c == '\\':
                                pos += 1
                                esc = s[pos]
                                if esc == '"':
                                    res.append('"')
                                elif esc == '\\':
                                    res.append('\\')
                                elif esc == '/':
                                    res.append('/')
                                elif esc == 'b':
                                    res.append('\b')
                                elif esc == 'f':
                                    res.append('\f')
                                elif esc == 'n':
                                    res.append('\n')
                                elif esc == 'r':
                                    res.append('\r')
                                elif esc == 't':
                                    res.append('\t')
                                elif esc == 'u':
