                                    hx = s[pos+1:pos+5]
                                    code = int(hx, 16)
                                    res.append(chr(code))
                                    pos += 4
                                else:
                                    raise ValueError("bad escape")
                                pos += 1
                            elif c == '"':
                                pos += 1
                                return ''.join(res)
                            else:
                                res.append(c)
                                pos += 1
                        raise ValueError("unterminated string")

                    def parse_number():
                        nonlocal pos
                        start = pos
                        if pos < length and s[pos] == '-':
                            pos += 1
                        while pos < length and s[pos].isdigit():
                            pos += 1
                        if pos < length and s[pos] == '.':
