                        return int(num_str)

                    return parse_value()

                def dump_json(obj, indent=None, cur_indent=0):
                    sp = ' ' * indent if indent is not None else ''
                    pad = ' ' * (cur_indent + indent) if indent is not None else ''
                    pad_outer = ' ' * cur_indent if indent is not None else ''

                    if obj is None:
                        return 'null'
                    elif isinstance(obj, bool):
                        return 'true' if obj else 'false'
                    elif isinstance(obj, int):
                        return str(obj)
                    elif isinstance(obj, float):
                        return repr(obj)
                    elif isinstance(obj, str):
                        return json_quote(obj)
                    elif isinstance(obj, list):
                        if not obj:
                            return '[]'
                        items = []
                        for item in obj:
                            items.append(pad + dump_json(item, indent, cur_indent + indent) if indent else '')
                        if indent:
                            inner = ',\n'.join(pad + dump_json(i, indent, cur_indent + indent) for i in obj)
                            return '[\n' + inner + '\n' + pad_outer + ']'
                        else:
                            return '[' + ','.join(dump_json(i, None, 0) for i in obj) + ']'
                    elif isinstance(obj, dict):
                        if not obj:
                            return '{}'
                        if indent:
                            items = []
                            for k, v in obj.items():
                                items.append(pad + json_quote(str(k)) + ': ' + dump_json(v, indent, cur_indent + indent))
                            return '{\n' + ',\n'.join(items) + '\n' + pad_outer + '}'
                        else:
