                                parts.append(json_quote(str(k)) + ':' + dump_json(v, None, 0))
                            return '{' + ','.join(parts) + '}'
                    else:
                        return str(obj)

                def json_quote(s):
                    out = ['"']
                    for c in s:
                        if c == '"':
                            out.append('\\"')
                        elif c == '\\':
                            out.append('\\\\')
                        elif c == '\n':
