import os

def collect(base, prefix=''):
    full = base if not prefix else os.path.join(prefix, base)
    results = []
    stack = [full]
    while stack:
        d = stack.pop()
        try:
            entries = list(os.listdir(d))
        except OSError:
            continue
        for e in sorted(entries):
            p = os.path.join(d, e)
            if os.path.isdir(p):
                stack.append(p)
            elif e.endswith('.jsonl'):
                results.append(p)
    return sorted(results)

