def _loads(s):
    s2 = s.strip()
    try:
        from json import loads as _jl
        return _jl(s2)
    except Exception:
        pass
    # Minimal fallback JSON parser (rarely used)
    return _mini_json(s2)

def _mini_json(s):
    # Simple recursive descent parser
    pos = [0]
    def ws():
        while pos[0] < len(s) and s[pos[0]] in ' \t\n\r':
            pos[0] += 1
    def val():
        ws()
        c = s[pos[0]]
        if c == '{':
            return obj()
        if c == '[':
            return arr()
        if c == '"':
            return string()
        if c == 't' and s[pos[0]:pos[0]+4] == 'true':
            pos[0] += 4; return True
        if c == 'f' and s[pos[0]:pos[0]+5] == 'false':
            pos[0] += 5; return False
        if c == 'n' and s[pos[0]:pos[0]+4] == 'null':
            pos[0] += 4; return None
        return number()
    def obj():
        pos[0] += 1; ws()
        r = {}
        if s[pos[0]] == '}':
            pos[0] += 1; return r
        while True:
            ws(); k = string(); ws()
            assert s[pos[0]] == ':'
            pos[0] += 1
            v = val()
            r[k] = v
            ws()
            if s[pos[0]] == ',':
                pos[0] += 1
            else:
                break
        pos[0] += 1
        return r
    def arr():
        pos[0] += 1; ws()
        r = []
        if s[pos[0]] == ']':
            pos[0] += 1; return r
        while True:
            r.append(val())
            ws()
            if s[pos[0]] == ',':
                pos[0] += 1
            else:
                break
        pos[0] += 1
        return r
    def string():
        assert s[pos[0]] == '"'
        pos[0] += 1
        out = []
        while s[pos[0]] != '"':
            c = s[pos[0]]
            if c == '\\':
                pos[0] += 1
                nc = s[pos[0]]
                if nc == 'n': out.append('\n')
                elif nc == 't': out.append('\t')
                elif nc == 'r': out.append('\r')
                elif nc == 'b': out.append('\b')
                elif nc == 'f': out.append('\f')
                elif nc == '/': out.append('/')
                elif nc == '"': out.append('"')
                elif nc == '\\': out.append('\\')
                elif nc == 'u':
                    hx = s[pos[0]+1:pos[0]+5]
                    out.append(chr(int(hx,16)))
                    pos[0] += 4
                pos[0] += 1
            else:
                out.append(c)
                pos[0] += 1
        pos[0] += 1
        return ''.join(out)
    def number():
        start = pos[0]
        while pos[0] < len(s) and s[pos[0]] in '-+0123456789.eE':
            pos[0] += 1
        txt = s[start:pos[0]]
        try:
            return int(txt)
        except ValueError:
            return float(txt)
    return val()

def _dumps(obj, indent=1):
    # Minimal JSON dumps matching Python's json.dumps with indent=1
    lines = []
    def rec(o, ind):
        pad = ' ' * ind
        if isinstance(o, dict):
            if not o:
                return '{}'
            items = []
            for k, v in o.items():
                key_str = _json_str(k)
                val_str = rec(v, ind + indent)
                items.append(pad + key_str + ': ' + val_str.replace('\n', '\n' + ' ' * ind).replace('\n', '\n' + pad))
            # Rebuild properly
            inner = []
            for k, v in o.items():
                key_str = _json_str(k)
                if isinstance(v, (dict, list)) and v:
                    inner.append(pad + key_str + ': ' + rec(v, ind + indent).strip())
                else:
                    inner.append(pad + key_str + ': ' + rec(v, ind))
            res = '{\n' + ',\n'.join(inner) + '\n' + (' ' * max(0, ind - indent)) + '}'
            return res
        elif isinstance(o, list):
            if not o:
                return '[]'
            inner = []
            for v in o:
                if isinstance(v, (dict, list)) and v:
                    inner.append(pad + rec(v, ind + indent).strip())
                else:
                    inner.append(pad + rec(v, ind))
            res = '[\n' + ',\n'.join(inner) + '\n' + (' ' * max(0, ind - indent)) + ']'
            return res
        else:
            return _json_scalar(o)
    def _json_scalar(o):
        if o is None:
            return 'null'
        if o is True:
            return 'true'
        if o is False:
            return 'false'
        if isinstance(o, str):
            return _json_str(o)
        if isinstance(o, int):
            return str(o)
        if isinstance(o, float):
            return repr(o)
        return _json_str(str(o))
    def _json_str(s):
        out = ['"']
        for c in s:
            if c == '"':
                out.append('\\"')
            elif c == '\\':
                out.append('\\\\')
            elif c == '\n':
                out.append('\\n')
            elif c == '\t':
                out.append('\\t')
            elif c == '\r':
                out.append('\\r')
            elif c == '\b':
                out.append('\\b')
            elif c == '\f':
                out.append('\\f')
            elif ord(c) < 0x20:
                out.append('\\u%04x' % ord(c))
            else:
                out.append(c)
        out.append('"')
        return ''.join(out)
    return rec(obj, 0)

