def safe_repr(s):
    """Compute repr(s) without calling the built-in repr() on the string."""
    out = []
    for ch in s:
        cp = ord(ch)
        if ch == '\\':
            out.append('\\\\')
        elif ch == '"':
            out.append('\\"')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\t':
            out.append('\\t')
        else:
            # Determine whether the character is printable using Python's default rules.
            # A non-ASCII character >= 0x20 and not a C1 control char (0x7F-0x9F range that is
            # considered unprintable by Python) is printable, except category Cc/Zl/Zp which are
            # also unprintable.
            cat = unicodedata_category(cp)
            if cp < 0x20 or cp == 0x7f or cat in ('Cc', 'Cf', 'Zl', 'Zp'):
                out.append('\\u{:04x}'.format(cp))
            else:
                out.append(ch)
    return '"' + ''.join(out) + '"'


def unicodedata_category(cp):
    """Return a minimal category code sufficient to detect Cc/Cf/Zl/Zp characters."""
    if cp == 0:
        return 'Cc'
    if 0x1 <= cp <= 0x1F:
        return 'Cc'
    if cp == 0x7F:
        return 'Cc'
    if 0x80 <= cp <= 0x9F:
        return 'Cc'
    if 0x200E <= cp <= 0x200F:
        return 'Cf'
    if 0x202A <= cp <= 0x202E:
        return 'Cf'
    if 0x2060 <= cp <= 0x206F:
        return 'Cf'
    if 0xFEFF <= cp <= 0xFFFF:
        # Many Cf characters in this range; we only need to check specific ones
        if cp in (0xFEFF, 0xFFFE, 0xFFFF):
            return 'Cf'
        return 'L'  # placeholder; these are actually L* but not Cf
    if cp == 0x2028:
        return 'Zl'
    if cp == 0x2029:
        return 'Zp'
    # For all other ranges, return something that is NOT in {'Cc','Cf','Zl','Zp'}
    return 'L'


