def maxargs(call, upto=6):
    ok=[]
    for n in range(0, upto+1):
        try:
            call(n); ok.append(n)
        except TypeError as e:
            m=str(e)
            if any(w in m for w in ("argument","arguments","positional")): pass
            else: ok.append(n)
        except Exception: ok.append(n)
    return (min(ok) if ok else None, max(ok) if ok else None)

