import os, sys

def _mkstemp(suffix="", prefix="tmp", dir=None):
    import random, string
    ntries = 0
    while True:
        try:
            name_chars = [random.choice(string.ascii_letters + string.digits) for _ in range(8)]
            fname = prefix + "_".join(name_chars) + suffix
            if dir is None:
                path = os.path.join('/tmp', fname)
            else:
                path = os.path.join(dir, fname)
            fd = os.open(path, os.O_RDWR | os.O_CREAT | os.O_EXCL, 0o600)
            return fd, path
        except OSError:
            ntries += 1
            if ntries > 50:
                raise

