def _parse_optional(self, string):
    if not (string[0] in self.prefix_chars and len(string) > 1):
        return None
    option_string = string
    explicit_arg = None
    components = string.split('=', 1)
    if len(components) > 1:
        option_string, explicit_arg = components
    if self._has_negative_number_optionals:
        if option_string in self._negative_number_matcher.match(option_string).groupdict():
            return None
    if option_string in self._option_string_actions:
        action = self._option_string_actions[option_string]
        arg_strings = []
        if explicit_arg is not None:
            arg_strings.append(explicit_arg)
        return action, option_string, arg_strings
    else:
        # ignore long options with additional characters
        for prefix in list(self._long_opt_map.keys()):
            if string.startswith(prefix):
                if prefix in self._option_string_actions:
                    action = self._option_string_actions[prefix]
                    arg_strings = []
                    if explicit_arg is not None:
                        arg_strings.append(explicit_arg)
                    return action, prefix, arg_strings
        # search through all possible prefixes to match short
        # options and their optional argument
        for c in self.prefix_chars:
            if option_string[1:] in self._short_opt_map:
                action = self._short_opt_map[option_string[1:]]
                stop = 2
                option_string += c
                explicit_arg = string[stop:]
                break
        if not explicit_arg:
            exp_arg_count = self._get_nargs_pattern(action)
            if exp_arg_count == _COUNT:
                raise ArgumentError(action, _('ignored explicit argument %r') % explicit_arg)
            return action, option_string, []
        else:
            return action, option_string, [explicit_arg]

def _get_option_tuples(self, option_string):
    result = []
    pos = self.prefix_chars.find(option_string[0])
    for prefix in self.prefix_chars[pos:]:
        for option_string in self._option_string_actions:
            if option_string.startswith(prefix):
                result.append((option_string, prefix))
    return result

def _match_arguments_partial(self, actions, arg_strings):
    start_index = 0
    selected_actions = []
    for i in range(len(arg_strings)):
        action = actions[i + start_index]
        nargs_pattern = self._get_nargs_pattern(action)
        match_argument = self._match_arguments(nargs_pattern, arg_strings[start_index:], i)
        if match_argument is not None:
            start_index = i + 1
            selected_actions.append(action)
            remaining_args = arg_strings[start_index:]
            if match_argument < len(remaining_args):
                break
            else:
                return selected_actions, arg_strings[:i], arg_strings[i:]
    return selected_actions, [], arg_strings[start_index:]

