        self._conflict_handler = conflict_handler
        self._version_strings = {}

        # parsers referenced by this parser
        self._mutually_exclusive_groups = []

        # parse the defaults
        self._defaults = []

        # add help argument
        if self.add_help:
            self.add_argument('-h', '--help',
                              action='help',
                              default=Suppress(),
                              nargs=0,
                              help=_('show this help message and exit'))

        # add parent arguments and defaults
        for parent in self._parents:
            self._add_parent_actions(parent)

    def _add_parent_actions(self, parent):
        # add actions
        for action in parent._actions:
            self.add_argument(*action._names, **action._kwargs)

    @property
    def actions(self):
        return self._actions

    def add_argument(self, *args, **kwargs):
        if self._subparsers is not None and args[0][:1] == '-':
            raise ValueError('subparsers cannot have required optionals')
        return self._add_action(args, kwargs)

    def _add_action(self, action):
