        self._check_conflict(action)

        # add to actions list
        self._actions.append(action)
        action.container = self

        # map the action's name(s) to this action
        for option_string in action.option_strings:
            self._option_string_actions[option_string] = action

        return action

    def add_subparsers(self, **kwargs):
        # add the parser to the subparsers' actions
        subparsers_action = _SubParsersAction(
            parser=self,
            dest=kwargs.pop('dest', None),
            title=kwargs.pop('title', _('subcommands')),
            description=kwargs.pop('description', None),
            metavar=kwargs.pop('metavar', None),
            command_names=kwargs.pop('command_names', None))

        self._add_action(subparsers_action)
        self._subparsers = subparsers_action

        # create the parsers
        return subparsers_action

