        for action in self._actions:
            if action.dest is not SUPPRESS:
                if not hasattr(namespace, action.dest):
                    if action.default is not SUPPRESS:
                        setattr(namespace, action.dest, action.default)

        # parse the arguments and exit if there are any errors
        if self.exit_on_error:
            try:
                argv, extras = self._parse_known_args(args, namespace)
            except ArgumentError as err:
                self.error(str(err))
        else:
            argv, extras = self._parse_known_args(args, namespace)

        if hasattr(namespace, _UNRECOGNIZED_ARGS_ATTR):
            extras.extend(getattr(namespace, _UNRECOGNIZED_ARGS_ATTR))
            delattr(namespace, _UNRECOGNIZED_ARGS_ATTR)

        return namespace, extras

    def parse_args(self, args=None, namespace=None):
        args, argv = self.parse_known_args(args, namespace)
        if argv:
            msg = _('unrecognized arguments: %s')
            self.error(msg % ' '.join(argv))
        return args

    def format_usage(self):
        formatter = self._get_formatter()
        formatter.add_usage(self.usage, self._actions, self._mutually_exclusive_groups)
        return formatter.format_help()

    def format_help(self):
        formatter = self._get_formatter()
        formatter.add_usage(self.usage, self._actions, self._mutually_exclusive_groups)
        formatter.add_text(self.description)

        # add sub-commands
        if self._subparsers is not None:
            subparsers_action = self._subparsers
            formatter.start_section(subparsers_action.title)
            formatter.add_text(subparsers_action.description)
            subparsers_formatter = self._get_formatter()
            for action in subparsers_action._choices_actions:
                subparsers_formatter.start_section(action.name)
                subparser = self._subparsers._name_parser_map[action.name]
                subparsers_formatter.add_text(subparser.description)
                subparsers_formatter.end_section()
            formatter.end_section()

        # add options
        for group in self._action_groups:
            formatter.start_section(group.title)
            formatter.add_text(group.description)
            formatter.add_arguments(group._group_actions)
            formatter.end_section()

        # add epilog
        if self._epilog:
            formatter.add_text(self._epilog)

        return formatter.format_help()

    def _get_formatter(self):
        return self.formatter_class(prog=self.prog)

    def _parse_known_args(self, args, namespace):
        # replace args with first non-dash arg
        extras = []

        # determine which option strings should be considered negative numbers
