def extract_method_source(code, class_name, method_name):
    """Extract the source of a method from code string"""
    lines = code.split('\n')

    # Find the class
    in_class = False
    class_indent = 0
    class_start = None

    for i, line in enumerate(lines):
        stripped = line.strip()
        if stripped == 'class ' + class_name + ':':
            in_class = True
            class_indent = len(line) - len(line.lstrip())
            class_start = i
            break
        elif stripped.startswith('class ') and in_class:
            in_class = False

    if not in_class or class_start is None:
        return ''

    # Find the method within the class
    in_method = False
    method_indent = 0
    method_start = None

    for i in range(class_start + 1, len(lines)):
        line = lines[i]
        stripped = line.strip()

        if not in_method:
            # Check if this is a def at the class level
            if stripped.startswith('def ' + method_name + '(') or stripped.startswith('async def ' + method_name + '('):
                indent = len(line) - len(line.lstrip())
                # Make sure it's indented more than class (i.e., it's a method)
                if indent > class_indent:
                    in_method = True
                    method_indent = indent
                    method_start = i
                    break
        else:
            if stripped and not stripped.startswith('#'):
                indent = len(line) - len(line.lstrip())
                if indent <= method_indent and stripped.startswith('def '):
                    # End of method
                    break
                if indent < method_indent:
                    # End of method
                    break

    if method_start is None:
        return ''

    # Collect the method lines
    result_lines = []
    in_method = False
    method_indent = None

    for i in range(method_start, len(lines)):
        line = lines[i]

        if not in_method:
            result_lines.append(line)
            in_method = True
            method_indent = len(line) - len(line.lstrip())
            continue

        if line.strip():
            indent = len(line) - len(line.lstrip())
            if indent < method_indent:
                break
            if indent == method_indent and line.strip().startswith('def '):
                break

        result_lines.append(line)

    # Remove trailing empty lines
    while result_lines and result_lines[-1].strip() == '':
        result_lines.pop()

    return '\n'.join(result_lines)


def extract_function_source(code, func_name):
    """Extract the source of a top-level function"""
    lines = code.split('\n')

    for i, line in enumerate(lines):
        stripped = line.strip()
        if stripped.startswith('def ' + func_name + '(') or stripped.startswith('async def ' + func_name + '('):
            indent = len(line) - len(line.lstrip())
            if indent == 0:
                # Found it
                result_lines = [line]

                for j in range(i + 1, len(lines)):
                    next_line = lines[j]
                    if next_line.strip():
