def get_negative_number_matcher_pattern(code):
    """Extract the pattern from _negative_number_matcher definition"""
    lines = code.split('\n')
    for i, line in enumerate(lines):
        if '_negative_number_matcher' in line and 're.compile' in line:
            # Extract the string
