def classify(cpy_res, lyp_res, target_engine, prog_ns):
    c_out = cpy_res.stdout
    l_out = lyp_res.stdout

    if cpy_res.returncode != 0 or lyp_res.returncode != 0:
        # Both should be 0 per the test cases, but handle gracefully
        pass

    # Compare outputs as floats with some tolerance
    try:
        c_val = float(c_out.strip())
        l_val = float(l_out.strip())
    except (ValueError, AttributeError):
        c_val = None
        l_val = None

    if c_val is not None and l_val is not None:
        diff = abs(c_val - l_val)
        rel_diff = diff / max(abs(c_val), abs(l_val)) if max(abs(c_val), abs(l_val)) != 0 else diff
        if diff < 1e-9 or rel_diff < 1e-6:
            verdict = "pass"
            detail = "outputs match within tolerance"
        else:
            verdict = "fail"
            detail = "outputs differ: expected %r, got %r" % (c_val, l_val)
    else:
        if c_out == l_out:
            verdict = "pass"
            detail = "outputs match exactly"
        else:
            verdict = "fail"
            detail = "outputs differ: expected %r, got %r" % (c_out, l_out)

    class Verdict:
        def __init__(self, verdict_, detail_):
            self.verdict = verdict_
            self.detail = detail_

    return Verdict(verdict, detail)


