import random

class _Engines:
    @staticmethod
    def chain_after_refusal(a, b):
        return f"chain[{a}->{b}]"
    @staticmethod
    def Result(name, stdout, rc, out, err, elapsed):
        r = {"name": name, "stdout": stdout, "rc": rc, "out": out, "err": err, "elapsed": elapsed}
        return r

class _Conformance:
    @staticmethod
    def is_seeded_stream(entry):
        if isinstance(entry, dict):
            p = entry.get("program", "")
        else:
            p = getattr(entry, "program", "")
        return "random.seed" in p

    @staticmethod
    def is_run_specific(entry):
        if isinstance(entry, dict):
            tags = entry.get("tags", ())
        else:
            tags = getattr(entry, "tags", ())
        return "run-specific" in tags or "runtime-nondeterministic" in tags

    @staticmethod
    def classify(ref, arm, arm_name, entry):
        ref_out = ref["stdout"]
        arm_out = arm["stdout"]
        if ref_out == arm_out:
            return "match"
        if _Conformance.is_seeded_stream(entry) and not _Conformance.is_run_specific(entry):
            return "seed-divergence(accepted)"
        return "mismatch"

