    for k in range(n):
        d[k] = k * 2
    for k in range(0, n, 2):
        del d[k]
    for k in range(0, n, 2):
        d[k] = k * 3
    ks = list(d)
    print('C1', n, len(d), ks[:5], ks[-5:], sum(d.values()))
    p = []
    for _ in range(min(5, len(d))):
        p.append(d.popitem())
    print('C2', n, p, len(d))

# --- collision-forcing integer keys ---
for step in [8, 16, 32, 64, 1024]:
    d = {}
    for i in range(20):
        d[i * step] = i
    print('C3', step, len(d), list(d)[:6], sum(d.values()))
    for i in range(0, 20, 3):
        del d[i * step]
    print('C4', step, len(d), list(d)[:6])
    s = set(i * step for i in range(20))
    for i in range(0, 20, 3):
        s.discard(i * step)
    print('C5', step, len(s), sorted(s)[:6])

