import json, re, subprocess

files = subprocess.run(
    ["find", ".", "-name", "corpus.jsonl", "-o", "-name", "seed-corpus.jsonl"],
    capture_output=True, text=True
).stdout.split()
n = 0
hits = 0
for f in files:
    for line in open(f):
        try:
            e = json.loads(line)
        except Exception:
            continue
        src = json.dumps(e)
        if re.search(r"import\\?\s+random|from\s+random", src):
            n += 1
            if "sum(" in src and "seed(" in src:
                hits += 1
                print(f, repr(src[:200]))
print("files:", files, "entries importing random:", n, "seeded+sum:", hits)

