def cp(b):
    r = []
    for x in b:
        r.append(x)
    return r

bases = [[], [1], [1, 2, 3], [1, 1, 2, 1], [5, 4, 3, 2, 1], [0, 0, 0], [7, 8]]
idxs = [-1000, -6, -4, -3, -2, -1, 0, 1, 2, 3, 5, 1000]
ops = ["insert", "pop", "index", "index_s", "index_se", "index_neg", "remove", "del", "count", "getitem", "setitem", "delslice"]
n = 0
for bi in range(len(bases)):
    for ii in range(len(idxs)):
        for oi in range(len(ops)):
            op = ops[oi]
            i = idxs[ii]
            L = cp(bases[bi])
            tag = str(bi) + "/" + str(i) + "/" + op
            out = "?"
            try:
                if op == "insert":
                    L.insert(i, 99)
                    out = repr(L)
                elif op == "pop":
                    v = L.pop(i)
                    out = repr(v) + " " + repr(L)
                elif op == "index":
                    out = repr(L.index(1))
                elif op == "index_s":
                    out = repr(L.index(1, i))
                elif op == "index_se":
                    out = repr(L.index(1, i, i + 2))
                elif op == "index_neg":
                    out = repr(L.index(1, 0, i))
                elif op == "remove":
                    L.remove(i)
                    out = repr(L)
                elif op == "del":
                    # Emulate del L[i] using list slicing with a single-element slice
                    L[i:i+1] = []
                    out = repr(L)
                elif op == "count":
                    out = repr(L.count(i))
                elif op == "getitem":
                    out = repr(L[i])
                elif op == "setitem":
                    L[i] = 42
                    out = repr(L)
                elif op == "delslice":
                    del L[i:i+2]
                    out = repr(L)
            except IndexError as e:
                out = "E IndexError: " + str(e)
            except ValueError as e:
                out = "E ValueError: " + str(e)
            except TypeError as e:
                out = "E TypeError: " + str(e)
            except OverflowError as e:
                out = "E OverflowError: " + str(e)
            n = n + 1
            print(tag + " => " + out)
print("TOTAL " + str(n))

