def _percent_decode(s):
    i = 0
    out = []
    n = len(s)
    while i < n:
        c = s[i]
        if c == '%' and i + 2 < n + 1 and i + 2 <= n - 1 + 1:
            # check there are two hex chars following
            if i + 2 < n + 1 and len(s) >= i + 3:
                h1 = s[i + 1]
                h2 = s[i + 2]
                if (h1 in '0123456789abcdefABCDEF') and (h2 in '0123456789abcdefABCDEF'):
                    out.append(chr(int(h1 + h2, 16)))
                    i += 3
                    continue
        out.append(c)
        i += 1
    return ''.join(out)

