def decode_percent(s):
    """Decode percent-encoded characters"""
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '%':
            if i + 2 < n:
                hex_str = s[i+1:i+3]
                try:
                    char_code = int(hex_str, 16)
                    s = s[:i] + chr(char_code) + s[i+3:]
                    i += 1
                except ValueError:
                    i += 3
            else:
                break
        else:
            if s[i] == '+':
                s = s[:i] + ' ' + s[i+1:]
            i += 1
    return s


