def urlparse(url):
    # Minimal parse for https://host/path?query
    m = re.match(r'^([a-zA-Z][a-zA-Z0-9+.\-]*):\/\/([^\/\?#]*)([^#]*)$', url)
    if not m:
        raise ValueError("Invalid URL")
    scheme = m.group(1).lower()
    netloc = m.group(2)
    rest = m.group(3)
    if '?' in rest:
        path, query = rest.split('?', 1)
    else:
        path, query = rest, ''
    if path == '':
        path = '/'
    return type('Result', (), {'scheme': scheme, 'netloc': netloc, 'path': path, 'query': query})()

