import os, sys, time

def _max_rss_kb():
    try:
        with open('/proc/self/status', 'r') as f:
            for line in f:
                if line.startswith('VmPeak:'):
                    val = line.split()[1]
                    return int(val)
    except Exception:
        pass
    try:
        import resource
        return resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss
    except Exception:
        pass
    return 0

def run(bin, prog):
    t0 = time.perf_counter()
    pid = os.fork()
    if pid == 0:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, 1)
        os.execv(bin, [bin, "-c", prog])
        os._exit(127)
    _, status, _ = os.wait4(pid, 0)
    rss_kb = _max_rss_kb()
    elapsed_ms = (time.perf_counter() - t0) * 1000
    return rss_kb, elapsed_ms, status

