    if not s1.startswith('{') or not s1.endswith('}'):
        return False
    if not s2.startswith('{') or not s2.endswith('}'):
        return False

    inner1 = s1[1:-1]
    inner2 = s2[1:-1]

    # Try to parse as a set (no colons) or dict (colons)
    # Split on top-level commas and compare elements as sets

    def split_top_level(s):
        elements = []
        depth = 0
        current = ''
        for c in s:
            if c == '{' or c == '[' or c == '(':
                depth += 1
                current += c
            elif c == '}' or c == ']' or c == ')':
                depth -= 1
                current += c
            elif c == ',' and depth == 0:
                elements.append(current.strip())
                current = ''
            else:
                current += c
        if current.strip():
            elements.append(current.strip())
        return elements

    elems1 = split_top_level(inner1)
    elems2 = split_top_level(inner2)

    if len(elems1) != len(elems2):
        return False

    if len(elems1) == 0:
        return True

    # Check if they have the same elements as a set (order doesn't matter)
    if set(elems1) == set(elems2):
        return True

    return False


