    """Check if two strings contain the same elements but in a different order."""
    # Remove whitespace and normalize
    s1 = text1.strip()
    s2 = text2.strip()

    # For sets like {1, 2, 3} vs {3, 1, 2}
    # Check if they are both set-like (start with { and end with })
    if s1.startswith('{') and s1.endswith('}') and s2.startswith('{') and s2.endswith('}'):
        # Extract contents
        content1 = s1[1:-1].strip()
        content2 = s2[1:-1].strip()

        # Try to parse as set of numbers
        try:
            elements1 = [x.strip() for x in content1.split(',')]
            elements2 = [x.strip() for x in content2.split(',')]

            # Check if they have the same elements (as sets) but different order
            if len(elements1) == len(elements2):
                # Convert to canonical form for comparison
                try:
                    nums1 = sorted(int(x) for x in elements1)
                    nums2 = sorted(int(x) for x in elements2)
                    if nums1 == nums2:
                        return elements1 != elements2
                except ValueError:
                    # Not integers, compare as strings
                    if sorted(elements1) == sorted(elements2):
                        return elements1 != elements2
                    else:
                        return False

            return False

        # If it's a dict-like structure
        elif ':' in content1 or ':' in content2:
            # It's a dictionary - check if key-value pairs are the same but in different order
            try:
                # Parse dict entries
                def parse_dict_content(content):
                    # Handle cases like {'a': 1, 'b': 2}
                    content = content.strip()
                    if not content:
                        return []

                    # Split by commas carefully (handle nested structures simply)
                    entries = []
                    current = ''
                    depth = 0
                    for char in content:
                        if char in '{[':
                            depth += 1
                            current += char
                        elif char in '}]':
                            depth -= 1
                            current += char
                        elif char == ',' and depth == 0:
                            entries.append(current.strip())
                            current = ''
                        else:
                            current += char
                    if current.strip():
                        entries.append(current.strip())

                    return entries

                entries1 = parse_dict_content(content1)
                entries2 = parse_dict_content(content2)

                if len(entries1) == len(entries2):
                    if sorted(entries1) == sorted(entries2):
                        return entries1 != entries2
                    else:
                        return False

            return False

    # Fallback: check if they're the same when reordered
    # This is a general case
    words1 = s1.split()
    words2 = s2.split()

    if sorted(words1) == sorted(words2):
        return words1 != words2
    return False


