import re


def only_set_order_differs(s1: str, s2: str) -> bool:
    """
    Compare two strings that represent Python sets or dicts, returning True if they differ only in ordering.

    For sets: compares the set of elements.
    For dicts: compares keys and values independently (order-independent).
    """
    # Try to parse as a set first
    def try_parse_set(s):
        s = s.strip()
        if not s.startswith('{') or not s.endswith('}'):
            return None
        inner = s[1:-1].strip()
        if not inner:
            return frozenset()
        # Split by commas, but need to handle nested structures carefully
        # For simple cases like {1, 2, 3} or {'a', 'b'}
        items = []
        depth = 0
        current = ''
        for ch in inner:
            if ch == ',' and depth == 0:
                items.append(current.strip())
                current = ''
            else:
                if ch in '([{':
                    depth += 1
                elif ch in ')]}':
                    depth -= 1
                current += ch
        if current.strip():
            items.append(current.strip())

        # Parse each item
        elements = []
        for item in items:
            # Try to eval it safely - since we're dealing with string literals, numbers, etc.
            try:
                val = eval(item, {"__builtins__": {}}, {})
                elements.append(val)
            except Exception:
                # If eval fails, keep as string
                elements.append(item)

        # Check for duplicates - if there are duplicates, it's not really a valid set representation
        if len(elements) != len(set(str(e) for e in elements)):
            return None

        return frozenset(str(e) for e in elements)

    def try_parse_dict(s):
        s = s.strip()
        if not s.startswith('{') or not s.endswith('}'):
            return None
        inner = s[1:-1].strip()
        if not inner:
            return {}

        # Split into key-value pairs by top-level commas
        pairs = []
        depth = 0
        current = ''
        for ch in inner:
            if ch == ',' and depth == 0:
                pairs.append(current.strip())
                current = ''
            else:
                if ch in '([{':
                    depth += 1
                elif ch in ')]}':
                    depth -= 1
                current += ch
        if current.strip():
            pairs.append(current.strip())

        d = {}
        for pair in pairs:
            if ':' not in pair:
                return None
            idx = pair.index(':')
            key_str = pair[:idx].strip()
            val_str = pair[idx+1:].strip()

            try:
                key = eval(key_str, {"__builtins__": {}}, {})
                val = eval(val_str, {"__builtins__": {}}, {})
            except Exception:
                key = key_str
                val = val_str

            d[key] = val

        return d

    # First check if both can be parsed as sets
    s1_set = try_parse_set(s1)
    s2_set = try_parse_set(s2)

    if s1_set is not None and s2_set is not None:
        return s1_set == s2_set

    # Check if both can be parsed as dicts
    s1_dict = try_parse_dict(s1)
    s2_dict = try_parse_dict(s2)

    if s1_dict is not None and s2_dict is not None:
        # Compare dictionaries ignoring order
        if set(k for k in s1_dict.keys()) != set(k for k in s2_dict.keys()):
            return False
        for k in s1_dict:
            if s1_dict[k] != s2_dict.get(k):
                return False
        return True

    # Fallback: treat as generic string comparison after normalizing
    # Just compare the raw strings
    return s1.strip() == s2.strip()


