def only_set_order_differs(s1, s2):
    """Check if two strings differ only in the order of elements within braces."""
    # Extract content between outermost braces
    def extract_braces(s):
        # Find the first opening brace and its matching closing brace
        start = s.index('{')
        depth = 0
        for i in range(start, len(s)):
            if s[i] == '{':
                depth += 1
            elif s[i] == '}':
                depth -= 1
                if depth == 0:
                    return s[start+1:i], s[:start], s[i+1:]
        raise ValueError("Unmatched braces")

    inner1, prefix1, suffix1 = extract_braces(s1)
    inner2, prefix2, suffix2 = extract_braces(s2)

    # Check that everything outside braces is the same
    if prefix1 != prefix2 or suffix1 != suffix2:
        return False

    # Split by commas at top level (not inside nested braces/brackets/parens/quotes)
    def split_by_commas(s):
        parts = []
        current = []
        depth = 0
        in_string = None
        i = 0
        while i < len(s):
            c = s[i]
            if in_string:
                current.append(c)
                if c == '\\':
                    # Skip escaped character
                    if i + 1 < len(s):
                        current.append(s[i+1])
                        i += 1
                elif c == in_string:
                    in_string = None
            else:
                if c in ('"', "'"):
                    in_string = c
                    current.append(c)
                elif c in '{[(':
                    depth += 1
                    current.append(c)
                elif c in '}])':
                    depth -= 1
                    current.append(c)
                elif c == ',' and depth == 0:
                    parts.append(''.join(current))
                    current = []
                else:
                    current.append(c)
            i += 1
        if current:
            parts.append(''.join(current))
        return [p.strip() for p in parts]

    elements1 = split_by_commas(inner1)
    elements2 = split_by_commas(inner2)

    # Sort and compare
    return sorted(elements1) == sorted(elements2)


