def only_set_order_differs(s1: str, s2: str) -> bool:
    try:
        obj1 = ast.literal_eval(s1.strip())
        obj2 = ast.literal_eval(s2.strip())
    except (ValueError, SyntaxError):
        return False

    # Check if both are sets or both are dicts
    if isinstance(obj1, set) and isinstance(obj2, set):
        return obj1 == obj2
    elif isinstance(obj1, dict) and isinstance(obj2, dict):
        # Compare keys and values
        if set(obj1.keys()) != set(obj2.keys()):
            return False
        for key in obj1:
            if obj1[key] != obj2.get(key):
                return False
        return True
    else:
        return False


