from collections.abc import Iterable, Sequence


class conformance:
    @staticmethod
    def only_set_order_differs(s1: str, s2: str) -> bool:
        """Return True if two string representations differ only by the order of elements within sets."""
        import ast

        try:
            tree1 = ast.parse(s1.strip(), mode='eval')
            tree2 = ast.parse(s2.strip(), mode='eval')
        except SyntaxError:
            return False

        # Check that top-level expressions are sets or dicts with set values
        def is_set_or_dict_with_sets(node):
            if isinstance(node, ast.Set):
                return True
            elif isinstance(node, ast.Dict):
                # Check all values are sets or literals (not necessarily)
                return True
            return False

        def normalize(node):
            """Recursively normalize a node: sort set elements, keep dict structure but sort keys and set values."""
            if isinstance(node, ast.Set):
                # Sort the elements for canonical form
                els = sorted([ast.dump(el) for el in node.elts])
                return ('set', tuple(els))
            elif isinstance(node, ast.Dict):
                # Sort keys and normalize values
                items = []
                for key, val in zip(node.keys, node.values):
                    k = ast.dump(key)
                    v = normalize(val)
                    items.append((k, v))
                items.sort()
                return ('dict', tuple(items))
            else:
                return ast.dump(node)

        norm1 = normalize(tree1.body)
        norm2 = normalize(tree2.body)

        return norm1 == norm2


