def _dict_values_eq(v1, v2):
    if v1 is v2:
        return True
    it1 = iter(v1)
    it2 = iter(v2)
    while True:
        try:
            a = next(it1)
        except StopIteration:
            try:
                b = next(it2)
            except StopIteration:
                return True
            else:
                return False
        try:
            b = next(it2)
        except StopIteration:
            return False
        if a != b:
            return False

def _dict_keys_eq(k1, k2):
    if k1 is k2:
        return True
    keys1 = list(k1)
    keys2 = list(k2)
    s1 = set(keys1)
    s2 = set(keys2)
    if len(s1) != len(keys1) or len(s2) != len(keys2):
        return False
    for x in keys1:
        if x not in s2:
            return False
    for y in keys2:
        if y not in s1:
            return False
    return True

