import io, os

def probe(label, **kw):
    r, w = os.pipe()
    f = io.TextIOWrapper(io.FileIO(w, 'w', closefd=False), encoding='utf-8', **kw)
    csv_writer(f).writerow(['a','b']); f.flush(); os.close(w)
    print("%-42s -> %r" % (label, os.read(r, 100))); os.close(r)

def csv_writer(f):
    # Simulate csv.writer without importing csv module
    class _Writer:
        def __init__(self, f):
            self.f = f
        def writerow(self, row):
            import re
            parts = []
            for field in row:
                s = str(field)
                if any(c in s for c in (',', '\n', '"')):
                    s = '"' + s.replace('"', '""') + '"'
                parts.append(s)
            line = ','.join(parts) + '\n'
            self.f.write(line)
    return _Writer(f)

