import sys, json

# Re-implement the lypning module functionality
# Sighting and Entry classes with from_obj and to_obj methods

class Sighting:
    def __init__(self, **kwargs):
        self.data = kwargs

    @classmethod
    def from_obj(cls, obj):
        # Accept all keys, including unknown ones like "model"
        return cls(**obj)

    def to_obj(self):
        return self.data


class Entry:
    def __init__(self, **kwargs):
        self.id = kwargs.get("id")
        self.program = kwargs.get("program")
        self.count = kwargs.get("count", 0)
        self.first_seen = kwargs.get("first_seen")
        self.extra = {}
        for k, v in kwargs.items():
            if k not in ("id", "program", "count", "first_seen"):
                self.extra[k] = v

    @classmethod
    def from_obj(cls, obj):
        return cls(**obj)

    def to_obj(self):
        result = {
            "id": self.id,
            "program": self.program,
            "count": self.count,
            "first_seen": self.first_seen,
        }
        result.update(self.extra)
        return result

    def __eq__(self, other):
        if not isinstance(other, Entry):
            return False
        return (self.id == other.id and 
                self.program == other.program and 
                self.count == other.count and 
                self.first_seen == other.first_seen)
        # Note: extra is NOT compared in equality


def merge(list_a, list_b):
    """Merge two lists of Entries by id, keeping the first occurrence's data."""
    seen = {}
    result = []
    for entry in list_a + list_b:
        eid = entry.id
        if eid not in seen:
            seen[eid] = True
            result.append(entry)
    return result


