    _FIELDS = {"id", "program", "count", "first_seen"}

    def __init__(self, id=None, program=None, count=None, first_seen=None, **kwargs):
        self.id = id
        self.program = program
        self.count = count
        self.first_seen = first_seen
        extra = dict(kwargs)
        # Filter out known fields that were passed as kwargs
        for f in self._FIELDS:
            extra.pop(f, None)
        self.extra = extra

    @classmethod
    def from_obj(cls, obj):
        known = {k: v for k, v in obj.items() if k in cls._FIELDS}
        unknown = {k: v for k, v in obj.items() if k not in cls._FIELDS}
        return cls(**known, **unknown)

    def to_obj(self):
        d = {}
        if self.id is not None:
            d["id"] = self.id
        if self.program is not None:
            d["program"] = self.program
        if self.count is not None:
            d["count"] = self.count
        if self.first_seen is not None:
            d["first_seen"] = self.first_seen
        for k, v in self.extra.items():
            d[k] = v
        return d

    def __eq__(self, other):
        if not isinstance(other, Entry):
            return NotImplemented
        return (self.id == other.id and
                self.program == other.program and
                self.count == other.count and
                self.first_seen == other.first_seen)

    def __hash__(self):
        return hash((self.id, self.program, self.count, self.first_seen))


def merge(groups):
    """Merge list of lists of Entries. Collapses entries with equal (non-extra) fields."""
    result = []
    seen = set()
    for group in groups:
        for entry in group:
            h = hash(entry)
            if h not in seen:
                seen.add(h)
                result.append(entry)
    return result


