import json, re, os


def get_files(pattern: str):
    """Glob-like function that returns a sorted list of files matching the pattern."""
    # Simple implementation for patterns like "src/lypning/assets/*.jsonl"
    # We'll manually handle this specific case
    if not pattern.endswith("*.jsonl"):
        return []

    # Split directory and filename pattern
    last_slash = pattern.rfind("/")
    if last_slash == -1:
        dir_path = ""
        name_pattern = pattern
    else:
        dir_path = pattern[:last_slash]
        name_pattern = pattern[last_slash + 1:]

    if not name_pattern.startswith("*") or not name_pattern.endswith(".jsonl"):
        return []

    ext = ".jsonl"
    prefix = name_pattern[1:-len(ext)] if len(name_pattern) > 1 + len(ext) else ""

    results = []
    if not os.path.isdir(dir_path):
        return []

    for entry in os.listdir(dir_path):
        full_path = os.path.join(dir_path, entry)
        if not os.path.isfile(full_path):
            continue
        if not entry.endswith(ext):
            continue
        if prefix and not entry.startswith(prefix):
            continue
        results.append(full_path)

    return sorted(results)


