def sorted_glob(pattern):
    prefix = pattern.rfind("/*") + 1 if "/*" in pattern else -1
    if prefix < 0:
        return []
    d = pattern[:prefix]
    filename_prefix = pattern[prefix:]
    if not os.path.isdir(d):
        return []
    names = os.listdir(d)
    result = []
    for name in names:
        fullpath = d + "/" + name
        if name.startswith(filename_prefix):
            try:
                st = os.stat(fullpath)
            except OSError:
                continue
            import stat as _stat_mod
            if _stat_mod.S_ISREG(st.st_mode):
                result.append(fullpath)
    return sorted(result)


