import json, re, os, sys


def _is_file(path):
    try:
        st = os.stat(path)
    except OSError:
        return False
    # Simple check: not a directory; assume regular file if exists
    import stat as _stat
    return _stat.S_ISREG(st.st_mode)


def glob_jsonl(directory):
    try:
        entries = sorted(os.listdir(directory))
    except (OSError, FileNotFoundError):
        return []
    result = []
    for name in entries:
        full = directory + "/" + name
        if name.endswith(".jsonl") and _is_file(full):
            result.append(full)
    return result


