    s = obj_str.strip()
    if not (s.startswith("{") and s.endswith("}")):
        return None
    inner = s[1:-1]
    for key in keys:
        # Search for `"key":` or `'key':` pattern
        idx = 0
        while True:
            pos = inner.find('"' + key + '"', idx)
            if pos == -1:
                break
            # Check that this is a key (followed by colon)
            after = pos + len(key) + 2
            # Skip whitespace
            j = after
            while j < len(inner) and inner[j] in ' \t\n\r':
                j += 1
            if j < len(inner) and inner[j] == ':':
                j += 1
                while j < len(inner) and inner[j] in ' \t\n\r':
                    j += 1
                if j >= len(inner):
                    break
                c = inner[j]
                if c == '"':
                    # String value
                    k = j + 1
                    buf = []
                    escaped = False
                    while k < len(inner):
                        ch = inner[k]
                        if escaped:
                            if ch == 'n':
                                buf.append('\n')
                            elif ch == 't':
                                buf.append('\t')
                            elif ch == 'r':
                                buf.append('\r')
                            elif ch == '"':
                                buf.append('"')
                            elif ch == '\\':
                                buf.append('\\')
                            elif ch == '/':
                                buf.append('/')
                            elif ch == 'b':
                                buf.append('\b')
                            elif ch == 'f':
                                buf.append('\f')
                            else:
                                buf.append(ch)
                            escaped = False
                        elif ch == '\\':
                            escaped = True
                        elif ch == '"':
                            break
                        else:
                            buf.append(ch)
                        k += 1
                    return ''.join(buf)
                elif c == "'" :
                    # Single-quoted? Not standard JSON but handle anyway
                    k = j + 1
                    buf = []
                    escaped = False
                    while k < len(inner):
                        ch = inner[k]
                        if escaped:
                            if ch == 'n':
