                        elif ch == '\\':
                            escaped = True
                        elif ch == "'":
                            break
                        else:
                            buf.append(ch)
                        k += 1
                    return ''.join(buf)
                # non-string value; skip
                idx = j + 1
                continue
            idx = pos + 1
    return None

