                else:
                    i = len(ln) - len(stripped)
                    # Check import random
                    j = i
                    while j < len(src) and src[j] == ' ':
                        j += 1
                    # Now at start of token
                    if src.startswith("import ", j):
                        k = j + len("import ")
                        while k < len(src) and src[k] in (' ', '\t'):
                            k += 1
                        if src.startswith("random", k):
                            if k + len("random") >= len(src) or not (src[k+len("random")].isalnum() or src[k+len("random")] == '_'):
                                matched = True
                                break
                    elif src.startswith("from ", j):
                        k = j + len("from ")
                        while k < len(src) and src[k] in (' ', '\t'):
                            k += 1
                        if src.startswith("random", k):
