def parse_json_line(line):
    """Minimal JSON parser for object lines. Returns dict or None."""
    line = line.strip()
    if not line:
        return None
    if not (line.startswith('{') and line.endswith('}')):
        return None

    # Strip outer braces
    s = line[1:-1].strip()
    if not s:
        return {}

    result = {}
    i = 0
    n = len(s)

    def skip_ws(i):
        while i < n and s[i] in ' \t\r\n':
            i += 1
        return i

    def parse_value(i):
        i = skip_ws(i)
        if i >= n:
            return None, i
        ch = s[i]
        if ch == '"':
            return parse_string(i)
        elif ch == '{':
            return parse_object(i)
        elif ch == '[':
            return parse_array(i)
        elif ch == 't' and i+3 < n and s[i:i+4] == 'true':
            return True, i+4
        elif ch == 'f' and i+4 < n and s[i:i+5] == 'false':
            return False, i+5
        elif ch == 'n' and i+3 < n and s[i:i+4] == 'null':
            return None, i+4
        else:
            return parse_number(i)

    def parse_string(i):
        # i points to opening quote
        assert s[i] == '"'
        i += 1
        buf = []
        while i < n:
            c = s[i]
            if c == '\\':
                i += 1
                if i < n:
                    ec = s[i]
                    if ec == '"': buf.append('"')
                    elif ec == '\\': buf.append('\\')
                    elif ec == '/': buf.append('/')
                    elif ec == 'b': buf.append('\b')
                    elif ec == 'f': buf.append('\f')
                    elif ec == 'n': buf.append('\n')
                    elif ec == 'r': buf.append('\r')
                    elif ec == 't': buf.append('\t')
                    elif ec == 'u' and i+5 <= n:
                        hexs = s[i+1:i+5]
                        try:
                            code = int(hexs, 16)
                            buf.append(chr(code))
                            i += 4
                        except:
                            pass
                    i += 1
                    continue
            elif c == '"':
                return ''.join(buf), i+1
            else:
                buf.append(c)
                i += 1
        return ''.join(buf), i

    def parse_object(i):
        # i points to {
        i += 1
        obj = {}
        i = skip_ws(i)
        if i < n and s[i] == '}':
            return obj, i+1
        while i < n:
            i = skip_ws(i)
            if i >= n: break
            if s[i] != '"':
                i += 1
                continue
            key, i = parse_string(i)
            i = skip_ws(i)
            if i < n and s[i] == ':':
                i += 1
            val, i = parse_value(i)
            obj[key] = val
            i = skip_ws(i)
            if i < n and s[i] == ',':
                i += 1
            elif i < n and s[i] == '}':
                i += 1
                break
            else:
                break
        return obj, i

    def parse_array(i):
        i += 1
        arr = []
        i = skip_ws(i)
        if i < n and s[i] == ']':
            return arr, i+1
        while i < n:
            val, i = parse_value(i)
            arr.append(val)
            i = skip_ws(i)
            if i < n and s[i] == ',':
                i += 1
            elif i < n and s[i] == ']':
                i += 1
                break
            else:
                break
        return arr, i

    def parse_number(i):
        start = i
        while i < n and (s[i].isdigit() or s[i] in '-+.eE'):
            i += 1
        txt = s[start:i]
        try:
            if '.' in txt or 'e' in txt or 'E' in txt:
                return float(txt), i
            return int(txt), i
        except:
            return 0, i

    try:
        obj, _ = parse_object(i)
        return obj
    except Exception:
        return None


