def natural_key(path):
    parts = path.replace('\\', '/').split('/')
    def tok(s):
        out = []
        i = 0
        while i < len(s):
            ch = s[i]
            if ch.isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                out.append(('n', int(s[i:j])))
                i = j
            else:
                j = i
                while j < len(s) and not s[j].isdigit():
                    j += 1
                out.append(('s', s[i:j]))
                i = j
        return out
    key = []
    for p in parts:
        tk = tok(p)
        # separate numeric suffix from stem so that a.b.jsonl sorts naturally
        last_num_suffix = None
        has_stem = False
        for t in tk:
            if t[0] == 'n' and (not has_stem or last_num_suffix is None):
                if not has_stem:
                    key.append(t)
                    last_num_suffix = t
                elif t[1] > last_num_suffix[1]:
                    last_num_suffix = t
            else:
                key.append(t)
                has_stem = True
        if last_num_suffix is not None and has_stem:
            key.append(last_num_suffix)
    return key

