        if c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == '"':
            return parse_string()
        elif c == 't':
            # true
            if s[i:i+4] == 'true':
                i += 4
                return True
            else:
                raise ValueError("bad literal")
        elif c == 'f':
            # false
            if s[i:i+5] == 'false':
                i += 5
                return False
            else:
                raise ValueError("bad literal")
        elif c == 'n':
            # null
            if s[i:i+4] == 'null':
                i += 4
                return None
            else:
                raise ValueError("bad literal")
        else:
            return parse_number()

    def parse_string():
        nonlocal i
        assert s[i] == '"'
        i += 1
        result = []
        while i < n:
            c = s[i]
            if c == '\\':
                i += 1
                if i >= n:
                    raise ValueError("bad escape")
                esc = s[i]
                if esc == '"':
                    result.append('"')
                elif esc == '\\':
                    result.append('\\')
                elif esc == '/':
                    result.append('/')
                elif esc == 'b':
                    result.append('\b')
                elif esc == 'f':
                    result.append('\f')
                elif esc == 'n':
                    result.append('\n')
                elif esc == 'r':
                    result.append('\r')
                elif esc == 't':
                    result.append('\t')
                elif esc == 'u':
                    # unicode escape
                    hexs = s[i+1:i+5]
                    if len(hexs) != 4:
                        raise ValueError("bad unicode escape")
