import os, sys

def glob_jsonl(pattern):
    """Recursively find .jsonl files using os.scandir."""
    results = []
    if not os.path.isdir(pattern[:-len('**/*.jsonl')]):
        return results
    base = pattern[:-(len('**/*.jsonl'))]
    def walk(d):
        try:
            entries = list(os.scandir(d))
        except OSError:
            return
        for e in entries:
            if e.is_dir():
                if not e.name.startswith('.'):
                    walk(e.path)
            elif e.name.endswith('.jsonl'):
                results.append(e.path)
    walk(base)
    return results

