    # Skip whitespace and colon
    while after < len(line) and line[after] in ' ':
        after += 1
    if after >= len(line) or line[after] != ':':
        return None
    after += 1
    while after < len(line) and line[after] in ' ':
        after += 1
    if after >= len(line):
        return None
    ch = line[after]
    if ch == '"':
        # String value
        start = after + 1
        i = start
        while i < len(line):
            if line[i] == '\\':
                i += 2
                continue
            if line[i] == '"':
                break
            i += 1
        if i >= len(line):
            return None
        val = line[start:i]
        # Unescape basic escapes
        val = val.replace('\\"', '"').replace('\\n', '\n').replace('\\t', '\t').replace('\\\\', '\\')
        return val
    elif ch == 't' and line[after:after+4] == 'true':
        return True
    elif ch == 'f' and line[after:after+5] == 'false':
        return False
    elif ch == 'n' and line[after:after+4] == 'null':
        return None
    else:
        # Number or object/array - not what we need
        if ch in '{[':
            return 'object_or_array'
        # Try to read a number
        end = after
        while end < len(line) and line[end] not in ',}]\n':
            end += 1
        s = line[after:end].strip()
        try:
            return int(s)
        except:
            try:
                return float(s)
            except:
                return s

    return None

