import json, glob, collections, os

def _defaultdict(factory=None):
    class _DD(dict):
        def __init__(self, f=None, *a, **kw):
            super().__init__(*a, **kw)
            self._factory = f if f is not None else factory
        def __missing__(self, key):
            if self._factory is None:
                raise KeyError(key)
            v = self._factory()
            self[key] = v
            return v
    return _DD

