def json_loads_minimal(s):
    """Minimal JSON parser for the specific structure needed."""
    # This needs to handle nested objects, arrays, strings, numbers, booleans, null
    i = 0
    n = len(s)

    def skip_ws():
        nonlocal i
        while i < n and s[i] in ' \t\n\r':
            i += 1

    def parse_value():
        nonlocal i
        skip_ws()
        if i >= n:
            raise ValueError("unexpected end")
        c = s[i]
        if c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == '"':
            return parse_string()
        elif c in '-0123456789':
            return parse_number()
        elif s[i:i+4] == 'true':
            i += 4
            return True
        elif s[i:i+5] == 'false':
            i += 4 + 1
            return False
        elif s[i:i+4] == 'null':
            i += 4
            return None
        else:
            raise ValueError(f"unexpected char {c!r} at pos {i}")

    def parse_object():
        nonlocal i
        assert s[i] == '{'
        i += 1
        obj = {}
        skip_ws()
        if i < n and s[i] == '}':
            i += 1
            return obj
        while True:
            skip_ws()
            if i < n and s[i] == '"':
                key = parse_string()
            else:
                raise ValueError("expected string key")
            skip_ws()
            if i < n and s[i] == ':':
                i += 1
            else:
                raise ValueError("expected colon")
            val = parse_value()
            obj[key] = val
            skip_ws()
            if i < n and s[i] == ',':
                i += 1
            elif i < n and s[i] == '}':
                i += 1
                break
            else:
                raise ValueError("expected comma or closing brace")
        return obj

    def parse_array():
        nonlocal i
        assert s[i] == '['
        i += 1
        arr = []
        skip_ws()
        if i < n and s[i] == ']':
            i += 1
            return arr
        while True:
            val = parse_value()
            arr.append(val)
            skip_ws()
            if i < n and s[i] == ',':
                i += 1
            elif i < n and s[i] == ']':
                i += 1
                break
            else:
                raise ValueError("expected comma or closing bracket")
        return arr

    def parse_string():
        nonlocal i
        assert s[i] == '"'
        i += 1
        chars = []
        while i < n:
            c = s[i]
            if c == '\\':
                i += 1
                if i >= n:
                    break
                esc = s[i]
                if esc == '"':
                    chars.append('"')
                elif esc == '\\':
                    chars.append('\\')
                elif esc == '/':
                    chars.append('/')
                elif esc == 'b':
                    chars.append('\b')
                elif esc == 'f':
                    chars.append('\f')
                elif esc == 'n':
                    chars.append('\n')
                elif esc == 'r':
                    chars.append('\r')
                elif esc == 't':
                    chars.append('\t')
                elif esc == 'u':
                    hex_str = s[i+1:i+5]
                    try:
                        code_point = int(hex_str, 16)
                        chars.append(chr(code_point))
                        i += 4
                    except:
                        chars.append('')
                else:
                    chars.append(esc)
                i += 1
            elif c == '"':
                i += 1
                break
            else:
                chars.append(c)
                i += 1
        return ''.join(chars)

    def parse_number():
