        except:
            return num_str

    result = parse_value()
    return result


def list_jsonl_files(root):
    """Recursively list all .jsonl files under root."""
    results = []
    try:
        entries = sorted(os.scandir(root), key=lambda e: e.name)
    except OSError:
        return results
    for entry in entries:
        try:
            if entry.is_dir(follow_symlinks=True):
                results.extend(list_jsonl_files(entry.path))
            elif entry.is_file(follow_symlinks=True) and entry.name.endswith('.jsonl'):
                results.append(entry.path)
        except OSError:
            pass
    return results


