def walk_recursive(directory):
    """Yield all files recursively (non-recursive glob replacement)."""
    stack = [directory]
    while stack:
        d = stack.pop()
        try:
            entries = sorted(os.listdir(d))
        except OSError:
            continue
        for entry in entries:
            full = os.path.join(d, entry)
            try:
                if os.path.isdir(full):
                    stack.append(full)
                elif os.path.isfile(full):
                    yield full
            except OSError:
                continue

