    start += 1  # skip {
    start = _skip_ws(s, start)
    if start >= len(s):
        raise ValueError("unterminated object")
    if s[start] == '}':
        return obj, start + 1
    while True:
        start = _skip_ws(s, start)
        if start >= len(s):
            raise ValueError("unterminated object")
        if s[start] != '"':
            raise ValueError("expected key string")
        key, start = _parse_string(s, start)
        start = _skip_ws(s, start)
        if start >= len(s) or s[start] != ':':
            raise ValueError("expected colon")
        start += 1
        start = _skip_ws(s, start)
        val, start = _parse_value_at(s, start)
        obj[key] = val
        start = _skip_ws(s, start)
        if start >= len(s):
            raise ValueError("unterminated object")
        if s[start] == ',':
            start += 1
            continue
        elif s[start] == '}':
            return obj, start + 1
        else:
            raise ValueError("expected , or }")

def _parse_array(s, start):
    arr = []
    start += 1  # skip [
    start = _skip_ws(s, start)
    if start >= len(s):
        raise ValueError("unterminated array")
    if s[start] == ']':
        return arr, start + 1
    while True:
        start = _skip_ws(s, start)
        val, start = _parse_value_at(s, start)
        arr.append(val)
        start = _skip_ws(s, start)
        if start >= len(s):
            raise ValueError("unterminated array")
        if s[start] == ',':
            start += 1
            continue
        elif s[start] == ']':
            return arr, start + 1
        else:
            raise ValueError("expected , or ]")

def _parse_string(s, start):
    """Parse a JSON string starting at start (which should be '"'). Returns (str, end_pos)."""
    if s[start] != '"':
        raise ValueError("expected string")
    start += 1
    result = []
    while start < len(s):
        c = s[start]
        if c == '\\':
            start += 1
            if start >= len(s):
                break
            esc = s[start]
            if esc == '"':
                result.append('"')
            elif esc == '\\':
                result.append('\\')
            elif esc == '/':
                result.append('/')
            elif esc == 'b':
                result.append('\b')
            elif esc == 'f':
                result.append('\f')
            elif esc == 'n':
                result.append('\n')
            elif esc == 'r':
                result.append('\r')
            elif esc == 't':
                result.append('\t')
            elif esc == 'u':
                if start + 4 < len(s):
                    hexs = s[start+1:start+5]
                    try:
