                        result.append(chr(code))
                    except ValueError:
                        result.append('?')
                    start += 4
                else:
                    result.append('?')
            else:
                result.append(esc)
            start += 1
        elif c == '"':
            start += 1
            return ''.join(result), start
        else:
            result.append(c)
            start += 1
    raise ValueError("unterminated string")

def _skip_ws(s, pos):
    while pos < len(s) and s[pos] in (' ', '\t', '\n', '\r'):
        pos += 1
    return pos

def _parse_value_at(s, start):
    """Parse a JSON value at position start. Returns (value, next_pos)."""
    start = _skip_ws(s, start)
    if start >= len(s):
        raise ValueError("end of input")
