def _skip_ws(s, i):
    while i < len(s) and s[i] in ' \t\n\r':
        i += 1
    return i


def _parse_value(s, i):
    i = _skip_ws(s, i)
    if i >= len(s):
        return None, i
    ch = s[i]
    if ch == '{':
        return _parse_object(s, i)
    elif ch == '[':
        return _parse_array(s, i)
    elif ch == '"':
        return _parse_string(s, i)
    elif ch == 't':
        return True, i + 4  # true
    elif ch == 'f':
        return False, i + 5  # false
    elif ch == 'n':
        return None, i + 4  # null
    else:
        return _parse_number(s, i)


def _parse_string(s, i):
    # s[i] == '"'
    i += 1
    result = []
    while i < len(s):
        ch = s[i]
        if ch == '\\':
            i += 1
            if i < len(s):
                esc = s[i]
                if esc == '"':
                    result.append('"')
                elif esc == '\\':
                    result.append('\\')
                elif esc == '/':
                    result.append('/')
                elif esc == 'b':
                    result.append('\b')
                elif esc == 'f':
                    result.append('\f')
                elif esc == 'n':
                    result.append('\n')
                elif esc == 'r':
                    result.append('\r')
                elif esc == 't':
                    result.append('\t')
                elif esc == 'u':
                    hex4 = s[i+1:i+5]
                    try:
                        cp = int(hex4, 16)
                        result.append(chr(cp))
                    except (ValueError, OverflowError):
                        result.append('\ufffd')
                    i += 4
                else:
                    result.append(esc)
            i += 1
        elif ch == '"':
            i += 1
            break
        else:
            result.append(ch)
            i += 1
    return ''.join(result), i


def _parse_number(s, i):
    start = i
    if i < len(s) and s[i] == '-':
        i += 1
    while i < len(s) and s[i].isdigit():
        i += 1
    is_float = False
    if i < len(s) and s[i] == '.':
        is_float = True
        i += 1
        while i < len(s) and s[i].isdigit():
            i += 1
    if i < len(s) and s[i] in 'eE':
        is_float = True
        i += 1
        if i < len(s) and s[i] in '+-':
            i += 1
        while i < len(s) and s[i].isdigit():
            i += 1
    num_str = s[start:i]
    if is_float:
        try:
            return float(num_str), i
        except ValueError:
            return 0, i
    else:
        try:
            return int(num_str), i
        except ValueError:
            return 0, i


def _parse_object(s, i):
    i += 1  # skip {
    obj = {}
    i = _skip_ws(s, i)
    if i < len(s) and s[i] == '}':
        return obj, i + 1
    while i < len(s):
        key, i = _parse_string(s, i)
        i = _skip_ws(s, i)
        if i < len(s) and s[i] == ':':
            i += 1
        val, i = _parse_value(s, i)
        obj[key] = val
        i = _skip_ws(s, i)
        if i < len(s) and s[i] == ',':
            i += 1
        elif i < len(s) and s[i] == '}':
            i += 1
            break
        else:
            break
    return obj, i


def _parse_array(s, i):
    i += 1  # skip [
    arr = []
    i = _skip_ws(s, i)
    if i < len(s) and s[i] == ']':
        return arr, i + 1
    while i < len(s):
        val, i = _parse_value(s, i)
        arr.append(val)
        i = _skip_ws(s, i)
        if i < len(s) and s[i] == ',':
            i += 1
        elif i < len(s) and s[i] == ']':
            i += 1
            break
        else:
            break
    return arr, i


