class Counter:
    def __init__(self):
        self._d = {}

    def __setitem__(self, k, v):
        self._d[k] = v

    def __getitem__(self, k):
        return self._d.get(k, 0)

    def __contains__(self, k):
        return k in self._d

    def increment(self, k, n=1):
        self._d[k] = self._d.get(k, 0) + n

    def items(self):
        return self._d.items()

    def most_common(self):
        return sorted(self._d.items(), key=lambda x: (-x[1], x[0]))

    def __len__(self):
        return len(self._d)

    def __eq__(self, other):
        return isinstance(other, Counter) and self._d == other._d

    def __repr__(self):
        return repr(dict(self._d))


