import os, sys

def parse_json(s):
    s = s.strip()
    return _parse_value(_TokenStream(s))

class _TokenStream:
    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)
    def peek(self):
        while self.i < self.n and self.s[self.i] in ' \t\r\n':
            self.i += 1
        if self.i >= self.n:
            return None
        return self.s[self.i]
    def next_char(self):
        c = self.peek()
        if c is not None:
            self.i += 1
        return c
    def expect(self, ch):
        c = self.next_char()
        if c != ch:
            raise ValueError(f"Expected {ch}, got {c}")

def _parse_value(ts):
    c = ts.peek()
    if c == '{':
        return _parse_object(ts)
    elif c == '[':
        return _parse_array(ts)
    elif c == '"':
        return _parse_string(ts)
    elif c == 't':
        ts.expect('t'); ts.expect('r'); ts.expect('u'); ts.expect('e')
        return True
    elif c == 'f':
        ts.expect('f'); ts.expect('a'); ts.expect('l'); ts.expect('s'); ts.expect('e')
        return False
    elif c == 'n':
        ts.expect('n'); ts.expect('u'); ts.expect('l'); ts.expect('l')
        return None
    else:
        return _parse_number(ts)

def _parse_object(ts):
    ts.expect('{')
    obj = {}
    if ts.peek() == '}':
        ts.next_char()
        return obj
    while True:
        key = _parse_string(ts)
        ts.expect(':')
        val = _parse_value(ts)
        obj[key] = val
        c = ts.next_char()
        if c == '}':
            break
        elif c == ',':
            continue
        else:
            raise ValueError(f"Unexpected {c}")
    return obj

def _parse_array(ts):
    ts.expect('[')
    arr = []
    if ts.peek() == ']':
        ts.next_char()
        return arr
    while True:
        val = _parse_value(ts)
        arr.append(val)
        c = ts.next_char()
        if c == ']':
            break
        elif c == ',':
            continue
        else:
            raise ValueError(f"Unexpected {c}")
    return arr

def _parse_string(ts):
    ts.expect('"')
    chars = []
    while True:
        c = ts.s[ts.i]
        ts.i += 1
        if c == '\\':
            nc = ts.s[ts.i]
            ts.i += 1
            if nc == '"': chars.append('"')
            elif nc == '\\': chars.append('\\')
            elif nc == '/': chars.append('/')
            elif nc == 'b': chars.append('\b')
            elif nc == 'f': chars.append('\f')
            elif nc == 'n': chars.append('\n')
            elif nc == 'r': chars.append('\r')
            elif nc == 't': chars.append('\t')
            elif nc == 'u':
                hexs = ts.s[ts.i:ts.i+4]
                ts.i += 4
                chars.append(chr(int(hexs, 16)))
            else:
                raise ValueError(f"Bad escape \\{nc}")
        elif c == '"':
            break
        else:
            chars.append(c)
    return ''.join(chars)

def _parse_number(ts):
    start = ts.i
    if ts.peek() == '-':
        ts.i += 1
    while ts.i < ts.n and (ts.s[ts.i].isdigit()):
        ts.i += 1
    if ts.i < ts.n and ts.s[ts.i] == '.':
        ts.i += 1
        while ts.i < ts.n and (ts.s[ts.i].isdigit()):
            ts.i += 1
    if ts.i < ts.n and ts.s[ts.i] in 'eE':
        ts.i += 1
        if ts.i < ts.n and ts.s[ts.i] in '+-':
            ts.i += 1
        while ts.i < ts.n and ts.s[ts[i]].isdigit():
            ts.i += 1
    num_str = ts.s[start:ts.i]
    if '.' in num_str or 'e' in num_str or 'E' in num_str:
        return float(num_str)
    return int(num_str)

def walk_jsonl(root):
    result = []
    if not os.path.exists(root):
        return result
    for dirpath, dirnames, filenames in os.walk(root):
        for fn in filenames:
            if fn.endswith('.jsonl'):
                result.append(os.path.join(dirpath, fn))
    return sorted(result)

