        try:
            entries = os.listdir(d)
        except OSError:
            return
        for e in entries:
            fp = os.path.join(d, e)
            if os.path.isdir(fp):
                _walk(fp)
            elif e.endswith('.jsonl'):
                files.append(fp)

    _walk(root_dir)
    files.sort()

    # Determine "top" level: depth matching the number of '/' in root_dir + 1
    n_slashes_root = root_dir.count('/')
    top = [f for f in files if f.count('/') == n_slashes_root + 1]

    print("total jsonl:", len(files))

    c = {}       # model -> count (all)
    ctop = {}    # model -> count (top-level files only)
    csub = {}    # model -> count (subagent files only)
    persess = {} # file -> {model: count}
    side = 0

    for f in files:
        sub = '/subagents/' in f
        try:
            with open(f, 'r', errors='replace') as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        o = _parse_json_line(line)
                    except Exception:
                        continue
                    if o.get('type') != 'assistant':
                        continue
                    m = o.get('message')
                    if not isinstance(m, dict):
                        continue
                    mod = m.get('model')
                    if not mod:
                        continue
                    c[mod] = c.get(mod, 0) + 1
                    tgt = csub if sub else ctop
                    tgt[mod] = tgt.get(mod, 0) + 1
                    fc = persess.setdefault(f, {})
                    fc[mod] = fc.get(mod, 0) + 1
                    if o.get('isSidechain'):
                        side += 1
        except Exception:
            pass

    print("=== ALL message.model values ===")
    for k, v in sorted(c.items(), key=lambda x: (-x[1], x[0])):
        print("{:8d}  {}".format(v, k))

    print("=== main-transcript only ===")
    for k, v in sorted(ctop.items(), key=lambda x: (-x[1], x[0])):
        print("{:8d}  {}".format(v, k))

    print("=== subagent files only ===")
    for k, v in sorted(csub.items(), key=lambda x: (-x[1], x[0])):
        print("{:8d}  {}".format(v, k))

    print("isSidechain=true assistant records:", side)

    print("=== per-file model mixes (files with >1) ===")
