import os, sys

def glob_jsonl(base):
    # recursive walk to collect .jsonl files under base (non-recursive glob is not available without the glob module)
    results = []
    for root, dirs, fnames in os.walk(base):
        for name in fnames:
            if name.endswith('.jsonl'):
                results.append(os.path.join(root, name))
    return results

