import os

def expand_user(p):
    if p and (p == '~' or p.startswith('~/') or p.startswith('~\\')):
        home = os.environ.get('HOME', '')
        return os.path.join(home, p[2:]) if len(p) > 1 else home
    return p

def find_all_files(root):
    out = []
    try:
        entries = os.listdir(root)
    except OSError:
        return out
    for name in entries:
        full = root + '/' + name
        is_dir = False
        try:
            is_dir = os.path.isdir(full)
        except OSError:
            pass
        if is_dir:
            out.extend(find_all_files(full))
        elif name.endswith('.jsonl'):
            out.append(full)
    return out

def json_loads(s):
    """Minimal JSON parser compatible with the subset of JSON we need."""
    # Try a recursive-descent parser.
    import re
    idx = [0]
    n = len(s)

    def skip_ws():
        while idx[0] < n and s[idx[0]] in ' \t\n\r':
            idx[0] += 1

    def parse_value():
        skip_ws()
        if idx[0] >= n:
            raise ValueError("unexpected end")
        c = s[idx[0]]
        if c == '{':
            return parse_object()
        elif c == '[':
            return parse_array()
        elif c == '"':
            return parse_string()
        elif c in ('t', 'f'):
            if s[idx[0]:idx[0]+4] == 'true':
                idx[0] += 4
                return True
            elif s[idx[0]:idx[0]+5] == 'false':
                idx[0] += 5
                return False
            else:
                raise ValueError("bad literal")
        elif c == 'n':
            if s[idx[0]:idx[0]+4] == 'null':
                idx[0] += 4
                return None
            else:
                raise ValueError("bad literal")
        else:
            return parse_number()

    def parse_string():
        assert s[idx[0]] == '"'
        idx[0] += 1
        buf = []
        while idx[0] < n:
            c = s[idx[0]]
            if c == '\\':
                idx[0] += 1
                if idx[0] >= n:
                    raise ValueError("bad escape")
                e = s[idx[0]]
                if e == 'n':
                    buf.append('\n')
                elif e == 't':
                    buf.append('\t')
                elif e == 'r':
                    buf.append('\r')
                elif e == '"':
                    buf.append('"')
                elif e == '\\':
                    buf.append('\\')
                elif e == '/':
                    buf.append('/')
                elif e == 'b':
                    buf.append('\b')
                elif e == 'f':
                    buf.append('\f')
                elif e == 'u':
                    idx[0] += 4
                    hexstr = s[idx[0]-3:idx[0]+1]
                    try:
                        code = int(hexstr, 16)
                    except:
                        raise ValueError("bad unicode escape")
                    buf.append(chr(code))
                    continue
                else:
                    raise ValueError("bad escape char")
                idx[0] += 1
            elif c == '"':
                idx[0] += 1
                break
            else:
                buf.append(c)
                idx[0] += 1
        return ''.join(buf)

    def parse_object():
        assert s[idx[0]] == '{'
        idx[0] += 1
        obj = {}
        skip_ws()
        if idx[0] < n and s[idx[0]] == '}':
            idx[0] += 1
            return obj
        while True:
            skip_ws()
            if idx[0] >= n or s[idx[0]] != '"':
                raise ValueError("expected string key")
            key = parse_string()
            skip_ws()
            if idx[0] >= n or s[idx[0]] != ':':
                raise ValueError("expected colon")
            idx[0] += 1
            val = parse_value()
            obj[key] = val
            skip_ws()
            if idx[0] >= n:
                raise ValueError("unexpected end in object")
            c = s[idx[0]]
            if c == ',':
                idx[0] += 1
            elif c == '}':
                idx[0] += 1
                return obj
            else:
                raise ValueError("expected , or } in object")

    def parse_array():
        assert s[idx[0]] == '['
        idx[0] += 1
        arr = []
        skip_ws()
        if idx[0] < n and s[idx[0]] == ']':
            idx[0] += 1
            return arr
        while True:
            val = parse_value()
            arr.append(val)
            skip_ws()
            if idx[0] >= n:
                raise ValueError("unexpected end in array")
            c = s[idx[0]]
            if c == ',':
                idx[0] += 1
            elif c == ']':
                idx[0] += 1
                return arr
            else:
                raise ValueError("expected , or ] in array")

    def parse_number():
        start = idx[0]
        while idx[0] < n and s[idx[0]] not in ' \t\n\r,}]':
            idx[0] += 1
        tok = s[start:idx[0]]
        try:
            return float(tok) if ('.' in tok or 'e' in tok or 'E' in tok) else int(tok)
        except:
            raise ValueError("bad number: " + tok)

    result = parse_value()
    skip_ws()
    return result


