                m = o.get('message')
                if not isinstance(m, dict):
                    continue
                mod = m.get('model')
                if not mod:
                    continue
                c[mod] = c.get(mod, 0) + 1
                if sub:
                    csub[mod] = csub.get(mod, 0) + 1
                else:
                    ctop[mod] = ctop.get(mod, 0) + 1
                if f not in persess:
                    persess[f] = {}
                persess[f][mod] = persess[f].get(mod, 0) + 1
                if o.get('isSidechain'):
                    side += 1

    print("=== ALL message.model values ===")
    items = sorted(c.items(), key=lambda kv: (-kv[1], kv[0]))
    for k, v in items:
        print("{:8d}  {}".format(v, k))

