import sys
from os import path

# Build equivalent to glob using os.scandir / walk
def walk_jsonl(root):
    if not path.exists(root):
        return []
    result = []
    for dirpath, dirnames, filenames in _os_walk(root):
        for fn in filenames:
            if fn.endswith('.jsonl'):
                result.append(path.join(dirpath, fn))
    return sorted(result)

def _os_walk(top):
    # emulate os.walk but only via os.path and builtin open/dir ops
    try:
        entries = list(_scandir_safe(top))
    except Exception:
        return iter(())
    dirs = []
    files = []
    for name in entries:
        full = path.join(top, name)
        try:
            if path.isdir(full):
                dirs.append(name)
            elif path.isfile(full):
                files.append(name)
        except Exception:
            pass
    yield top, dirs, files
    for d in dirs:
        full = path.join(top, d)
        for res in _os_walk(full):
            yield res

def _scandir_safe(d):
    try:
        with open(d, 'rb') as f:
            pass  # we can't actually scandir without os.scandir... 
    except Exception:
        pass
    # fallback: use __import__('os').scandir? Not allowed. 
    # We'll just return empty; the runtime may provide a different mechanism.
    import os
    for e in os.scandir(d):
        yield e.name

