# Pre-compute repr for strings without calling repr() on problematic ones
def str_repr(s):
    if not s:
        return "''"
    # Determine if we can use single or double quotes
    has_single = "'" in s
    has_double = '"' in s

    # Use single quotes unless string contains a single quote and doesn't contain a double
    if has_single and not has_double:
        quote = '"'
    else:
        quote = "'"

    result = quote
    for ch in s:
        c = ord(ch)
        if ch == '\\' or ch == quote:
            result += '\\' + ch
        elif c < 32 or (c >= 127 and c < 160):
            # Need to escape control chars and some others
            if ch == '\n':
                result += '\\n'
            elif ch == '\t':
                result += '\\t'
            elif ch == '\r':
                result += '\\r'
            elif ch == '\v':
                result += '\\v'
            elif ch == '\f':
                result += '\\f'
            else:
                # Use \xNN for other control/special chars
                result += '\\x%02x' % c
        elif c == 0x85:
            result += '\\x85'
        else:
            result += ch
    result += quote
    return result

