def bytes_repr(b):
    if len(b) == 0:
        return "b''"
    # Determine quote style
    has_single = b'\'' in b
    has_double = b'"' in b
    if has_single and not has_double:
        quote = '"'
    else:
        quote = "'"
    result = 'b' + quote
    for byte in b:
        c = byte
        if byte == 0x27 or byte == 0x22:
            result += '\\' + chr(byte)
        elif c < 32:
            if c == 0x09:
                result += '\\t'
            elif c == 0x0A:
                result += '\\n'
            elif c == 0x0D:
                result += '\\r'
            elif c == 0x0C:
                result += '\\f'
            elif c == 0x0B:
                result += '\\v'
            else:
                result += '\\x%02x' % c
        elif c == 0x5c:
            result += '\\\\'
        elif c >= 127:
            result += '\\x%02x' % c
        else:
