def container_repr(obj):
    # Handle containers safely by building them up from parts
    if isinstance(obj, list):
        if not obj:
            return "[]"
        items = []
        for item in obj:
            items.append(container_repr(item))
        return "[" + ", ".join(items) + "]"
    elif isinstance(obj, tuple):
        if not obj:
            return "()"
        if len(obj) == 1:
            return "(" + container_repr(obj[0]) + ",)"
        items = []
        for item in obj:
            items.append(container_repr(item))
        return "(" + ", ".join(items) + ")"
    elif isinstance(obj, dict):
        if not obj:
            return "{}"
        items = []
        for k, v in obj.items():
            items.append(container_repr(k) + ": " + container_repr(v))
        return "{" + ", ".join(items) + "}"
    elif isinstance(obj, bytes):
        return bytes_repr(obj)
    elif isinstance(obj, float):
        return float_repr(obj)
    elif isinstance(obj, int):
        return repr(obj)
    elif obj is None:
        return "None"
    elif obj is True:
        return "True"
    elif obj is False:
        return "False"
    elif isinstance(obj, str):
        return str_repr(obj)
    else:
        return repr(obj)

