    # Actually let's just compute it directly for the problematic character
    # When repr() encounters U+0085, Python's unicode tables determine printability
    # In CPython, U+0085 is considered printable (it's NEL - Next Line), so repr outputs it as-is
    # Wait, actually let me think more carefully...
    # U+0085 (NEL) - in Python 3, is it printable? 
    # Let me check: '\u0085'.isprintable() -> False in Python 3
    # So repr would output it as \u0085

    # But the issue is that the runtime refuses to call repr on a string containing U+0085
    # because it needs CPython's unicode tables to determine printability.

    # We need to manually compute what repr would produce for strings containing U+0085

    # Strategy: if the string contains \u0085, we'll build the repr manually
    # Otherwise, use repr() normally

    if '\u0085' not in s:
        return r

    # For strings with \u0085, build repr manually
    # First determine quote style
    has_single = "'" in s
    has_double = '"' in s

    if has_single and not has_double:
        quote = '"'
    else:
        quote = "'"

    result = [quote]
    for ch in s:
        c_ord = ord(ch)
        if ch == '\\' or (ch == quote):
            result.append('\\')
            result.append(ch)
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
            result.append('\\t')
        elif ch == '\v':
            result.append('\\v')
        elif ch == '\f':
            result.append('\\f')
        elif c_ord < 0x20 or c_ord >= 0x7f and not ch.isprintable():
            # Need to escape
            if c_ord <= 0xff:
                result.append('\\x%02x' % c_ord)
            elif c_ord <= 0xffff:
                result.append('\\u%04x' % c_ord)
            else:
                result.append('\\U%08x' % c_ord)
        else:
            result.append(ch)
    result.append(quote)
    return ''.join(result)


