def _make_iter(val):
    if isinstance(val, (list, tuple, str, bytes)):
        return iter(val)
    elif isinstance(val, range):
        return iter(val)
    elif isinstance(val, dict):
        return iter(val)
    elif isinstance(val, set) or isinstance(val, frozenset):
        return iter(val)
    elif val.__class__.__name__ == 'dict_keys':
        return iter(val)
    elif val.__class__.__name__ == 'dict_values':
        return iter(val)
    elif val.__class__.__name__ == 'dict_items':
        return iter(val)
    else:
        # For generators, enumerate, map, zip, filter, and other iterators
        try:
            r = val[::-1]
            return reversed(r)
        except TypeError:
            pass
        # If it's an iterator, consume it
        try:
            items = list(val)
            return reversed(items)
        except Exception as e:
            raise

